INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苹果", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“她是一位苹果”。"}, {"text": "研究员", "is_correct": true, "explanation": "“一位研究员”指从事研究工作的专业人员，与主语“她”和量词“位”都相符。"}, {"text": "老爷", "is_correct": false, "explanation": "语域：“老爷”是旧时对地主、官员的敬称，现代介绍职业时不用。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“一位桌子”。"}], "explanations": {"苹果": "搭配：量词“位”只用于人，不能说“她是一位苹果”。", "研究员": "“一位研究员”指从事研究工作的专业人员，与主语“她”和量词“位”都相符。", "老爷": "语域：“老爷”是旧时对地主、官员的敬称，现代介绍职业时不用。", "桌子": "搭配：量词“位”只用于人，不能说“一位桌子”。"}, "sentence_index": 0, "correct_answer": "研究员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥在研究员工作。", "explanation": "这里应该用〈研究所〉。研究员指人，表示工作地点要说“研究所”，不能说“在研究员工作”。"}, {"text": "我们公司来了一只研究员。", "explanation": "这里应该用〈位〉或〈名〉。研究员指人，量词要用“位”或“名”，“只”多用于动物或物件。"}, {"text": "我表弟正在读研究员。", "explanation": "这里应该用〈研究生〉。“读”后接的是在校学习的对象，研究员是已经工作的专业人员，应说“读研究生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究员", "is_correct": true, "explanation": "“一位研究员”来讲课，符合“公司请了……来给大家讲课”的语境。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能讲课；量词“位”只用于人。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不能讲课；量词“位”只用于人，不能说“一位黑板”。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“一位鱼”。"}], "explanations": {"研究员": "“一位研究员”来讲课，符合“公司请了……来给大家讲课”的语境。", "椅子": "语义：椅子不能讲课；量词“位”只用于人。", "黑板": "语义：黑板不能讲课；量词“位”只用于人，不能说“一位黑板”。", "鱼": "搭配：量词“位”只用于人，不能说“一位鱼”。"}, "sentence_index": 6, "correct_answer": "研究员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位研究员在餐厅负责给客人端菜。", "explanation": "这里应该用〈服务员〉。在餐厅端菜招待客人的是服务员，研究员从事研究工作，不做这类服务。"}, {"text": "那位研究员每天给病人打针。", "explanation": "这里应该用〈护士〉。给病人打针的是护士，研究员从事研究工作，不做护理工作。"}, {"text": "那个研究员每天早上去菜市场卖菜。", "explanation": "这里应该用〈菜贩〉。去菜市场卖菜的是菜贩，研究员从事研究工作，不做买卖蔬菜的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一位很有名研究员。", "corrected_sentence": "他是一位很有名的研究员。", "error_description": "“很有名”修饰名词时中间要加“的”，应为“很有名的研究员”；漏掉“的”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我父亲年轻时当过一只研究员。", "corrected_sentence": "我父亲年轻时当过一名研究员。", "error_description": "“研究员”指人，量词应用“名”或“位”，不能用“只”；“当过一只研究员”应为“当过一名研究员”，这是把动物量词套用到人身上的常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
