INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92421, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "发音是嘴里说出的字的声音。", "primary_collocate": null, "pronunciation": "fā yīn", "ipa": "fa˥ in˥", "syllable_count": 2, "sentences": [{"text": "她的发音像广播员一样好听。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听不清他的发音。", "target_word": "发音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子的发音还不清楚。", "target_word": "发音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的发音很清楚，我听得懂。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习发音要多听多说。", "target_word": "发音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的发音有南方口音。", "target_word": "发音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好的发音要靠每天练习。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学好汉语的发音。", "target_word": "发音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他牙齿掉了，发音不太清楚。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师纠正了我的发音。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种发音", "label": "量词搭配"}, {"form": "發音", "label": "繁体"}, {"form": "发音器官", "label": "复合词"}, {"form": "发音方法", "label": "复合词"}], "register": "中性", "sense_fingerprint": "嘴里说出的字音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92421, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "字体", "is_correct": false, "explanation": "语义：“字体”是字的写法，不能用“好听”形容。"}, {"text": "发音", "is_correct": true, "explanation": "“发音”指嘴里说出的字音，与“像广播员一样好听”相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”不能用“好听”形容。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“好听”用于声音、音乐，不说面积。"}], "explanations": {"字体": "语义：“字体”是字的写法，不能用“好听”形容。", "发音": "“发音”指嘴里说出的字音，与“像广播员一样好听”相符。", "身高": "语义：“身高”不能用“好听”形容。", "面积": "搭配：“好听”用于声音、音乐，不说面积。"}, "sentence_index": 0, "correct_answer": "发音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的发音很高。", "explanation": "这里应该用〈高度〉。发音指嘴里说出的字的声音，山的高低要用〈高度〉。"}, {"text": "这幅画的发音很美。", "explanation": "这里应该用〈色彩〉。发音指字的声音，画面的好看程度要用〈色彩〉。"}, {"text": "这本书的发音很贵。", "explanation": "这里应该用〈价格〉。发音指嘴里说出的字的声音，书的售价要用〈价格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能靠练习而好，句子不成立。"}, {"text": "发音", "is_correct": true, "explanation": "“发音”指嘴里说出的字音，靠练习而好，与句意相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不能靠练习变好，与“靠每天练习”不合。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不能靠练习而好，句子不成立。"}], "explanations": {"天气": "语义：“天气”不能靠练习而好，句子不成立。", "发音": "“发音”指嘴里说出的字音，靠练习而好，与句意相符。", "房子": "语义：“房子”不能靠练习变好，与“靠每天练习”不合。", "汽车": "语义：“汽车”不能靠练习而好，句子不成立。"}, "sentence_index": 6, "correct_answer": "发音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他举起手，做了一个发音。", "explanation": "这里应该用〈手势〉。发音指字音，做出的动作要用〈手势〉。"}, {"text": "这道菜的发音很好。", "explanation": "这里应该用〈味道〉。发音指字音，菜的味道要用〈味道〉。"}, {"text": "这件衣服的发音很鲜艳。", "explanation": "这里应该用〈颜色〉。发音指字音，衣服的颜色鲜艳要用〈颜色〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个字有两条发音。", "corrected_sentence": "这个字有两种发音。", "error_description": "错误：“两条发音”，量词“条”用于细长的东西，不用于发音。正确：“两种发音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师的这把发音我们都听得懂。", "corrected_sentence": "老师的这种发音我们都听得懂。", "error_description": "错误：“这把发音”，量词“把”用于有柄的东西，不用于发音。正确：“这种发音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
