INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "发出声音的方式；字词的读音。", "primary_collocate": null, "pronunciation": "fā yīn", "ipa": "fa˥ in˥", "syllable_count": 2, "sentences": [{"text": "他的发音很标准。", "target_word": "发音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字的发音我不会。", "target_word": "发音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的发音有点儿问题，要多练习。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请查一下这个词的发音。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汉语的发音我觉得很难。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我的发音进步了很多。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个字的发音一样，意思不同。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话的发音很清楚。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "词典里有每个词的发音。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方人和南方人的发音不一样。", "target_word": "发音", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种发音", "label": "量词搭配"}, {"form": "發音", "label": "繁体"}, {"form": "发音器官", "label": "复合词"}, {"form": "发音方法", "label": "复合词"}], "register": "中性", "sense_fingerprint": "说话的方式，字词的读音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c3bb35a-2fc8-434b-9b84-9706ca49f8a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "字数", "is_correct": false, "explanation": "搭配：“标准”说读音、做法等，不说字数。"}, {"text": "发音", "is_correct": true, "explanation": "“发音”指字词的读音，与“很标准”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能说“很标准”。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“标准”不用于饭量，饭量说大小、多少。"}], "explanations": {"字数": "搭配：“标准”说读音、做法等，不说字数。", "发音": "“发音”指字词的读音，与“很标准”相符。", "天气": "语义：“天气”是自然现象，不能说“很标准”。", "饭量": "搭配：“标准”不用于饭量，饭量说大小、多少。"}, "sentence_index": 0, "correct_answer": "发音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划的发音很好。", "explanation": "这里应该用〈安排〉。发音指发出声音的方式或字词的读音，计划的内容要用〈安排〉。"}, {"text": "这次实验的发音很成功。", "explanation": "这里应该用〈结果〉。发音指发出声音的方式或字词的读音，实验的成败要用〈结果〉。"}, {"text": "这条河的发音有三十米。", "explanation": "这里应该用〈宽度〉。发音指发出声音的方式或字词的读音，河面的宽窄要用〈宽度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：字没有价格，“价格一样，意思不同”不合句意。"}, {"text": "发音", "is_correct": true, "explanation": "“发音”指字词的读音，与“一样，意思不同”相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：字没有年龄，“年龄一样”不合句意。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：字一般不说重量，“重量”不能用于这里。"}], "explanations": {"价格": "语义：字没有价格，“价格一样，意思不同”不合句意。", "发音": "“发音”指字词的读音，与“一样，意思不同”相符。", "年龄": "语义：字没有年龄，“年龄一样”不合句意。", "重量": "搭配：字一般不说重量，“重量”不能用于这里。"}, "sentence_index": 6, "correct_answer": "发音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的发音很好吃。", "explanation": "这里应该用〈味道〉。发音指发出声音的方式或字词的读音，食物的味道要用〈味道〉。"}, {"text": "这个字的发音有十二画。", "explanation": "这里应该用〈笔画〉。发音指字词的读音，字的笔画数要用〈笔画〉。"}, {"text": "这台电脑的发音三千块。", "explanation": "这里应该用〈价格〉。发音指发出声音的方式或字词的读音，钱数要用〈价格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个词有两只发音。", "corrected_sentence": "这个词有两种发音。", "error_description": "错误：“两只发音”，量词“只”用于动物等，不用于发音。正确：“两种发音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把发音很难学。", "corrected_sentence": "这种发音很难学。", "error_description": "错误：“这把发音”，量词“把”用于有柄的东西，不用于发音。正确：“这种发音”，量词“种”用于种类。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a228281f-d815-4ab4-9faa-9ae781f8d717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
