INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92423, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "白色是像雪一样的颜色。", "primary_collocate": null, "pronunciation": "bái sè", "ipa": "pai˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我最喜欢的颜色是白色。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的山上全是白色。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿了一件白色的衬衫。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色的小猫坐在窗边。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把墙刷成白色。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的房子都是白色的。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘的裙子是白色的。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色让房间看起来更大。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车是白色，不是黑色。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一个白色的杯子。", "target_word": "白色", "complexity_tier": "T3", "furigana": "bái sè", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "像雪一样的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a1638f-b64a-4caa-8649-66c87ab87a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白色", "is_correct": true, "explanation": "白色：指像雪一样的颜色，填入后符合“最喜欢的颜色”的语义。"}, {"text": "白糖", "is_correct": false, "explanation": "语义：白糖是食品，不是颜色，不能作“颜色是”的内容。"}, {"text": "白天", "is_correct": false, "explanation": "语义：白天指白昼的时间，不是颜色。"}, {"text": "白云", "is_correct": false, "explanation": "搭配：“颜色是”后要接颜色词，白云是天上的具体事物，不能作颜色。"}], "explanations": {"白色": "白色：指像雪一样的颜色，填入后符合“最喜欢的颜色”的语义。", "白糖": "语义：白糖是食品，不是颜色，不能作“颜色是”的内容。", "白天": "语义：白天指白昼的时间，不是颜色。", "白云": "搭配：“颜色是”后要接颜色词，白云是天上的具体事物，不能作颜色。"}, "sentence_index": 0, "correct_answer": "白色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到这个消息，脸色变得白色。", "explanation": "这里应该用〈苍白〉。“苍白”形容因惊吓或生病而没有血色的脸色，“白色”只用来说物体的颜色，不能描述脸色的变化。"}, {"text": "我每天早上喝一杯白色的开水。", "explanation": "这里应该用〈白开水〉。“白开水”指烧开后的清水，本身无色，不能说“白色的开水”。"}, {"text": "我很喜欢这只白色。", "explanation": "这里应该用〈种〉。颜色名词常用“种”来数，“只”用于动物或个体事物，不能用来数“白色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白色", "is_correct": true, "explanation": "白色：指颜色，填入后符合“裙子的颜色”的语义。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，不能用来说明裙子的颜色。"}, {"text": "白班", "is_correct": false, "explanation": "搭配：“白班”指白天值的班，不能用在“裙子是……的”里作颜色。"}, {"text": "白兔", "is_correct": false, "explanation": "语义：白兔是动物，不能作裙子的颜色。"}], "explanations": {"白色": "白色：指颜色，填入后符合“裙子的颜色”的语义。", "白菜": "语义：白菜是蔬菜，不能用来说明裙子的颜色。", "白班": "搭配：“白班”指白天值的班，不能用在“裙子是……的”里作颜色。", "白兔": "语义：白兔是动物，不能作裙子的颜色。"}, "sentence_index": 6, "correct_answer": "白色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的皮肤白色，看起来很健康。", "explanation": "这里应该用〈白皙〉。“白皙”形容皮肤白净，“白色”是颜色名词，不说“皮肤白色”。"}, {"text": "他听到消息后，脸白色了。", "explanation": "这里应该用〈惨白〉。“惨白”形容因惊吓或生病而发白的脸色，“白色”不用来描述脸色的变化。"}, {"text": "这件衣服的白色很厚，穿起来很暖和。", "explanation": "这里应该用〈厚实〉。形容布料的厚度要用“厚实”，颜色名词“白色”没有厚薄之分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一条白色的帽子。", "corrected_sentence": "他买了一顶白色的帽子。", "error_description": "量词错误：错误形式是“一条……帽子”，正确形式是“一顶……帽子”，帽子用量词“顶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把墙刷了白色。", "corrected_sentence": "工人把墙刷成了白色。", "error_description": "结果补语错误：“把……刷”后表示结果的颜色要用“刷成”，缺少“成”。正确说法是“刷成了白色”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
