INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "像雪和牛奶那样的颜色。", "primary_collocate": null, "pronunciation": "bái sè", "ipa": "pai˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "牛奶是白色的。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只兔子全身都是白色。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一双白色的运动鞋。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色的云在蓝天上慢慢飘着。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生穿着白色的衣服。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子里的灯是白色的，很亮。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色和黑色放在一起很好看。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在白色的纸上画了一只小鸟。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天戴了一顶白色的帽子。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪下了一夜，外面变成了白色。", "target_word": "白色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "像雪和牛奶那样的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a1638f-b64a-4caa-8649-66c87ab87a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白色", "is_correct": true, "explanation": "白色：指像雪和牛奶那样的颜色，填入后符合“牛奶是……的”的语义。"}, {"text": "白粉", "is_correct": false, "explanation": "语义：白粉是粉末状的东西，不能用来说明牛奶的颜色。"}, {"text": "白天", "is_correct": false, "explanation": "搭配：“白天”是时间词，不能作“牛奶是……的”里的颜色。"}, {"text": "白纸", "is_correct": false, "explanation": "语义：白纸是纸张，不是颜色，不能用来描述牛奶。"}], "explanations": {"白色": "白色：指像雪和牛奶那样的颜色，填入后符合“牛奶是……的”的语义。", "白粉": "语义：白粉是粉末状的东西，不能用来说明牛奶的颜色。", "白天": "搭配：“白天”是时间词，不能作“牛奶是……的”里的颜色。", "白纸": "语义：白纸是纸张，不是颜色，不能用来描述牛奶。"}, "sentence_index": 0, "correct_answer": "白色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她听到这个消息，脸色变得白色。", "explanation": "这里应该用〈苍白〉。“苍白”形容因惊吓或生病而没有血色的脸色，“白色”只用来说物体的颜色，不能描述脸色的变化。"}, {"text": "我很喜欢这把白色。", "explanation": "这里应该用〈种〉。“把”用于有柄的器具，颜色名词要用“种”来数，不能说“这把白色”。"}, {"text": "我每天早上都喝一杯白色的开水。", "explanation": "这里应该用〈白开水〉。“白开水”指烧开后的清水，本身无色，不能说“白色的开水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白色", "is_correct": true, "explanation": "白色：指颜色，填入后句子成立，符合“白色和黑色”并列的语义。"}, {"text": "白粥", "is_correct": false, "explanation": "语义：白粥是食物，不是颜色，不能与“黑色”并列作主语。"}, {"text": "白糖", "is_correct": false, "explanation": "语义：白糖是调味品，不能与“黑色”并列说明颜色搭配。"}, {"text": "白班", "is_correct": false, "explanation": "搭配：“白班”指白天值的班，不能与颜色词并列作主语。"}], "explanations": {"白色": "白色：指颜色，填入后句子成立，符合“白色和黑色”并列的语义。", "白粥": "语义：白粥是食物，不是颜色，不能与“黑色”并列作主语。", "白糖": "语义：白糖是调味品，不能与“黑色”并列说明颜色搭配。", "白班": "搭配：“白班”指白天值的班，不能与颜色词并列作主语。"}, "sentence_index": 6, "correct_answer": "白色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的皮肤白色，很细腻。", "explanation": "这里应该用〈白皙〉。“白皙”形容皮肤白净，“白色”是颜色名词，不说“皮肤白色”。"}, {"text": "他被吓得脸白色了。", "explanation": "这里应该用〈惨白〉。“惨白”形容因惊吓而发白的脸色，“白色”不用来描述脸色的变化。"}, {"text": "这件衣服的白色很厚，穿起来很暖和。", "explanation": "这里应该用〈厚实〉。形容布料的厚度要用“厚实”，颜色名词“白色”没有厚薄之分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她穿了一件很白色的裙子。", "corrected_sentence": "她穿了一件白色的裙子。", "error_description": "程度副词误用：“白色”是颜色名词，前面不能加“很”，应说“一件白色的裙子”（或“很白的裙子”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一场大雪过后，山谷里变成了一白色。", "corrected_sentence": "一场大雪过后，山谷里变成了白色。", "error_description": "量词错误：颜色名词“白色”前不能加数量词“一”，应说“变成了白色”，“一白色”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92425, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "感谢", "is_correct": false, "explanation": "感谢是对别人的帮助表示谢意，与祝福不构成反义关系。"}, {"text": "诅咒", "is_correct": true, "explanation": "诅咒是希望别人遭殃，与祝福表达的美好心愿意思相反。"}, {"text": "帮助", "is_correct": false, "explanation": "帮助是出手协助别人，与祝福没有反义关系。"}, {"text": "批评", "is_correct": false, "explanation": "批评是指出别人的缺点，与祝福没有反义关系。"}], "correct_answer": "诅咒", "explanations": {"感谢": "感谢是对别人的帮助表示谢意，与祝福不构成反义关系。", "诅咒": "诅咒是希望别人遭殃，与祝福表达的美好心愿意思相反。", "帮助": "帮助是出手协助别人，与祝福没有反义关系。", "批评": "批评是指出别人的缺点，与祝福没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92425, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安慰", "is_correct": false, "explanation": "安慰是宽慰对方的情绪，与祝福没有反义关系。"}, {"text": "夸奖", "is_correct": false, "explanation": "夸奖是称赞对方，与祝福不构成反义关系。"}, {"text": "原谅", "is_correct": false, "explanation": "原谅是不再追究对方的过错，与祝福没有反义关系。"}, {"text": "诅咒", "is_correct": true, "explanation": "诅咒是希望别人遭殃，与祝福表达的美好心愿意思相反。"}], "correct_answer": "诅咒", "explanations": {"安慰": "安慰是宽慰对方的情绪，与祝福没有反义关系。", "夸奖": "夸奖是称赞对方，与祝福不构成反义关系。", "原谅": "原谅是不再追究对方的过错，与祝福没有反义关系。", "诅咒": "诅咒是希望别人遭殃，与祝福表达的美好心愿意思相反。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92425, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里希望别人快乐平安，并说出来。", "primary_collocate": null, "pronunciation": "zhù fú", "ipa": "tʂu˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "朋友要出国了，我们都祝福他一路平安。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家站在门口，祝福新娘新郎幸福。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过生日时，妈妈祝福我身体健康。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她明天要考试，我祝福她一切顺利。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师祝福毕业的同学前途光明。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚那天，我真心祝福他们。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶看着孙子上学，轻声祝福他。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，我发短信祝福老朋友。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起祝福这对夫妻白头到老。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你要当妈妈了，我祝福你们一家。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "祝福了", "label": "体标（了）"}, {"form": "祝福着", "label": "体标（着）"}, {"form": "祝福过", "label": "体标（过）"}, {"form": "祝福语", "label": "复合词"}], "register": "通用", "sense_fingerprint": "心里盼别人快乐平安并说出口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92425, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "祝福", "is_correct": true, "explanation": "祝福（zhù fú）：心里希望别人快乐平安，并说出口。"}, {"text": "住户", "is_correct": false, "explanation": "住户（zhù hù）与祝福的第二个音节不同：hù 的声母是 h，fú 的声母是 f。意思是住在某处的人家。"}, {"text": "主妇", "is_correct": false, "explanation": "主妇（zhǔ fù）与祝福两个音节的声调都不同：zhǔ 是第三声，fù 是第四声。意思是操持家务的女性。"}, {"text": "主夫", "is_correct": false, "explanation": "主夫（zhǔ fū）与祝福两个音节的声调都不同，意思是在家操持家务的男性。"}], "explanations": {"祝福": "祝福（zhù fú）：心里希望别人快乐平安，并说出口。", "住户": "住户（zhù hù）与祝福的第二个音节不同：hù 的声母是 h，fú 的声母是 f。意思是住在某处的人家。", "主妇": "主妇（zhǔ fù）与祝福两个音节的声调都不同：zhǔ 是第三声，fù 是第四声。意思是操持家务的女性。", "主夫": "主夫（zhǔ fū）与祝福两个音节的声调都不同，意思是在家操持家务的男性。"}, "sentence_index": null, "correct_answer": "祝福"}, "level_3": {"options": [{"text": "诅咒", "is_correct": false, "explanation": "语义：诅咒是希望别人遭殃，与“一路平安”的愿望正好相反。"}, {"text": "祝福", "is_correct": true, "explanation": "正确：祝福表示心里盼望朋友一路平安，并说出来，与“出国”的场景相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑别人，不能表达希望对方平安的心意。"}, {"text": "阻止", "is_correct": false, "explanation": "配价：“阻止”要接具体的行为，不能直接带“他一路平安”这样的状态作宾语。"}], "explanations": {"诅咒": "语义：诅咒是希望别人遭殃，与“一路平安”的愿望正好相反。", "祝福": "正确：祝福表示心里盼望朋友一路平安，并说出来，与“出国”的场景相符。", "嘲笑": "语义：嘲笑是取笑别人，不能表达希望对方平安的心意。", "阻止": "配价：“阻止”要接具体的行为，不能直接带“他一路平安”这样的状态作宾语。"}, "sentence_index": 0, "correct_answer": "祝福"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天拿到了金牌，我祝福他拿到了金牌。", "explanation": "这里应该用〈祝贺〉。祝福是对将来的美好心愿，对已经取得的成就要用祝贺。"}, {"text": "见到老师，我向他祝福。", "explanation": "这里应该用〈问候〉。祝福是表达美好心愿，见面打招呼要用问候。"}, {"text": "邻居帮我搬了一整天家，我连声向他祝福。", "explanation": "这里应该用〈感谢〉。祝福是表达对别人将来的美好心愿，对别人的帮助表示谢意要用感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推倒", "is_correct": false, "explanation": "搭配：“轻声”修饰说话类动作，“推倒”不是说话，句子不通；奶奶也不会推倒孙子。"}, {"text": "威胁", "is_correct": false, "explanation": "语义：威胁是用恐吓逼人，与奶奶温和的态度不符。"}, {"text": "祝福", "is_correct": true, "explanation": "正确：祝福表示轻声说出希望孙子平安的心意，与奶奶的疼爱相符。"}, {"text": "嘲讽", "is_correct": false, "explanation": "语义：嘲讽是讥笑挖苦，与奶奶疼爱孙子、轻声祝愿的语境相反。"}], "explanations": {"推倒": "搭配：“轻声”修饰说话类动作，“推倒”不是说话，句子不通；奶奶也不会推倒孙子。", "威胁": "语义：威胁是用恐吓逼人，与奶奶温和的态度不符。", "祝福": "正确：祝福表示轻声说出希望孙子平安的心意，与奶奶的疼爱相符。", "嘲讽": "语义：嘲讽是讥笑挖苦，与奶奶疼爱孙子、轻声祝愿的语境相反。"}, "sentence_index": 6, "correct_answer": "祝福"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他上课总说话，我严厉地祝福了他几句。", "explanation": "这里应该用〈批评〉。祝福是表达美好心愿，指出对方的错误要用批评；“严厉地”与“祝福”的语气相反。"}, {"text": "我弄丢了他的书，连忙向他祝福。", "explanation": "这里应该用〈道歉〉。祝福不用于认错，向对方承认过错要用道歉。"}, {"text": "他拿着刀站在门口，祝福我别乱动。", "explanation": "这里应该用〈警告〉。祝福是表达美好心愿，要求对方别轻举妄动、以严肃口吻提醒危险要用警告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很祝福你一路顺风。", "corrected_sentence": "我真心祝福你一路顺风。", "error_description": "错误形式：“很”修饰“祝福”。正确形式：“真心祝福”。原因：“祝福”表达发自内心的美好心愿，常用“真心”“衷心”等表示态度的词来修饰，一般不用“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他祝福了过很多朋友。", "corrected_sentence": "他祝福过很多朋友。", "error_description": "错误形式：“了”和“过”同时出现在“祝福”后面，重复标记体。正确形式：“祝福过”，只用“过”表示经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92426, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "感谢", "is_correct": false, "explanation": "感谢是对别人的帮助表示谢意，与祝福不构成反义关系。"}, {"text": "鼓励", "is_correct": false, "explanation": "鼓励是给人信心和力量，与祝福没有反义关系。"}, {"text": "批评", "is_correct": false, "explanation": "批评是指出别人的缺点，与祝福没有反义关系。"}, {"text": "诅咒", "is_correct": true, "explanation": "诅咒是希望别人遭殃，与祝福表达的美好心愿意思相反。"}], "correct_answer": "诅咒", "explanations": {"感谢": "感谢是对别人的帮助表示谢意，与祝福不构成反义关系。", "鼓励": "鼓励是给人信心和力量，与祝福没有反义关系。", "批评": "批评是指出别人的缺点，与祝福没有反义关系。", "诅咒": "诅咒是希望别人遭殃，与祝福表达的美好心愿意思相反。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92426, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "惩罚", "is_correct": false, "explanation": "惩罚是对过错的处罚，与祝福没有反义关系。"}, {"text": "责备", "is_correct": false, "explanation": "责备是指责对方的过错，与祝福没有反义关系。"}, {"text": "讥讽", "is_correct": false, "explanation": "讥讽是用话挖苦别人，与祝福没有反义关系。"}, {"text": "诅咒", "is_correct": true, "explanation": "诅咒是希望别人遭殃，与祝福表达的美好心愿意思相反。"}], "correct_answer": "诅咒", "explanations": {"惩罚": "惩罚是对过错的处罚，与祝福没有反义关系。", "责备": "责备是指责对方的过错，与祝福没有反义关系。", "讥讽": "讥讽是用话挖苦别人，与祝福没有反义关系。", "诅咒": "诅咒是希望别人遭殃，与祝福表达的美好心愿意思相反。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92426, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "祝愿别人平安幸福。", "primary_collocate": null, "pronunciation": "zhù fú", "ipa": "tʂu˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "过年时，爷爷祝福全家人平安幸福。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我祝福你每天都快乐。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把最好的愿望送给朋友，祝福他们幸福。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们微笑着祝福这对年轻人。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日那天，同学们一起祝福她。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们祝福所有的孩子健康长大。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他祝福过很多要远行的朋友。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走前，妈妈祝福我平安回家。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请让我祝福你们的新家温暖幸福。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写字，祝福大家新年快乐。", "target_word": "祝福", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "祝福了", "label": "体标（了）"}, {"form": "祝福着", "label": "体标（着）"}, {"form": "祝福过", "label": "体标（过）"}, {"form": "祝福语", "label": "复合词"}], "register": "通用", "sense_fingerprint": "祝愿别人平安幸福", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92426, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "祝福", "is_correct": true, "explanation": "祝福（zhù fú）：祝愿别人平安幸福。"}, {"text": "住户", "is_correct": false, "explanation": "住户（zhù hù）与祝福的第二个音节不同：hù 的声母是 h，fú 的声母是 f。意思是住在某处的人家。"}, {"text": "主妇", "is_correct": false, "explanation": "主妇（zhǔ fù）与祝福两个音节的声调都不同：zhǔ 是第三声，fù 是第四声。意思是操持家务的女性。"}, {"text": "主夫", "is_correct": false, "explanation": "主夫（zhǔ fū）与祝福两个音节的声调都不同，意思是在家操持家务的男性。"}], "explanations": {"祝福": "祝福（zhù fú）：祝愿别人平安幸福。", "住户": "住户（zhù hù）与祝福的第二个音节不同：hù 的声母是 h，fú 的声母是 f。意思是住在某处的人家。", "主妇": "主妇（zhǔ fù）与祝福两个音节的声调都不同：zhǔ 是第三声，fù 是第四声。意思是操持家务的女性。", "主夫": "主夫（zhǔ fū）与祝福两个音节的声调都不同，意思是在家操持家务的男性。"}, "sentence_index": null, "correct_answer": "祝福"}, "level_3": {"options": [{"text": "咒骂", "is_correct": false, "explanation": "语义：咒骂是骂人，与过年时对全家平安幸福的祝愿相反。"}, {"text": "驱赶", "is_correct": false, "explanation": "配价：“驱赶”的宾语应是被赶走的人或东西，不能直接带“全家人平安幸福”这样的愿望。"}, {"text": "祝福", "is_correct": true, "explanation": "正确：祝福表示对全家人平安幸福的美好祝愿，与过年的场景相符。"}, {"text": "讥笑", "is_correct": false, "explanation": "语义：讥笑是取笑别人，与过年时的祝愿不符。"}], "explanations": {"咒骂": "语义：咒骂是骂人，与过年时对全家平安幸福的祝愿相反。", "驱赶": "配价：“驱赶”的宾语应是被赶走的人或东西，不能直接带“全家人平安幸福”这样的愿望。", "祝福": "正确：祝福表示对全家人平安幸福的美好祝愿，与过年的场景相符。", "讥笑": "语义：讥笑是取笑别人，与过年时的祝愿不符。"}, "sentence_index": 0, "correct_answer": "祝福"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这对年轻人昨天获得了冠军，老人们祝福他们获得了冠军。", "explanation": "这里应该用〈祝贺〉。祝福是对将来的美好心愿，对已经取得的成就要用祝贺。"}, {"text": "进门时，老人们微笑着向大家祝福。", "explanation": "这里应该用〈问候〉。祝福是表达美好心愿，见面打招呼要用问候。"}, {"text": "邻居帮老人们搬了一整天家，老人们连声向他祝福。", "explanation": "这里应该用〈感谢〉。祝福是表达对别人将来的美好心愿，对别人的帮助表示谢意要用感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能说“煮过朋友”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是房间、地面，不能说“打扫过朋友”。"}, {"text": "驱赶", "is_correct": false, "explanation": "配价：“驱赶”要接被赶走的对象和去向，不能用来表达对远行朋友的祝愿。"}, {"text": "祝福", "is_correct": true, "explanation": "正确：祝福表示对远行朋友的美好祝愿，与“很多要远行的朋友”相符。"}], "explanations": {"煮": "语义：“煮”的对象是食物，不能说“煮过朋友”。", "打扫": "语义：“打扫”的对象是房间、地面，不能说“打扫过朋友”。", "驱赶": "配价：“驱赶”要接被赶走的对象和去向，不能用来表达对远行朋友的祝愿。", "祝福": "正确：祝福表示对远行朋友的美好祝愿，与“很多要远行的朋友”相符。"}, "sentence_index": 6, "correct_answer": "祝福"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在黑板上写字，严厉地祝福大家别迟到。", "explanation": "这里应该用〈批评〉。祝福是表达美好心愿，指出对方的错误要用批评；“严厉地”与“祝福”的语气相反。"}, {"text": "我不小心踩了他的脚，连忙向他祝福。", "explanation": "这里应该用〈道歉〉。祝福是表达美好心愿，做错事向对方认错要用道歉。"}, {"text": "老师在黑板上写字，向大家祝福早上好。", "explanation": "这里应该用〈问候〉。“早上好”是问候语，祝福不能与问候语搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人们很祝福这对年轻人。", "corrected_sentence": "老人们真心祝福这对年轻人。", "error_description": "错误形式：“很”修饰“祝福”。正确形式：“真心祝福”。原因：“祝福”表达发自内心的美好心愿，常用“真心”“衷心”等表示态度的词来修饰，一般不用“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他祝福得很多出国的朋友。", "corrected_sentence": "他祝福过很多出国的朋友。", "error_description": "错误形式：“祝福得”，“得”后面需要补语，这里没有。正确形式：“祝福过”，“过”表示曾经有过的经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
