INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责监察、督促他人或事情的人。", "primary_collocate": null, "pronunciation": "jiān dū rén", "ipa": "tɕjɛn˥ tu˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "学校请了一位家长做考试的监督人。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "xué xiào qǐng le yí wèi jiā zhǎng zuò kǎo shì de jiān dū rén", "sentence_source": "generated"}, {"text": "工程的监督人每天都会来检查。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "gōng chéng de jiān dū rén měi tiān dōu huì lái jiǎn chá", "sentence_source": "generated"}, {"text": "他是这次比赛的监督人，要保证公平。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "tā shì zhè cì bǐ sài de jiān dū rén, yào bǎo zhèng gōng píng", "sentence_source": "generated"}, {"text": "公司需要一位监督人看着这笔钱怎么用。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "gōng sī xū yào yí wèi jiān dū rén kàn zhe zhè bǐ qián zěn me yòng", "sentence_source": "generated"}, {"text": "这个项目的监督人是王经理。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "zhè ge xiàng mù de jiān dū rén shì wáng jīng lǐ", "sentence_source": "generated"}, {"text": "监督人发现问题后马上告诉了大家。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "jiān dū rén fā xiàn wèn tí hòu mǎ shàng gào sù le dà jiā", "sentence_source": "generated"}, {"text": "选举时，每个地方都有监督人。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "xuǎn jǔ shí, měi ge dì fang dōu yǒu jiān dū rén", "sentence_source": "generated"}, {"text": "她当过工厂的安全监督人。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "tā dāng guo gōng chǎng de ān quán jiān dū rén", "sentence_source": "generated"}, {"text": "作为监督人，他必须说真话。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "zuò wéi jiān dū rén, tā bì xū shuō zhēn huà", "sentence_source": "generated"}, {"text": "我们请老师当小组的监督人。", "target_word": "监督人", "complexity_tier": "T3", "furigana": "wǒ men qǐng lǎo shī dāng xiǎo zǔ de jiān dū rén", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "監督人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "负责监察、督促他人或事情的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作者", "is_correct": false, "explanation": "语义：作者是写作的人，不负责监察考试，与“学校请了一位家长做考试的”不符。"}, {"text": "监督人", "is_correct": true, "explanation": "正确：“监督人”指负责监察考试的人，与“学校请了一位家长做考试的……”的语境相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘车的人，与考试无关，不能填入这一位置。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“做考试的厨师”说不通，厨师与考试不搭配。"}], "explanations": {"作者": "语义：作者是写作的人，不负责监察考试，与“学校请了一位家长做考试的”不符。", "监督人": "正确：“监督人”指负责监察考试的人，与“学校请了一位家长做考试的……”的语境相符。", "乘客": "语义：乘客是乘车的人，与考试无关，不能填入这一位置。", "厨师": "搭配：“做考试的厨师”说不通，厨师与考试不搭配。"}, "sentence_index": 0, "correct_answer": "监督人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子的父母去世后，由叔叔担任他的监督人，负责抚养他。", "explanation": "这里应该用〈监护人〉。「监督人」指负责监察、督促的人，「监护人」指负责照顾、抚养未成年人的人；这里说抚养，应用监护人。"}, {"text": "这所学校的监督人负责教学生写字。", "explanation": "这里应该用〈教师〉。「监督人」指负责监察、督促他人的人，不负责教学，教学生写字应用教师。"}, {"text": "这支球队的监督人负责训练运动员的体能。", "explanation": "这里应该用〈教练〉。「监督人」指负责监察、督促的人，不负责训练，训练体能应用教练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不是人或职位，与“选举时，每个地方都有”的语境不符。"}, {"text": "监督人", "is_correct": true, "explanation": "正确：选举时每个地方都设有负责监督的人，与语境一致。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：邮票是物品，不能在选举中担任负责监督的人。"}, {"text": "外星人", "is_correct": false, "explanation": "语义：选举时每个地方都有外星人说不通，与选举的语境不符。"}], "explanations": {"地震": "语义：地震是自然灾害，不是人或职位，与“选举时，每个地方都有”的语境不符。", "监督人": "正确：选举时每个地方都设有负责监督的人，与语境一致。", "邮票": "语义：邮票是物品，不能在选举中担任负责监督的人。", "外星人": "语义：选举时每个地方都有外星人说不通，与选举的语境不符。"}, "sentence_index": 6, "correct_answer": "监督人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "监督人负责做饭，每天要准备三顿饭菜。", "explanation": "这里应该用〈厨师〉。「监督人」指负责监察、督促的人，不负责做饭，做饭应说厨师。"}, {"text": "监督人负责给病人看病开药。", "explanation": "这里应该用〈医生〉。「监督人」指负责监察、督促的人，不给病人看病开药，应说医生。"}, {"text": "监督人负责开车送客人。", "explanation": "这里应该用〈司机〉。「监督人」指负责监察、督促的人，不负责开车送客，应说司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛需要一只监督人。", "corrected_sentence": "这次比赛需要一位监督人。", "error_description": "量词错误：“监督人”指人，应用“位”“名”“个”，不能用“只”。正确说法是“一位监督人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校请了几位监督人们。", "corrected_sentence": "学校请了几位监督人。", "error_description": "多加了“们”：名词前已有数量词“几位”时，后面不能再加“们”，应说“几位监督人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92429, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "领先", "is_correct": true, "explanation": "在比赛中“领先”与“落后”互为反义词，正确。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”与“落后”在比赛位置的义项上没有反义或近义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”与“落后”在比赛位置的义项上没有反义或近义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”与“落后”在比赛位置的义项上没有反义或近义关系。"}], "correct_answer": "领先", "explanations": {"领先": "在比赛中“领先”与“落后”互为反义词，正确。", "散步": "“散步”与“落后”在比赛位置的义项上没有反义或近义关系。", "睡觉": "“睡觉”与“落后”在比赛位置的义项上没有反义或近义关系。", "讨论": "“讨论”与“落后”在比赛位置的义项上没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92429, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "领先", "is_correct": true, "explanation": "在比赛中“领先”与“落后”互为反义词，正确。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”与“落后”在比赛位置的义项上没有反义或近义关系。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”与“落后”在比赛位置的义项上没有反义或近义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”与“落后”在比赛位置的义项上没有反义或近义关系。"}], "correct_answer": "领先", "explanations": {"领先": "在比赛中“领先”与“落后”互为反义词，正确。", "唱歌": "“唱歌”与“落后”在比赛位置的义项上没有反义或近义关系。", "写字": "“写字”与“落后”在比赛位置的义项上没有反义或近义关系。", "游泳": "“游泳”与“落后”在比赛位置的义项上没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92429, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "落后是走得比别人慢，在后面。", "primary_collocate": null, "pronunciation": "luò hòu", "ipa": "lwɔ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他跑得慢，落后了很多。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛刚开始，我们队就落后了。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山的时候，我落后了几米。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明走得太慢，落后了大家一大段。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直落后，最后一个到终点。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别落后，跟紧我。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们队落后两分，还有时间。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑到一半，他落后第一名很多。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的自行车坏了，所以落后了。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走快一点，不要落后。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "落后了", "label": "完成体"}, {"form": "落后过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "行进、比赛中速度慢，位置在别人后面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1770a-bc57-44b1-a061-4827a60dbaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落后", "is_correct": true, "explanation": "“落后”指走得慢、在别人后面，与“跑得慢”的语境一致，正确。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人风趣，不能说跑得慢后变得幽默了。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不能描述跑步的位置或速度。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌，不能用来说跑步的位置或状态。"}], "explanations": {"落后": "“落后”指走得慢、在别人后面，与“跑得慢”的语境一致，正确。", "幽默": "语义：“幽默”形容人风趣，不能说跑得慢后变得幽默了。", "柔软": "语义：“柔软”形容质地，不能描述跑步的位置或速度。", "漂亮": "搭配：“漂亮”形容外貌，不能用来说跑步的位置或状态。"}, "sentence_index": 0, "correct_answer": "落后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆赛车跑得很落后，比对手都强。", "explanation": "这里应该用〈快〉。落后指走得慢、在后面，说车跑得快要用“快”，“跑得很落后”与“比对手都强”自相矛盾。"}, {"text": "小明跑得很快，落后了大家一大段。", "explanation": "这里应该用〈超过〉。小明跑得快，应说“超过了大家一大段”；“落后”说的是位置在别人后面，与“跑得快”矛盾。"}, {"text": "他一直跑在最前面，比别人落后很多。", "explanation": "这里应该用〈领先〉。落后说的是走得慢、处于后面，与“跑在最前面”矛盾，应说“领先”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "落后", "is_correct": true, "explanation": "“落后”指在比赛中落在别人后面，与“落后两分”的说法一致，正确。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，不能用来表示比分的差距。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“两分”作数量宾语。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”不能与“两分”搭配来说比分。"}], "explanations": {"落后": "“落后”指在比赛中落在别人后面，与“落后两分”的说法一致，正确。", "唱": "语义：“唱”指唱歌，不能用来表示比分的差距。", "睡": "配价：“睡”是不及物动词，不能带“两分”作数量宾语。", "散步": "搭配：“散步”不能与“两分”搭配来说比分。"}, "sentence_index": 6, "correct_answer": "落后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆自行车跑得很快，比别人落后很多。", "explanation": "这里前后矛盾：“跑得很快”与“比别人落后很多”不能并存，应改为“跑得很慢”。"}, {"text": "这次比赛他跑得最快，结果落后在最前面。", "explanation": "这里应该用〈领先〉。落后指位置在别人后面，“跑得最快”却“落后在最前面”自相矛盾；跑在最前面要说“领先”。"}, {"text": "这头老牛走得很快，却一直落后在大家的前面。", "explanation": "这里应该用〈领先〉。“落后在大家的前面”自相矛盾：落后指走在别人后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑得慢，越跑越很落后。", "corrected_sentence": "他跑得慢，越跑越落后。", "error_description": "错误：「越……越……」结构中不能加「很」。「越跑越很落后」是错误的，应说「越跑越落后」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛，我们的队员被落后了一圈。", "corrected_sentence": "这次比赛，我们的队员落后了一圈。", "error_description": "错误：“落后”是不及物的，不能用“被”构成被动句。应说“我们的队员落后了一圈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92430, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "先进", "is_correct": true, "explanation": "“先进”与“落后”在发展水平的义项上互为反义词，正确。"}, {"text": "幸福", "is_correct": false, "explanation": "“幸福”与“落后”在此义项上没有反义或近义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“落后”在此义项上没有反义或近义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”与“落后”在此义项上没有反义或近义关系。"}], "correct_answer": "先进", "explanations": {"先进": "“先进”与“落后”在发展水平的义项上互为反义词，正确。", "幸福": "“幸福”与“落后”在此义项上没有反义或近义关系。", "清楚": "“清楚”与“落后”在此义项上没有反义或近义关系。", "柔软": "“柔软”与“落后”在此义项上没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
