INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92430, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在发展水平、成绩、条件或思想等方面比别人差。", "primary_collocate": null, "pronunciation": "luò hòu", "ipa": "lwɔ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个地方的经济比较落后。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩在班里很落后。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的交通很落后。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的技术比别的国家落后。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧设备太落后，不能用了。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的学校条件落后，老师也不多。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己的思想已经落后了。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不努力学习，就会落后。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器已经落后了十年。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能让孩子的教育落后。", "target_word": "落后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "落后了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "发展水平、条件、技术比别人差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1770a-bc57-44b1-a061-4827a60dbaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落后", "is_correct": true, "explanation": "“落后”说发展水平比别人差，与“经济比较”搭配，正确。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人风趣，不能用来形容经济。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容人或事物惹人喜欢，不能用来形容经济状况。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”说人的智力，不与“经济”搭配作谓语。"}], "explanations": {"落后": "“落后”说发展水平比别人差，与“经济比较”搭配，正确。", "幽默": "语义：“幽默”形容人风趣，不能用来形容经济。", "可爱": "语义：“可爱”形容人或事物惹人喜欢，不能用来形容经济状况。", "聪明": "搭配：“聪明”说人的智力，不与“经济”搭配作谓语。"}, "sentence_index": 0, "correct_answer": "落后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆老车的技术很先进，远远落后于新车。", "explanation": "这里前后矛盾：“技术很先进”与“远远落后于新车”不能并存，应改为“技术很落后”。"}, {"text": "他每天上班都落后，老板很生气。", "explanation": "这里应该用〈迟到〉。落后说的是在行进或发展中处于后面，指到达时间晚要用“迟到”，“上班落后”不自然。"}, {"text": "这台刚买的新电脑很落后。", "explanation": "这里应该用〈先进〉。落后指发展水平低，与“新”的意思矛盾；说新机器水平高要用“先进”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "落后", "is_correct": true, "explanation": "“落后”说思想跟不上时代，与“思想已经……了”搭配，正确。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人风趣，不能说思想幽默了。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指身体需要食物，不能用来形容思想。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能修饰“思想”。"}], "explanations": {"落后": "“落后”说思想跟不上时代，与“思想已经……了”搭配，正确。", "幽默": "语义：“幽默”形容人风趣，不能说思想幽默了。", "饿": "语义：“饿”指身体需要食物，不能用来形容思想。", "甜": "搭配：“甜”形容味道，不能修饰“思想”。"}, "sentence_index": 6, "correct_answer": "落后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的字写得很落后，老师看了直摇头。", "explanation": "这里应该用〈差〉。落后指与别人相比处于后面，形容字写得不好要用“差”，“写得很落后”不自然。"}, {"text": "今年的物价明显落后了。", "explanation": "这里应该用〈下降〉。落后指与别人相比处于后面，物价数量下降要用“下降”，“物价落后”不成立。"}, {"text": "他的脑子很落后，老师讲三遍也不懂。", "explanation": "这里应该用〈笨〉。落后指与别人相比水平差，形容脑子理解慢、学不会要用“笨”，“脑子落后”不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区的卫生条件落后的很厉害，需要改善。", "corrected_sentence": "这个地区的卫生条件落后得很厉害，需要改善。", "error_description": "错误：表示程度的补语要用「得」，不能用「的」。应说「落后得很厉害」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的英语成绩落后的很多，要努力补上。", "corrected_sentence": "他的英语成绩落后了很多，要努力补上。", "error_description": "错误：「落后」后面表示已经变化、带数量补语时要用「了」，不能用「的」。「落后的很多」应改为「落后了很多」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
