INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92431, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小动物住的地方。", "primary_collocate": null, "pronunciation": "wō", "ipa": "wɔ˥", "syllable_count": 1, "sentences": [{"text": "小狗回到自己的窝里睡觉。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家小狗的窝在门口。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给小猫做了一个暖和的窝。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只兔子的窝很干净。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不愿意离开它的窝。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在院子里给小鸡搭了一个窝。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在窝里睡着了。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那个窝里有三只小猫。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个窝是小狗自己找的。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，小狗跑回窝里。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个窝", "label": "量词"}, {"form": "狗窝", "label": "复合词"}, {"form": "鸟窝", "label": "复合词"}, {"form": "窩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小动物或宠物住的地方，如小狗、小猫的窝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92431, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "窝", "is_correct": true, "explanation": "正确答案：「窝」（wō）指小动物住的地方。"}, {"text": "我", "is_correct": false, "explanation": "wǒ（第三声）与 wō（第一声）声调不同，意思是「我」，不是小动物的窝。"}, {"text": "握", "is_correct": false, "explanation": "wò（第四声）与 wō（第一声）声调不同，意思是「握住」，不是窝。"}, {"text": "挖", "is_correct": false, "explanation": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是「挖掘」。"}, {"text": "蛙", "is_correct": false, "explanation": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是「青蛙」。"}], "explanations": {"窝": "正确答案：「窝」（wō）指小动物住的地方。", "我": "wǒ（第三声）与 wō（第一声）声调不同，意思是「我」，不是小动物的窝。", "握": "wò（第四声）与 wō（第一声）声调不同，意思是「握住」，不是窝。", "挖": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是「挖掘」。", "蛙": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是「青蛙」。"}, "sentence_index": null, "correct_answer": "窝"}, "level_3": {"options": [{"text": "碗", "is_correct": false, "explanation": "语义：「碗」是盛饭菜的器皿，小狗不能住在碗里睡觉。"}, {"text": "窝", "is_correct": true, "explanation": "「窝」指小动物住的地方，与「小狗回到自己的窝里睡觉」相符。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "搭配：「睡觉」的地点不能是垃圾桶，「垃圾桶里睡觉」不搭配。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋是用来穿的，不是小狗睡觉的地方，句子不通。"}], "explanations": {"碗": "语义：「碗」是盛饭菜的器皿，小狗不能住在碗里睡觉。", "窝": "「窝」指小动物住的地方，与「小狗回到自己的窝里睡觉」相符。", "垃圾桶": "搭配：「睡觉」的地点不能是垃圾桶，「垃圾桶里睡觉」不搭配。", "鞋": "语义：鞋是用来穿的，不是小狗睡觉的地方，句子不通。"}, "sentence_index": 0, "correct_answer": "窝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸把汽车开进了窝里。", "explanation": "这里应该用〈车库〉。窝是小动物住的地方，汽车要停在车库里。"}, {"text": "妈妈把衣服挂进了窝里。", "explanation": "这里应该用〈衣柜〉。窝是小动物住的地方，衣服要挂在衣柜里。"}, {"text": "学生们坐在窝里上课。", "explanation": "这里应该用〈教室〉。窝是小动物住的地方，学生在教室里上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92431, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "窝", "is_correct": true, "explanation": "正确答案：「窝」（wō）指小动物住的地方。"}, {"text": "卧", "is_correct": false, "explanation": "wò（第四声）与 wō（第一声）声调不同，意思是「躺下」。"}, {"text": "沃", "is_correct": false, "explanation": "wò（第四声）与 wō（第一声）声调不同，意思是「肥沃」。"}, {"text": "哇", "is_correct": false, "explanation": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是语气词「哇」。"}], "explanations": {"窝": "正确答案：「窝」（wō）指小动物住的地方。", "卧": "wò（第四声）与 wō（第一声）声调不同，意思是「躺下」。", "沃": "wò（第四声）与 wō（第一声）声调不同，意思是「肥沃」。", "哇": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是语气词「哇」。"}, "sentence_index": null, "correct_answer": "窝"}, "level_3": {"options": [{"text": "湖", "is_correct": false, "explanation": "语义：「湖」是大片水域，小猫不能在湖里睡着，与常识矛盾。"}, {"text": "水井", "is_correct": false, "explanation": "语义：水井是取水的深坑，小猫不会睡在里面。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「在窗户里」的方位不成立，应说「在窗户上」。"}, {"text": "窝", "is_correct": true, "explanation": "「窝」指小动物住的地方，「小猫在窝里睡着了」符合句意。"}], "explanations": {"湖": "语义：「湖」是大片水域，小猫不能在湖里睡着，与常识矛盾。", "水井": "语义：水井是取水的深坑，小猫不会睡在里面。", "窗户": "搭配：「在窗户里」的方位不成立，应说「在窗户上」。", "窝": "「窝」指小动物住的地方，「小猫在窝里睡着了」符合句意。"}, "sentence_index": 6, "correct_answer": "窝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把毛衣叠好，放进了鸟窝。", "explanation": "这里应该用〈衣柜〉。「窝」指鸟、兽栖息的地方，不能用来放衣服。"}, {"text": "飞机慢慢降落在窝里。", "explanation": "这里应该用〈机场〉。窝是小动物住的地方，飞机降落在机场。"}, {"text": "我们去窝里买菜。", "explanation": "这里应该用〈市场〉。窝是小动物住的地方，买菜要去市场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子的角落里有一只小窝。", "corrected_sentence": "院子的角落里有一个小窝。", "error_description": "错误：「窝」的量词用错了。「窝」应该用量词「个」，应说「一个小窝」，不说「一只小窝」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟叼着虫子飞回了里窝。", "corrected_sentence": "小鸟叼着虫子飞回了窝里。", "error_description": "错误：方位词「里」的位置错了。「里」应放在名词后面，应说「窝里」，不能说「里窝」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
