INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鸟、兽、虫等栖息的地方。", "primary_collocate": null, "pronunciation": "wō", "ipa": "wɔ˥", "syllable_count": 1, "sentences": [{"text": "燕子在屋檐下做了一个窝。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的熊冬天在窝里睡觉。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁的窝在那棵大树下面。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰把窝建在高高的山上。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风把树上的窝吹掉了。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂的窝挂在树枝上。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不要去碰鸟的窝。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，小鸟开始找地方做窝。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇的窝在石头下面。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼晚上回到窝里休息。", "target_word": "窝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个窝", "label": "量词"}, {"form": "鸟窝", "label": "复合词"}, {"form": "蜂窝", "label": "复合词"}, {"form": "窩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鸟、兽、虫等野生动物栖息的巢穴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92432, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "窝", "is_correct": true, "explanation": "正确答案：「窝」（wō）指鸟、兽、虫等栖息的地方。"}, {"text": "我", "is_correct": false, "explanation": "wǒ（第三声）与 wō（第一声）声调不同，意思是「我」，不是栖息的巢穴。"}, {"text": "握", "is_correct": false, "explanation": "wò（第四声）与 wō（第一声）声调不同，意思是「握住」，不是窝。"}, {"text": "挖", "is_correct": false, "explanation": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是「挖掘」。"}, {"text": "蛙", "is_correct": false, "explanation": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是「青蛙」。"}], "explanations": {"窝": "正确答案：「窝」（wō）指鸟、兽、虫等栖息的地方。", "我": "wǒ（第三声）与 wō（第一声）声调不同，意思是「我」，不是栖息的巢穴。", "握": "wò（第四声）与 wō（第一声）声调不同，意思是「握住」，不是窝。", "挖": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是「挖掘」。", "蛙": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是「青蛙」。"}, "sentence_index": null, "correct_answer": "窝"}, "level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "语义：燕子不会做蛋糕，「做了一个蛋糕」与燕子的行为矛盾。"}, {"text": "宣言", "is_correct": false, "explanation": "搭配：「宣言」通常说「发表」或「发布」，不说「做了一个宣言」。"}, {"text": "窝", "is_correct": true, "explanation": "「窝」指鸟类筑成的巢，「燕子在屋檐下做了一个窝」符合句意。"}, {"text": "手势", "is_correct": false, "explanation": "语义：「手势」是用手做出的动作，燕子没有手，句意不通。"}], "explanations": {"蛋糕": "语义：燕子不会做蛋糕，「做了一个蛋糕」与燕子的行为矛盾。", "宣言": "搭配：「宣言」通常说「发表」或「发布」，不说「做了一个宣言」。", "窝": "「窝」指鸟类筑成的巢，「燕子在屋檐下做了一个窝」符合句意。", "手势": "语义：「手势」是用手做出的动作，燕子没有手，句意不通。"}, "sentence_index": 0, "correct_answer": "窝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书整齐地放在窝里。", "explanation": "这里应该用〈书架〉。窝是鸟兽栖息的地方，书要放在书架上。"}, {"text": "病人躺在窝里打针。", "explanation": "这里应该用〈病房〉。窝是鸟兽栖息的地方，病人在病房里打针。"}, {"text": "火车开进了窝里。", "explanation": "这里应该用〈车站〉。窝是鸟兽栖息的地方，火车开进车站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92432, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "窝", "is_correct": true, "explanation": "正确答案：「窝」（wō）指鸟、兽、虫等栖息的地方。"}, {"text": "卧", "is_correct": false, "explanation": "wò（第四声）与 wō（第一声）声调不同，意思是「躺下」。"}, {"text": "沃", "is_correct": false, "explanation": "wò（第四声）与 wō（第一声）声调不同，意思是「肥沃」。"}, {"text": "哇", "is_correct": false, "explanation": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是语气词「哇」。"}], "explanations": {"窝": "正确答案：「窝」（wō）指鸟、兽、虫等栖息的地方。", "卧": "wò（第四声）与 wō（第一声）声调不同，意思是「躺下」。", "沃": "wò（第四声）与 wō（第一声）声调不同，意思是「肥沃」。", "哇": "wā（第一声）与 wō 的韵母不同（ā 与 ō），意思是语气词「哇」。"}, "sentence_index": null, "correct_answer": "窝"}, "level_3": {"options": [{"text": "叫声", "is_correct": false, "explanation": "语义：声音无形，不能用「碰」去接触，「碰鸟的叫声」不通。"}, {"text": "窝", "is_correct": true, "explanation": "「窝」是鸟的巢，是可以碰触的实物，与「不要去碰鸟的窝」相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是抽象的属性，不能用「碰」去接触。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：「碰」接触的是有形的东西，闻「气味」应说「闻」，不说「碰气味」。"}], "explanations": {"叫声": "语义：声音无形，不能用「碰」去接触，「碰鸟的叫声」不通。", "窝": "「窝」是鸟的巢，是可以碰触的实物，与「不要去碰鸟的窝」相符。", "颜色": "语义：颜色是抽象的属性，不能用「碰」去接触。", "气味": "搭配：「碰」接触的是有形的东西，闻「气味」应说「闻」，不说「碰气味」。"}, "sentence_index": 6, "correct_answer": "窝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把一双鞋放进了鸟窝。", "explanation": "这里的「窝」指鸟、兽栖息的地方，不能用来放鞋，应放进〈鞋柜〉。"}, {"text": "妈妈把冰箱放在窝里。", "explanation": "这里应该用〈厨房〉。窝是鸟兽栖息的地方，冰箱放在厨房里。"}, {"text": "我们去窝里看电影。", "explanation": "这里应该用〈电影院〉。窝是鸟兽栖息的地方，看电影要去电影院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings