INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "技艺；方法，策略。", "primary_collocate": null, "pronunciation": "shù", "ipa": "ʂu˥˩", "syllable_count": 1, "sentences": [{"text": "我想学一点防身之术，晚上回家更安全。", "target_word": "术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人伤得太重，医生已经没有救治之术了。", "target_word": "术", "complexity_tier": "T3", "furigana": "bìngrén shāng de tài zhòng, yīshēng yǐjīng méiyǒu jiùzhì zhī shù le.", "sentence_source": "generated"}, {"text": "他一个人要照顾三个孩子，真想学一种分身之术。", "target_word": "术", "complexity_tier": "T3", "furigana": "tā yí gè rén yào zhàogù sān gè háizi, zhēn xiǎng xué yì zhǒng fēnshēn zhī shù.", "sentence_source": "generated"}, {"text": "他从小不爱读书，一点养家之术都没学会。", "target_word": "术", "complexity_tier": "T3", "furigana": "tā cóngxiǎo bú ài dúshū, yìdiǎn yǎngjiā zhī shù dōu méi xuéhuì.", "sentence_source": "generated"}, {"text": "古时候的人都想找到长生不老之术。", "target_word": "术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔法师会隐身之术，没有人能看见他。", "target_word": "术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个骗子靠骗人之术赚了很多钱。", "target_word": "术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这座山里，他学会了求生之术。", "target_word": "术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板懂用人之术，公司越办越好。", "target_word": "术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人会一种治病之术，村里人都找他。", "target_word": "术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "術", "label": "繁体"}, {"form": "战术", "label": "复合"}, {"form": "技术", "label": "复合"}], "register": "书面", "sense_fingerprint": "术：技艺、方法、策略（多见于“……之术”“回天乏术”“不学无术”）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1770a-bc57-44b1-a061-4827a60dbaf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92436, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "术", "is_correct": true, "explanation": "正确答案：“术”读 shù（第四声）。"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是书。"}, {"text": "输", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是输赢的输。"}, {"text": "素", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是素食、朴素。"}, {"text": "熟", "is_correct": false, "explanation": "shú（第二声）与 shù（第四声）声调不同，意思是熟悉、成熟。"}], "explanations": {"术": "正确答案：“术”读 shù（第四声）。", "书": "shū（第一声）与 shù（第四声）声调不同，意思是书。", "输": "shū（第一声）与 shù（第四声）声调不同，意思是输赢的输。", "素": "sù 与 shù 声母不同（s 与 sh），意思是素食、朴素。", "熟": "shú（第二声）与 shù（第四声）声调不同，意思是熟悉、成熟。"}, "sentence_index": null, "correct_answer": "术"}, "level_3": {"options": [{"text": "术", "is_correct": true, "explanation": "“防身之术”是固定的说法，“术”与“之”组成名词短语，正确。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”指食物，不能用来指防身的技能或方法。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“歌”指歌曲，不能作“防身”的内容。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“防身之花”不成词组，“之”后接的应是抽象的技艺或方法。"}], "explanations": {"术": "“防身之术”是固定的说法，“术”与“之”组成名词短语，正确。", "饭": "语义：“饭”指食物，不能用来指防身的技能或方法。", "歌": "语义：“歌”指歌曲，不能作“防身”的内容。", "花": "搭配：“防身之花”不成词组，“之”后接的应是抽象的技艺或方法。"}, "sentence_index": 0, "correct_answer": "术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他术后恢复得很好，过几天就能出院。", "explanation": "这里的「术」是“术后”的一部分，指手术，属另一义项，不是技艺或方法。"}, {"text": "这次术很顺利，他很快就能出院。", "explanation": "这里的「术」指“手术”，属另一义项，不是技艺或方法。"}, {"text": "他学会了一只防身之术。", "explanation": "这里应该用〈门〉或〈种〉。「术」搭配量词时用「门」或「种」，「只」不能用于抽象的技艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92436, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "术", "is_correct": true, "explanation": "正确答案：“术”读 shù（第四声）。"}, {"text": "叔", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔。"}, {"text": "鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是老鼠。"}, {"text": "诉", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是诉说、告诉。"}, {"text": "赎", "is_correct": false, "explanation": "shú（第二声）与 shù（第四声）声调不同，意思是赎回。"}], "explanations": {"术": "正确答案：“术”读 shù（第四声）。", "叔": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔。", "鼠": "shǔ（第三声）与 shù（第四声）声调不同，意思是老鼠。", "诉": "sù 与 shù 声母不同（s 与 sh），意思是诉说、告诉。", "赎": "shú（第二声）与 shù（第四声）声调不同，意思是赎回。"}, "sentence_index": null, "correct_answer": "术"}, "level_3": {"options": [{"text": "术", "is_correct": true, "explanation": "“骗人之术”是固定的说法，“术”与“之”组成名词短语，正确。"}, {"text": "饭", "is_correct": false, "explanation": "语义：「饭」指食物，不能用来指骗人的方法。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：“鞋”是穿的东西，不能用来指骗人的方法。"}, {"text": "船", "is_correct": false, "explanation": "搭配：“骗人之船”不成词组，“之”后接的应是抽象的方法或技艺。"}], "explanations": {"术": "“骗人之术”是固定的说法，“术”与“之”组成名词短语，正确。", "饭": "语义：「饭」指食物，不能用来指骗人的方法。", "鞋": "语义：“鞋”是穿的东西，不能用来指骗人的方法。", "船": "搭配：“骗人之船”不成词组，“之”后接的应是抽象的方法或技艺。"}, "sentence_index": 6, "correct_answer": "术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说这次术很成功，他不用担心。", "explanation": "这里的「术」指“手术”，属另一义项，不是技艺。"}, {"text": "他找到了一个术语，考试很顺利。", "explanation": "这里的「术」属于“术语”，指专门名词，不是技艺或方法。"}, {"text": "他学会了一只治病之术，村里人都找他。", "explanation": "这里应该用〈门〉或〈种〉。“术”作量词搭配时用“门”或“种”，“只”用于动物或成对的东西，不能搭配“治病之术”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学了一条养家之术，生活好了很多。", "corrected_sentence": "他学了一门养家之术，生活好了很多。", "error_description": "错误：量词「条」用错。「术」搭配量词时应用「门」，不能用「条」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学会了一只谈判之术，合同签得很顺利。", "corrected_sentence": "他学会了一门谈判之术，合同签得很顺利。", "error_description": "错误：量词「只」用错。「术」搭配量词时应用「门」，不能用「只」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdad047-1e62-48ae-b1ce-1454e683b637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
