INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92439, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "秋是天气变凉、叶子变黄的季节。", "primary_collocate": null, "pronunciation": "qiū", "ipa": "tɕʰjoʊ˥", "syllable_count": 1, "sentences": [{"text": "秋到了，树叶慢慢变黄了。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的秋很凉快，叶子都黄了。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢秋，天气不冷也不热。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋一来，早上就有点凉了。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的秋很美，地上都是黄叶。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏去秋来，天气慢慢变凉了。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的秋很短，一下子就冷了。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的秋来得早，叶子很快就黄了。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，秋到了，要多穿一件衣服。", "target_word": "秋", "complexity_tier": "T3", "furigana": "qiū", "sentence_source": "generated"}, {"text": "山上的秋，红叶黄叶都很好看。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "秋天", "label": "复合"}, {"form": "秋季", "label": "复合"}], "register": "中性", "sense_fingerprint": "天气变凉、树叶变黄的季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92439, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "秋", "is_correct": true, "explanation": "正确答案：秋（qiū），指天气变凉、树叶变黄的季节。"}, {"text": "球", "is_correct": false, "explanation": "球（qiú，第二声）与秋（qiū，第一声）声调不同，意思是球。"}, {"text": "修", "is_correct": false, "explanation": "修（xiū）与秋（qiū）声母不同，意思是修理。"}, {"text": "七", "is_correct": false, "explanation": "七（qī）与秋（qiū）韵母不同，意思是数字七。"}], "explanations": {"秋": "正确答案：秋（qiū），指天气变凉、树叶变黄的季节。", "球": "球（qiú，第二声）与秋（qiū，第一声）声调不同，意思是球。", "修": "修（xiū）与秋（qiū）声母不同，意思是修理。", "七": "七（qī）与秋（qiū）韵母不同，意思是数字七。"}, "sentence_index": null, "correct_answer": "秋"}, "level_3": {"options": [{"text": "秋", "is_correct": true, "explanation": "正确答案：“秋”指树叶变黄的季节，符合“秋到了，树叶慢慢变黄了”。"}, {"text": "春", "is_correct": false, "explanation": "语义：春天树叶发芽变绿，不会慢慢变黄。"}, {"text": "冬", "is_correct": false, "explanation": "语义：冬天树叶已经落光，不会再慢慢变黄。"}, {"text": "雪", "is_correct": false, "explanation": "搭配：“变黄”是树叶的变化，不能说“雪到了，树叶慢慢变黄”。"}], "explanations": {"秋": "正确答案：“秋”指树叶变黄的季节，符合“秋到了，树叶慢慢变黄了”。", "春": "语义：春天树叶发芽变绿，不会慢慢变黄。", "冬": "语义：冬天树叶已经落光，不会再慢慢变黄。", "雪": "搭配：“变黄”是树叶的变化，不能说“雪到了，树叶慢慢变黄”。"}, "sentence_index": 0, "correct_answer": "秋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在老家度过了一只秋。", "explanation": "这里应该用〈个〉。量词“只”用于动物，季节不能用“只”。"}, {"text": "他把秋吃完了。", "explanation": "“秋”是季节，是时间，不是食物，不能“吃完”。"}, {"text": "我们在山里过了一条秋。", "explanation": "这里应该用〈个〉。量词“条”用于细长的东西，不能用于季节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92439, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "秋", "is_correct": true, "explanation": "正确答案：秋（qiū），指一年中的季节。"}, {"text": "求", "is_correct": false, "explanation": "求（qiú，第二声）与秋（qiū，第一声）声调不同，意思是请求。"}, {"text": "休", "is_correct": false, "explanation": "休（xiū）与秋（qiū）声母不同，意思是休息。"}, {"text": "期", "is_correct": false, "explanation": "期（qī）与秋（qiū）韵母不同，意思是时期。"}], "explanations": {"秋": "正确答案：秋（qiū），指一年中的季节。", "求": "求（qiú，第二声）与秋（qiū，第一声）声调不同，意思是请求。", "休": "休（xiū）与秋（qiū）声母不同，意思是休息。", "期": "期（qī）与秋（qiū）韵母不同，意思是时期。"}, "sentence_index": null, "correct_answer": "秋"}, "level_3": {"options": [{"text": "秋", "is_correct": true, "explanation": "正确答案：“秋”指天气变凉的季节，符合“这个城市的秋很短，一下子就冷了”。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“水”不能用“很短”形容，不合句意。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“很短”是说时间长度，不能用来形容树叶。"}, {"text": "冰", "is_correct": false, "explanation": "搭配：“很短”不能用来形容冰。"}], "explanations": {"秋": "正确答案：“秋”指天气变凉的季节，符合“这个城市的秋很短，一下子就冷了”。", "水": "搭配：“水”不能用“很短”形容，不合句意。", "树叶": "搭配：“很短”是说时间长度，不能用来形容树叶。", "冰": "搭配：“很短”不能用来形容冰。"}, "sentence_index": 6, "correct_answer": "秋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在北京住了一根秋。", "explanation": "这里应该用〈个〉。量词“根”用于细长的东西，季节不能用“根”。"}, {"text": "我们坐在秋上聊天。", "explanation": "“秋”是时间，不是可以坐的地方，不能说“坐在秋上”。"}, {"text": "他把秋放进了箱子里。", "explanation": "“秋”是时间，不是具体的东西，不能放进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只秋天特别凉快。", "corrected_sentence": "这个秋天特别凉快。", "error_description": "错误：量词“只”用于动物，季节要用量词“个”。正确：“这个秋天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条秋天很快就过去了。", "corrected_sentence": "一个秋天很快就过去了。", "error_description": "错误：量词“条”用于细长的东西，季节要用量词“个”。正确：“一个秋天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
