INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年中的第三个季节。", "primary_collocate": null, "pronunciation": "qiū", "ipa": "tɕʰjoʊ˥", "syllable_count": 1, "sentences": [{"text": "春、夏、秋、冬是一年的四个季节。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋是一年中的第三个季节。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九月到十一月是北京的秋。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春去夏来，夏走秋到，一年又过了大半。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年秋，我们全家去了上海。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年有四季，春夏秋冬，秋排第三。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年秋，我们要去北京。", "target_word": "秋", "complexity_tier": "T3", "furigana": "qiū", "sentence_source": "generated"}, {"text": "夏天以后就是秋。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋以后是冬，冬以后是春。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的秋比去年来得晚。", "target_word": "秋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "秋天", "label": "复合"}, {"form": "秋季", "label": "复合"}], "register": "中性", "sense_fingerprint": "一年四季中排第三的季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92440, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "秋", "is_correct": true, "explanation": "正确答案：秋（qiū），指一年中排第三的季节。"}, {"text": "球", "is_correct": false, "explanation": "球（qiú，第二声）与秋（qiū，第一声）声调不同，意思是球。"}, {"text": "修", "is_correct": false, "explanation": "修（xiū）与秋（qiū）声母不同，意思是修理。"}, {"text": "七", "is_correct": false, "explanation": "七（qī）与秋（qiū）韵母不同，意思是数字七。"}], "explanations": {"秋": "正确答案：秋（qiū），指一年中排第三的季节。", "球": "球（qiú，第二声）与秋（qiū，第一声）声调不同，意思是球。", "修": "修（xiū）与秋（qiū）声母不同，意思是修理。", "七": "七（qī）与秋（qiū）韵母不同，意思是数字七。"}, "sentence_index": null, "correct_answer": "秋"}, "level_3": {"options": [{"text": "秋", "is_correct": true, "explanation": "正确答案：“秋”是四季之一，符合“春、夏、秋、冬是一年的四个季节”。"}, {"text": "春", "is_correct": false, "explanation": "搭配：四季列举中不能重复“春”。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是季节，不能和其他季节并列。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪不是季节，不能和其他季节并列。"}], "explanations": {"秋": "正确答案：“秋”是四季之一，符合“春、夏、秋、冬是一年的四个季节”。", "春": "搭配：四季列举中不能重复“春”。", "雨": "语义：雨不是季节，不能和其他季节并列。", "雪": "语义：雪不是季节，不能和其他季节并列。"}, "sentence_index": 0, "correct_answer": "秋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在老家度过了一根秋。", "explanation": "这里应该用〈个〉。量词“根”用于细长的东西，季节不能用“根”。"}, {"text": "学校在秋里开学。", "explanation": "“秋”是时间词，不能当地点名词用，应说“在秋天里”。"}, {"text": "我们在山里过了一只秋。", "explanation": "这里应该用〈个〉。量词“只”用于动物，季节不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92440, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "秋", "is_correct": true, "explanation": "正确答案：秋（qiū），指一年中排第三的季节。"}, {"text": "求", "is_correct": false, "explanation": "求（qiú，第二声）与秋（qiū，第一声）声调不同，意思是请求。"}, {"text": "休", "is_correct": false, "explanation": "休（xiū）与秋（qiū）声母不同，意思是休息。"}, {"text": "期", "is_correct": false, "explanation": "期（qī）与秋（qiū）韵母不同，意思是时期。"}], "explanations": {"秋": "正确答案：秋（qiū），指一年中排第三的季节。", "求": "求（qiú，第二声）与秋（qiū，第一声）声调不同，意思是请求。", "休": "休（xiū）与秋（qiū）声母不同，意思是休息。", "期": "期（qī）与秋（qiū）韵母不同，意思是时期。"}, "sentence_index": null, "correct_answer": "秋"}, "level_3": {"options": [{"text": "秋", "is_correct": true, "explanation": "正确答案：“秋”是季节，符合“今年秋，我们要去北京”。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：昨天已经过去，与“要去”矛盾。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：“今年”和“去年”不能同时作时间状语。"}, {"text": "上周", "is_correct": false, "explanation": "语义：上周已经过去，与“要去”矛盾。"}], "explanations": {"秋": "正确答案：“秋”是季节，符合“今年秋，我们要去北京”。", "昨天": "语义：昨天已经过去，与“要去”矛盾。", "去年": "搭配：“今年”和“去年”不能同时作时间状语。", "上周": "语义：上周已经过去，与“要去”矛盾。"}, "sentence_index": 6, "correct_answer": "秋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在北京住了一张秋。", "explanation": "这里应该用〈个〉。量词“张”用于平面的东西，季节不能用“张”。"}, {"text": "他把秋搬进了屋子。", "explanation": "“秋”是时间，不是可以搬动的东西。"}, {"text": "她把秋送给了朋友。", "explanation": "“秋”是时间，不能当作礼物送给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校在很秋季开学。", "corrected_sentence": "学校在秋季开学。", "error_description": "错误：程度副词“很”不能修饰时间名词“秋季”，应删去“很”。正确：“学校在秋季开学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一场秋天过得很快。", "corrected_sentence": "一个秋天过得很快。", "error_description": "错误：量词“场”用于活动或事件，不用于季节。正确：“一个秋天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
