INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92443, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事时身体和脑子的力气。", "primary_collocate": null, "pronunciation": "jīng lì", "ipa": "tɕiŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "学外语要花很多时间和精力。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有精力再做别的事了。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事花了他不少精力。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把全部精力用在工作上。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带孩子很费精力。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把精力浪费在小事上。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个项目需要大量精力。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写论文用掉了他很多精力。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把精力集中在学习上。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人管三家店，精力不够。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做事要付出的身体和脑力，如花精力、费精力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92443, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精力", "is_correct": true, "explanation": "正确。精力指做事时身体和脑子的力气。"}, {"text": "经理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是负责管理的人。"}, {"text": "警力", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是警察的力量或人员。"}, {"text": "净利", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是扣除成本后的利润。"}], "explanations": {"精力": "正确。精力指做事时身体和脑子的力气。", "经理": "lǐ（第三声）与 lì（第四声）声调不同，意思是负责管理的人。", "警力": "jǐng（第三声）与 jīng（第一声）声调不同，意思是警察的力量或人员。", "净利": "jìng（第四声）与 jīng（第一声）声调不同，意思是扣除成本后的利润。"}, "sentence_index": null, "correct_answer": "精力"}, "level_3": {"options": [{"text": "精力", "is_correct": true, "explanation": "正确。“花……时间和”后面接的是付出的身体和脑力，“精力”符合语境。"}, {"text": "电量", "is_correct": false, "explanation": "搭配：“花”后面接“时间、金钱、精力”一类，不能说“花电量”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人身体的温度，与学习所花的付出无关。"}, {"text": "运费", "is_correct": false, "explanation": "语义：“运费”指运输货物的费用，不能用在学外语上。"}], "explanations": {"精力": "正确。“花……时间和”后面接的是付出的身体和脑力，“精力”符合语境。", "电量": "搭配：“花”后面接“时间、金钱、精力”一类，不能说“花电量”。", "体温": "语义：“体温”指人身体的温度，与学习所花的付出无关。", "运费": "语义：“运费”指运输货物的费用，不能用在学外语上。"}, "sentence_index": 0, "correct_answer": "精力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "核电站每天产生巨大的精力。", "explanation": "这里应该用〈能量〉。精力只指人的精神和体力，核电站产生的是能量。"}, {"text": "这个国家的精力非常强大，能影响整个世界。", "explanation": "这里应该用〈力量〉。精力指人做事时身体和脑子的力气，国家的影响力要说“力量”。"}, {"text": "他有一把精力，每天都能工作十几个小时。", "explanation": "量词不对：“把”用于有柄的器具，精力是抽象的，不用“把”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92443, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "精力", "is_correct": true, "explanation": "正确。精力指做事时身体和脑子的力气。"}, {"text": "筋力", "is_correct": false, "explanation": "jīn 与 jīng 韵尾不同（-n 与 -ng），意思是肌肉的力量。"}, {"text": "精密", "is_correct": false, "explanation": "mì（第四声）与 lì（第四声）声母不同（m 与 l），意思是精确、细密。"}, {"text": "净利", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是扣除成本后的利润。"}], "explanations": {"精力": "正确。精力指做事时身体和脑子的力气。", "筋力": "jīn 与 jīng 韵尾不同（-n 与 -ng），意思是肌肉的力量。", "精密": "mì（第四声）与 lì（第四声）声母不同（m 与 l），意思是精确、细密。", "净利": "jìng（第四声）与 jīng（第一声）声调不同，意思是扣除成本后的利润。"}, "sentence_index": null, "correct_answer": "精力"}, "level_3": {"options": [{"text": "精力", "is_correct": true, "explanation": "正确。“需要大量”后面接的是付出的身体和脑力，“精力”符合语境。"}, {"text": "酒量", "is_correct": false, "explanation": "搭配：“酒量”只说“大”或“小”，不能说“需要大量酒量”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，做项目不需要“大量年龄”。"}, {"text": "视力", "is_correct": false, "explanation": "语义：“视力”指眼睛看清东西的能力，与做项目所需的付出不相关。"}], "explanations": {"精力": "正确。“需要大量”后面接的是付出的身体和脑力，“精力”符合语境。", "酒量": "搭配：“酒量”只说“大”或“小”，不能说“需要大量酒量”。", "年龄": "语义：“年龄”指岁数，做项目不需要“大量年龄”。", "视力": "语义：“视力”指眼睛看清东西的能力，与做项目所需的付出不相关。"}, "sentence_index": 6, "correct_answer": "精力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座电站每年提供大量精力。", "explanation": "这里应该用〈电力〉。精力指人的精神和体力，发电站提供的是电力。"}, {"text": "这个国家缺少精力。", "explanation": "这里应该用〈能源〉。精力只指人的精神和体力，国家缺的是能源。"}, {"text": "她有一座精力，干活从来不累。", "explanation": "量词不对：“座”用于山、桥、楼一类大型固定的东西，精力是抽象的，不用“座”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "照顾老人很费一台精力。", "corrected_sentence": "照顾老人很费精力。", "error_description": "错误在“精力”前面多加了量词“台”。精力是抽象的，不用“台”计量，应说“很费精力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作很耗了精力，他常常很累。", "corrected_sentence": "这份工作很耗精力，他常常很累。", "error_description": "错误：「耗」后面多加了「了」。「很」不能修饰带「了」的动作，应说「很耗精力」，不说「很耗了精力」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
