INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "精神和体力。", "primary_collocate": null, "pronunciation": "jīng lì", "ipa": "tɕiŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他年纪大了，精力不如从前。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的精力很旺盛，一天都不累。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天精力充沛地去上班。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡好觉，第二天才有精力。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的精力一天比一天差。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完早饭，我的精力就恢复了不少。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动让我一整天都精力十足。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人精力好，晚上也不觉得累。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的精力真好，一晚上没睡也不累。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他精力旺盛，每天早上都去跑步。", "target_word": "精力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人的精神状态和体力是否充足，如精力旺盛、精力不如从前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92444, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精力", "is_correct": true, "explanation": "正确。精力指精神和体力。"}, {"text": "经理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是负责管理的人。"}, {"text": "警力", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是警察的力量或人员。"}, {"text": "净利", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是扣除成本后的利润。"}], "explanations": {"精力": "正确。精力指精神和体力。", "经理": "lǐ（第三声）与 lì（第四声）声调不同，意思是负责管理的人。", "警力": "jǐng（第三声）与 jīng（第一声）声调不同，意思是警察的力量或人员。", "净利": "jìng（第四声）与 jīng（第一声）声调不同，意思是扣除成本后的利润。"}, "sentence_index": null, "correct_answer": "精力"}, "level_3": {"options": [{"text": "精力", "is_correct": true, "explanation": "正确。“不如从前”说的是精神和体力的减弱，只有“精力”能与之搭配。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”指上学交的钱，与人的状态变化无关，句子说不通。"}, {"text": "油价", "is_correct": false, "explanation": "语义：“油价”是油的价格，与人的精力状况无关，句子说不通。"}, {"text": "房价", "is_correct": false, "explanation": "语义：“房价”是房子的价格，与“年纪大了”没有关系。"}], "explanations": {"精力": "正确。“不如从前”说的是精神和体力的减弱，只有“精力”能与之搭配。", "学费": "语义：“学费”指上学交的钱，与人的状态变化无关，句子说不通。", "油价": "语义：“油价”是油的价格，与人的精力状况无关，句子说不通。", "房价": "语义：“房价”是房子的价格，与“年纪大了”没有关系。"}, "sentence_index": 0, "correct_answer": "精力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台发动机的精力很强，能带动整个工厂。", "explanation": "这里应该用〈能量〉。精力指人做事时的精神和体力，机器的动力要说“能量”。"}, {"text": "这股精力很大，能推动历史前进。", "explanation": "这里应该用〈力量〉。精力只指人的精神和体力，不能用来说事物或社会的推动力。"}, {"text": "他有一台精力，做事很快。", "explanation": "量词不对：“台”用于机器等有形的物件，精力是抽象的，不用“台”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92444, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "精力", "is_correct": true, "explanation": "正确。精力指精神和体力。"}, {"text": "筋力", "is_correct": false, "explanation": "jīn 与 jīng 韵尾不同（-n 与 -ng），意思是肌肉的力量。"}, {"text": "精密", "is_correct": false, "explanation": "mì（第四声）与 lì（第四声）声母不同（m 与 l），意思是精确、细密。"}, {"text": "净利", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是扣除成本后的利润。"}], "explanations": {"精力": "正确。精力指精神和体力。", "筋力": "jīn 与 jīng 韵尾不同（-n 与 -ng），意思是肌肉的力量。", "精密": "mì（第四声）与 lì（第四声）声母不同（m 与 l），意思是精确、细密。", "净利": "jìng（第四声）与 jīng（第一声）声调不同，意思是扣除成本后的利润。"}, "sentence_index": null, "correct_answer": "精力"}, "level_3": {"options": [{"text": "精力", "is_correct": true, "explanation": "正确。“精力十足”说的是精神充沛，符合运动后的感受。"}, {"text": "肥料", "is_correct": false, "explanation": "语义：“肥料”指施给植物的养料，不能用来形容人的状态。"}, {"text": "容貌", "is_correct": false, "explanation": "语义：“容貌”指长相，运动不会让人“容貌十足”，句子说不通。"}, {"text": "资金", "is_correct": false, "explanation": "语义：“资金”指钱和经费，与运动带来的身体感受无关。"}], "explanations": {"精力": "正确。“精力十足”说的是精神充沛，符合运动后的感受。", "肥料": "语义：“肥料”指施给植物的养料，不能用来形容人的状态。", "容貌": "语义：“容貌”指长相，运动不会让人“容貌十足”，句子说不通。", "资金": "语义：“资金”指钱和经费，与运动带来的身体感受无关。"}, "sentence_index": 6, "correct_answer": "精力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的精力很足，能跑很远的路。", "explanation": "这里应该用〈能量〉。精力指人的精神和体力，车的动力要说“能量”。"}, {"text": "他在公司的精力很大，说话很有分量。", "explanation": "这里应该用〈力量〉。精力只指人的精神和体力，不能用来说人在公司里的影响力。"}, {"text": "他有一颗精力，每天都很有干劲。", "explanation": "量词不对：“颗”用于粒状的东西，精力是抽象的，不用“颗”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶的一台精力很充沛，每天都去公园散步。", "corrected_sentence": "奶奶的精力很充沛，每天都去公园散步。", "error_description": "错误在“精力”前面多加了量词“台”。精力是抽象的，不用“台”计量，应说“精力很充沛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃了药以后，他的精力了比以前好多了。", "corrected_sentence": "吃了药以后，他的精力比以前好多了。", "error_description": "“了”放错了位置。“了”不能紧跟在“精力”后面，应放在句末，说“他的精力比以前好多了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92447, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "市场经济", "is_correct": true, "explanation": "反义：“市场经济”与“计划经济”是相对的两种经济体制。"}, {"text": "天气", "is_correct": false, "explanation": "无反义关系：“天气”指一段时间内的冷暖阴晴，与“计划经济”没有相对的关系。"}, {"text": "足球", "is_correct": false, "explanation": "无反义关系：“足球”指一项体育运动，与“计划经济”没有相对的关系。"}, {"text": "厨房", "is_correct": false, "explanation": "无反义关系：“厨房”指做饭的地方，与“计划经济”没有相对的关系。"}], "correct_answer": "市场经济", "explanations": {"市场经济": "反义：“市场经济”与“计划经济”是相对的两种经济体制。", "天气": "无反义关系：“天气”指一段时间内的冷暖阴晴，与“计划经济”没有相对的关系。", "足球": "无反义关系：“足球”指一项体育运动，与“计划经济”没有相对的关系。", "厨房": "无反义关系：“厨房”指做饭的地方，与“计划经济”没有相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92447, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "市场经济", "is_correct": true, "explanation": "反义：“市场经济”与“计划经济”是相对的两种经济体制。"}, {"text": "水果", "is_correct": false, "explanation": "无反义关系：“水果”指可以吃的果实，与“计划经济”没有相对的关系。"}, {"text": "教室", "is_correct": false, "explanation": "无反义关系：“教室”指上课的房间，与“计划经济”没有相对的关系。"}, {"text": "电影", "is_correct": false, "explanation": "无反义关系：“电影”指用影像讲故事的作品，与“计划经济”没有相对的关系。"}], "correct_answer": "市场经济", "explanations": {"市场经济": "反义：“市场经济”与“计划经济”是相对的两种经济体制。", "水果": "无反义关系：“水果”指可以吃的果实，与“计划经济”没有相对的关系。", "教室": "无反义关系：“教室”指上课的房间，与“计划经济”没有相对的关系。", "电影": "无反义关系：“电影”指用影像讲故事的作品，与“计划经济”没有相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92447, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "计划经济是国家事先安排好，要做多少东西。", "primary_collocate": null, "pronunciation": "jì huà jīng jì", "ipa": "tɕi˥˩ xwa˥˩ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "以前，国家实行计划经济。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在计划经济里，工厂做多少东西国家先定好。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计划经济时代，买东西常常要票。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，那时候是计划经济。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计划经济下，工人不用自己找生意。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是计划经济。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在计划经济的年代，店里东西不多。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的产量全由国家定，属于计划经济。", "target_word": "计划经济", "complexity_tier": "T3", "furigana": "zhè jiā gōngchǎng de chǎnliàng quán yóu guójiā dìng, shǔyú jìhuà jīngjì.", "sentence_source": "generated"}, {"text": "那个年代是计划经济，大家都有工作。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上问：计划经济是什么？", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "計劃經濟", "label": "繁体"}, {"form": "计划经济体制", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家先定好各种东西要做多少的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92447, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：“手机”不是可以“实行”的经济制度，国家实行手机没有意义。"}, {"text": "计划经济", "is_correct": true, "explanation": "“计划经济”指国家事先安排生产的经济体制，与“以前，国家实行”相合。"}, {"text": "外卖", "is_correct": false, "explanation": "语义：“外卖”指送餐服务，不能说国家实行外卖。"}, {"text": "体育", "is_correct": false, "explanation": "搭配：“实行”多搭配制度、政策，不搭配“体育”。"}], "explanations": {"手机": "语义：“手机”不是可以“实行”的经济制度，国家实行手机没有意义。", "计划经济": "“计划经济”指国家事先安排生产的经济体制，与“以前，国家实行”相合。", "外卖": "语义：“外卖”指送餐服务，不能说国家实行外卖。", "体育": "搭配：“实行”多搭配制度、政策，不搭配“体育”。"}, "sentence_index": 0, "correct_answer": "计划经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的计划经济做得很好。", "explanation": "这里应该用〈学习计划〉。计划经济专指国家统一安排生产与分配的经济体制，班级的学习计划不叫计划经济。"}, {"text": "这家餐厅每天都在计划经济，提前备菜。", "explanation": "这里应该用〈计划〉。计划经济是名词，指国家统一安排生产的经济体制，不能当动词用。"}, {"text": "我们公司负责做计划经济的工作。", "explanation": "这里应该用〈计划工作〉。计划经济是一种经济体制，不是具体可以“负责”的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：“诗歌”是文学作品，不能指一个经济背景的年代。"}, {"text": "计划经济", "is_correct": true, "explanation": "“计划经济”指国家事先安排的经济体制，与“那个年代店里东西不多”相合。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：“篮球”是一项运动，不能指那个年代。"}, {"text": "土豪", "is_correct": false, "explanation": "语域：“土豪”是口语网络用语，不适合这样的书面叙述。"}], "explanations": {"诗歌": "语义：“诗歌”是文学作品，不能指一个经济背景的年代。", "计划经济": "“计划经济”指国家事先安排的经济体制，与“那个年代店里东西不多”相合。", "篮球": "语义：“篮球”是一项运动，不能指那个年代。", "土豪": "语域：“土豪”是口语网络用语，不适合这样的书面叙述。"}, "sentence_index": 6, "correct_answer": "计划经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写了一份计划经济。", "explanation": "这里应该用〈计划书〉。计划经济是经济体制，不是可以写成的文件。"}, {"text": "这家公司每天都在计划经济，然后去找客户。", "explanation": "这里应该用〈计划〉。计划经济是名词，指国家统一安排生产的经济体制，不能当动词用。"}, {"text": "我的计划经济已经定好了，下周去旅行。", "explanation": "这里应该用〈打算〉。个人的安排只能说“打算”，计划经济专指国家统一安排的经济体制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家曾经采用一只计划经济。", "corrected_sentence": "这个国家曾经采用一种计划经济。", "error_description": "“只”是用于动物等的量词，计划经济是一种体制，应用“种”。正确为“一种计划经济”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那时候，工厂的产量都由国家决定，这是一只计划经济。", "corrected_sentence": "那时候，工厂的产量都由国家决定，这是一种计划经济。", "error_description": "错误在于量词用错。“只”用于动物等，计划经济是一种体制，应用“种”，说“一种计划经济”，不能说“一只计划经济”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92448, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "市场经济", "is_correct": true, "explanation": "反义：“市场经济”与“计划经济”是相对的两种经济体制。"}, {"text": "钢琴", "is_correct": false, "explanation": "无反义关系：“钢琴”是一种乐器，与“计划经济”没有相对的关系。"}, {"text": "海洋", "is_correct": false, "explanation": "无反义关系：“海洋”指大面积的咸水，与“计划经济”没有相对的关系。"}, {"text": "车站", "is_correct": false, "explanation": "无反义关系：“车站”指供车辆停靠、乘客上下的地方，与“计划经济”没有相对的关系。"}], "correct_answer": "市场经济", "explanations": {"市场经济": "反义：“市场经济”与“计划经济”是相对的两种经济体制。", "钢琴": "无反义关系：“钢琴”是一种乐器，与“计划经济”没有相对的关系。", "海洋": "无反义关系：“海洋”指大面积的咸水，与“计划经济”没有相对的关系。", "车站": "无反义关系：“车站”指供车辆停靠、乘客上下的地方，与“计划经济”没有相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92448, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "市场经济", "is_correct": true, "explanation": "反义：“市场经济”与“计划经济”是相对的两种经济体制。"}, {"text": "书包", "is_correct": false, "explanation": "无反义关系：“书包”是装书本的袋子，与“计划经济”没有相对的关系。"}, {"text": "公园", "is_correct": false, "explanation": "无反义关系：“公园”是供人游玩休息的场所，与“计划经济”没有相对的关系。"}, {"text": "面包", "is_correct": false, "explanation": "无反义关系：“面包”是一种食物，与“计划经济”没有相对的关系。"}], "correct_answer": "市场经济", "explanations": {"市场经济": "反义：“市场经济”与“计划经济”是相对的两种经济体制。", "书包": "无反义关系：“书包”是装书本的袋子，与“计划经济”没有相对的关系。", "公园": "无反义关系：“公园”是供人游玩休息的场所，与“计划经济”没有相对的关系。", "面包": "无反义关系：“面包”是一种食物，与“计划经济”没有相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由国家统一制订计划，调配资源和生产分配的经济体制。", "primary_collocate": null, "pronunciation": "jì huà jīng jì", "ipa": "tɕi˥˩ xwa˥˩ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "计划经济由国家统一制订生产计划。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计划经济和市场经济是两种不同的体制。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实行计划经济的国家，资源由政府调配。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计划经济要求国家管好生产和分配。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的经济以前主要是计划经济。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本里介绍了计划经济的特点。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计划经济中，价格常常由国家来定。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的国家把计划经济改成了市场经济。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者比较了计划经济和市场经济。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计划经济的好处是国家能统一安排。", "target_word": "计划经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "計劃經濟", "label": "繁体"}, {"form": "计划经济体制", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家统一制订计划、调配资源的经济体制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：“诗歌”是文学体裁，不能由国家统一制订生产计划。"}, {"text": "计划经济", "is_correct": true, "explanation": "“计划经济”指国家统一制订计划、调配资源的经济体制，与“由国家统一制订生产计划”相合。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：“篮球”是运动项目，不能由国家制订生产计划。"}, {"text": "土豪", "is_correct": false, "explanation": "语域：“土豪”是口语网络用语，不适合用在这样的书面说明中。"}], "explanations": {"诗歌": "语义：“诗歌”是文学体裁，不能由国家统一制订生产计划。", "计划经济": "“计划经济”指国家统一制订计划、调配资源的经济体制，与“由国家统一制订生产计划”相合。", "篮球": "语义：“篮球”是运动项目，不能由国家制订生产计划。", "土豪": "语域：“土豪”是口语网络用语，不适合用在这样的书面说明中。"}, "sentence_index": 0, "correct_answer": "计划经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市每天都在计划经济。", "explanation": "这里应该用〈规划〉。计划经济是名词，指国家统一安排的经济体制，不能当动词用。"}, {"text": "这次旅行的计划经济很完整，我们都很满意。", "explanation": "这里应该用〈行程〉。计划经济不用来指旅行的安排，应说“行程”。"}, {"text": "学生们的计划经济很完整，大家都按时完成了作业。", "explanation": "这里应该用〈学习计划〉。计划经济指国家统一安排生产与分配的经济体制，学生的学习安排不能叫计划经济。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花朵", "is_correct": false, "explanation": "语义：“花朵”是植物的部分，不能由国家来定。"}, {"text": "计划经济", "is_correct": true, "explanation": "“计划经济”中由国家决定价格，与“价格常常由国家来定”相合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”是自然景象，不能由国家来定。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“由……来定”多用于价格、规定，不用于“性格”。"}], "explanations": {"花朵": "语义：“花朵”是植物的部分，不能由国家来定。", "计划经济": "“计划经济”中由国家决定价格，与“价格常常由国家来定”相合。", "天空": "语义：“天空”是自然景象，不能由国家来定。", "性格": "搭配：“由……来定”多用于价格、规定，不用于“性格”。"}, "sentence_index": 6, "correct_answer": "计划经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的计划经济很简单。", "explanation": "这里应该用〈规则〉。计划经济是国家的经济体制，比赛的规定应说“规则”。"}, {"text": "我把计划经济发给了每个人。", "explanation": "这里应该用〈通知〉。计划经济是体制，不是可以发给人的纸张，应说“通知”。"}, {"text": "这所学校每天都在计划经济，老师很忙。", "explanation": "这里应该用〈计划〉。计划经济是名词，指国家统一安排的经济体制，不能当动词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当时的国家规定了企业的产量，这就是一条计划经济。", "corrected_sentence": "当时的国家规定了企业的产量，这就是一种计划经济。", "error_description": "“条”用于河流、道路等细长事物，计划经济是一种体制，应用“种”。正确为“一种计划经济”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "企业的生产和分配都由国家安排，这是一棵计划经济。", "corrected_sentence": "企业的生产和分配都由国家安排，这是一种计划经济。", "error_description": "“棵”用于树木等植物，计划经济是一种体制，应用“种”。正确为“一种计划经济”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
