INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "站台是车站里等车的地方。", "primary_collocate": null, "pronunciation": "zhàn tái", "ipa": "ʈʂan˥˩ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "我们在站台上等火车。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站台上有很多人在等车。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在站台的椅子上。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站台很干净，也很安静。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在站台上给妈妈挥手。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家都站在站台的棚子下。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车还没来，站台上人越来越多。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人在站台等了半小时。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在第二个站台等你。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站台上的广播说，火车晚点了。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地铁站台", "label": "复合"}, {"form": "火车站台", "label": "复合"}], "register": "中性", "sense_fingerprint": "车站里供人等车的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92451, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站台", "is_correct": true, "explanation": "站台是车站里供乘客等车的平台，“在站台上等火车”是自然的说法。"}, {"text": "车厢", "is_correct": false, "explanation": "语义：车厢是列车里供人乘坐的部分，不是等车的地方，“在车厢上等火车”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是车站里等车的地方，放在这里句子说不通。"}, {"text": "候车室", "is_correct": false, "explanation": "搭配：“候车室”是有墙的室内空间，要说“在候车室里”，不能用“上”。"}], "explanations": {"站台": "站台是车站里供乘客等车的平台，“在站台上等火车”是自然的说法。", "车厢": "语义：车厢是列车里供人乘坐的部分，不是等车的地方，“在车厢上等火车”说不通。", "桌子": "语义：桌子不是车站里等车的地方，放在这里句子说不通。", "候车室": "搭配：“候车室”是有墙的室内空间，要说“在候车室里”，不能用“上”。"}, "sentence_index": 0, "correct_answer": "站台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个站台有五层楼，很多人在里面买票。", "explanation": "这里应该用〈车站〉。站台只是供乘客等车的平台，没有楼层和售票处，不能指整座建筑。"}, {"text": "妈妈在站台上种了很多花，每天浇水。", "explanation": "这里应该用〈花坛〉。站台是供乘客等车的平台，不能用来种花；种花的地方是花坛。"}, {"text": "老师站在站台上讲课，学生们都在下面听。", "explanation": "这里应该用〈讲台〉。讲台是教室里供老师讲课的台子；站台是车站里供乘客等车的平台，不能用来讲课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92451, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "站台", "is_correct": true, "explanation": "“车还没来，站台上人越来越多”中，等车的人群聚在站台上，这里的“站台”正确。"}, {"text": "窗口", "is_correct": false, "explanation": "搭配：说人群聚集在窗口，要用“窗口前”，不能说“窗口上”。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是屋里的家具，等车的人群不会聚在书桌上，句子说不通。"}, {"text": "水池", "is_correct": false, "explanation": "语义：水池是盛水的设施，人群不会聚在水池上，与“等车”的语境不符。"}], "explanations": {"站台": "“车还没来，站台上人越来越多”中，等车的人群聚在站台上，这里的“站台”正确。", "窗口": "搭配：说人群聚集在窗口，要用“窗口前”，不能说“窗口上”。", "书桌": "语义：书桌是屋里的家具，等车的人群不会聚在书桌上，句子说不通。", "水池": "语义：水池是盛水的设施，人群不会聚在水池上，与“等车”的语境不符。"}, "sentence_index": 6, "correct_answer": "站台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本站台又长又宽，等车的人很多。", "explanation": "这里应该用〈个〉。〈本〉用于书、本子一类的东西；站台是平台，不能用〈本〉计量。"}, {"text": "这把站台很干净，我们在上面等车。", "explanation": "这里应该用〈个〉。〈把〉用于有柄或能拿起来的东西，如椅子、伞、刀；站台不能用〈把〉计量。"}, {"text": "一扇站台前站满了人。", "explanation": "这里应该用〈个〉。〈扇〉用于门、窗之类的东西，站台是平台，不能用〈扇〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在站台上了等二十分钟。", "corrected_sentence": "我们在站台上等了二十分钟。", "error_description": "错误：“了”放错了位置，应紧跟动词“等”，要说“在站台上等了二十分钟”，不能放在“站台上”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火车进站前，很多人已经站台上等着了。", "corrected_sentence": "火车进站前，很多人已经在站台上等着了。", "error_description": "错误：地点状语“站台上”前缺少介词“在”，要说“在站台上等着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
