INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "车站供乘客上下车的平台。", "primary_collocate": null, "pronunciation": "zhàn tái", "ipa": "ʈʂan˥˩ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "乘客从站台走上火车。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车停稳后，乘客走到站台上。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上车前请站在黄线后面的站台上。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在站台上打扫卫生。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心站台和列车之间的空隙。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个车站有四个站台。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提着行李走下火车，来到站台。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子从站台跑向刚下车的爸爸。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新建的站台又宽又长。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客只能在站台上下车。", "target_word": "站台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地铁站台", "label": "复合"}, {"form": "火车站台", "label": "复合"}], "register": "中性", "sense_fingerprint": "车站里供乘客上下车的平台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac744e40-6efc-45f3-935b-6099401ba30e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站台", "is_correct": true, "explanation": "“乘客从站台走上火车”中，乘客是从站台上车的，“站台”正确。"}, {"text": "车票", "is_correct": false, "explanation": "搭配：“从……走上”要接地点，“车票”不是地点，不能说“从车票走上火车”。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是要带上车的物品，不能作为乘客走上火车的路径。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是车厢里供人坐的地方，乘客不会“从座位走上火车”。"}], "explanations": {"站台": "“乘客从站台走上火车”中，乘客是从站台上车的，“站台”正确。", "车票": "搭配：“从……走上”要接地点，“车票”不是地点，不能说“从车票走上火车”。", "行李": "语义：行李是要带上车的物品，不能作为乘客走上火车的路径。", "座位": "语义：座位是车厢里供人坐的地方，乘客不会“从座位走上火车”。"}, "sentence_index": 0, "correct_answer": "站台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "站台关上后，列车慢慢开动了。", "explanation": "这里应该用〈车门〉。站台是固定的平台，不能关上；列车关门后才会开动。"}, {"text": "站台开着，风吹进来很凉快。", "explanation": "这里应该用〈车窗〉。站台是没有窗户的平台，不能说“开着”；能开着让风吹进来的是车窗。"}, {"text": "站台里有很多窗口，大家在排队买票。", "explanation": "这里应该用〈售票厅〉。站台没有售票窗口，大家排队买票的地方是售票厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "站台", "is_correct": true, "explanation": "“他提着行李走下火车，来到站台”中，他下车后来到的正是站台，“站台”正确。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是车厢或房屋的部件，不是可以“来到”的地点，句子说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，他走下火车不会“来到桌子”。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“来到”后要接地点，“书包”是物品，不能与“来到”搭配。"}], "explanations": {"站台": "“他提着行李走下火车，来到站台”中，他下车后来到的正是站台，“站台”正确。", "窗户": "语义：窗户是车厢或房屋的部件，不是可以“来到”的地点，句子说不通。", "桌子": "语义：桌子是家具，他走下火车不会“来到桌子”。", "书包": "搭配：“来到”后要接地点，“书包”是物品，不能与“来到”搭配。"}, "sentence_index": 6, "correct_answer": "站台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道站台又宽又长，乘客在上面等车。", "explanation": "这里应该用〈个〉。〈道〉多用于墙、门、河流等线状或屏障类的东西；站台是平台，不用〈道〉计量。"}, {"text": "这只站台很干净，乘客在上面等车。", "explanation": "这里应该用〈个〉。〈只〉多用于动物或成对的小东西；站台不能用〈只〉计量。"}, {"text": "这把站台很长，列车停在上面。", "explanation": "这里应该用〈个〉。〈把〉用于有柄或能拿起来的东西，如椅子、伞；站台不用〈把〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "乘客们都站台上等车。", "corrected_sentence": "乘客们都在站台上等车。", "error_description": "错误：地点状语“站台上”前缺少介词“在”。只需在“站台上”前补上“在”，应说“在站台上等车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "列车快到了，大家都站台上往前走。", "corrected_sentence": "列车快到了，大家都在站台上往前走。", "error_description": "错误：地点状语“站台上”前缺少介词“在”，要说“在站台上往前走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2cb7137-79f2-4b9c-ad24-a966302ee0bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92455, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中断", "is_correct": true, "explanation": "中断与“续”相对，指事情停下来，不再接着做。"}, {"text": "打开", "is_correct": false, "explanation": "与“续”无反义关系，“打开”指把关着的东西开启。"}, {"text": "收拾", "is_correct": false, "explanation": "与“续”无反义关系，“收拾”指整理、收起。"}, {"text": "唱", "is_correct": false, "explanation": "与“续”无反义关系，“唱”指发出歌声。"}], "correct_answer": "中断", "explanations": {"中断": "中断与“续”相对，指事情停下来，不再接着做。", "打开": "与“续”无反义关系，“打开”指把关着的东西开启。", "收拾": "与“续”无反义关系，“收拾”指整理、收起。", "唱": "与“续”无反义关系，“唱”指发出歌声。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
