INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92456, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92456, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接连；延长。", "primary_collocate": null, "pronunciation": "xù", "ipa": "ɕy˥˩", "syllable_count": 1, "sentences": [{"text": "房东同意我把租期续到明年。", "target_word": "续", "complexity_tier": "T3", "furigana": "fángdōng tóngyì wǒ bǎ zūqī xù dào míngnián", "sentence_source": "generated"}, {"text": "合同快到期了，我想再续一年。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的会员到期了，要续一个月。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的合作协议下个月到期，双方想续到年底。", "target_word": "续", "complexity_tier": "T3", "furigana": "wǒmen de hézuò xiéyì xià gè yuè dàoqī, shuāngfāng xiǎng xù dào niándǐ", "sentence_source": "generated"}, {"text": "租房合同下个月到期，我打算续三年。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份实习合同快到期了，公司说可以续一年。", "target_word": "续", "complexity_tier": "T3", "furigana": "zhè fèn shíxí hétong kuài dàoqī le, gōngsī shuō kěyǐ xù yī nián", "sentence_source": "generated"}, {"text": "他的签证到期了，想再续两个月。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个语言班的课程快结束了，我想续到明年夏天。", "target_word": "续", "complexity_tier": "T3", "furigana": "zhège yǔyán bān de kèchéng kuài jiéshù le, wǒ xiǎng xù dào míngnián xiàtiān", "sentence_source": "generated"}, {"text": "图书馆的书到期了，我上网续了一个月。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保险到期以后，你要不要再续一年？", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "续了", "label": "体标"}, {"form": "续过", "label": "体标"}, {"form": "续杯", "label": "复合"}, {"form": "續", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把水、合同、会员等接上并延长时间或数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b189c5-928f-4b14-9e03-b75e919a5733') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92456, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "续", "is_correct": true, "explanation": "正确答案。续（xù）意思是接着、延长。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 xù 声母不同，意思是离开。"}, {"text": "句", "is_correct": false, "explanation": "jù（第四声）与 xù 声母不同，意思是句子。"}, {"text": "许", "is_correct": false, "explanation": "xǔ（第三声）与 xù（第四声）声调不同，意思是允许。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 xù 韵母不同，意思是戏剧。"}, {"text": "巨", "is_correct": false, "explanation": "jù（第四声）与 xù 声母不同，意思是巨大。"}], "explanations": {"续": "正确答案。续（xù）意思是接着、延长。", "去": "qù（第四声）与 xù 声母不同，意思是离开。", "句": "jù（第四声）与 xù 声母不同，意思是句子。", "许": "xǔ（第三声）与 xù（第四声）声调不同，意思是允许。", "戏": "xì（第四声）与 xù 韵母不同，意思是戏剧。", "巨": "jù（第四声）与 xù 声母不同，意思是巨大。"}, "sentence_index": null, "correct_answer": "续"}, "level_3": {"options": [{"text": "续", "is_correct": true, "explanation": "正确。续在此表示把租期接着延长到明年。"}, {"text": "退", "is_correct": false, "explanation": "语义：“退”指退还、后退，“退到明年”不表示延长租期。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”指出售，与房东同意延长租期的语境不合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是口部动作，与租期无关。"}], "explanations": {"续": "正确。续在此表示把租期接着延长到明年。", "退": "语义：“退”指退还、后退，“退到明年”不表示延长租期。", "卖": "语义：“卖”指出售，与房东同意延长租期的语境不合。", "咬": "语义：“咬”是口部动作，与租期无关。"}, "sentence_index": 0, "correct_answer": "续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的工资续了两成。", "explanation": "这里应该用〈提高〉。续表示接续或延长期限，工资的上调要用提高，不能用续。"}, {"text": "这个月的菜价续了两成。", "explanation": "这里应该用〈上涨〉。续表示接续或延长，价格的涨幅要用上涨，不能用续。"}, {"text": "这座城市的人口续了十万。", "explanation": "这里应该用〈增长〉。续表示接续或延长期限，人口的增加要用增长，不能用续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92456, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "续", "is_correct": true, "explanation": "正确答案。续（xù）意思是接着、延长。"}, {"text": "聚", "is_correct": false, "explanation": "jù（第四声）与 xù 声母不同，意思是聚集。"}, {"text": "据", "is_correct": false, "explanation": "jù（第四声）与 xù 声母不同，意思是根据。"}, {"text": "需", "is_correct": false, "explanation": "xū（第一声）与 xù（第四声）声调不同，意思是需要。"}, {"text": "细", "is_correct": false, "explanation": "xì（第四声）与 xù 韵母不同，意思是细小。"}, {"text": "虚", "is_correct": false, "explanation": "xū（第一声）与 xù（第四声）声调不同，意思是虚假。"}], "explanations": {"续": "正确答案。续（xù）意思是接着、延长。", "聚": "jù（第四声）与 xù 声母不同，意思是聚集。", "据": "jù（第四声）与 xù 声母不同，意思是根据。", "需": "xū（第一声）与 xù（第四声）声调不同，意思是需要。", "细": "xì（第四声）与 xù 韵母不同，意思是细小。", "虚": "xū（第一声）与 xù（第四声）声调不同，意思是虚假。"}, "sentence_index": null, "correct_answer": "续"}, "level_3": {"options": [{"text": "续", "is_correct": true, "explanation": "正确。续在此表示把签证接着延长两个月。"}, {"text": "擦", "is_correct": false, "explanation": "配价：“擦”需要被擦的具体物体，“想再擦两个月”与签证无关。"}, {"text": "押", "is_correct": false, "explanation": "配价：“押”需要带被押的人或抵押物，不能押签证。"}, {"text": "剪", "is_correct": false, "explanation": "配价：“剪”需要被剪的对象，“想再剪两个月”不成立。"}], "explanations": {"续": "正确。续在此表示把签证接着延长两个月。", "擦": "配价：“擦”需要被擦的具体物体，“想再擦两个月”与签证无关。", "押": "配价：“押”需要带被押的人或抵押物，不能押签证。", "剪": "配价：“剪”需要被剪的对象，“想再剪两个月”不成立。"}, "sentence_index": 6, "correct_answer": "续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的库存续了一半。", "explanation": "这里应该用〈减少〉。续表示接续或延长，库存数量的变少要用减少，不能用续。"}, {"text": "今年的利率续了一个点。", "explanation": "这里应该用〈下降〉。续表示接续或延长，利率的降低要用下降，不能用续。"}, {"text": "这个班的人数续了不少。", "explanation": "这里应该用〈增加〉。续用于接续、延长期限，人数的增减要用增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的健身卡下个月到期，打算续了半年。", "corrected_sentence": "我的健身卡下个月到期，打算续半年。", "error_description": "“续”后面多加了“了”。“打算”表示将来的计划，不能与完成体“了”一起用，应去掉“了”，说“打算续半年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "网络套餐下个月到期，我想续再到明年。", "corrected_sentence": "网络套餐下个月到期，我想再续到明年。", "error_description": "副词“再”要放在动词“续”的前面，应说“再续到明年”，不能放在“续”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
