INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92457, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "站队是一个一个排成一行站好。", "primary_collocate": null, "pronunciation": "zhàn duì", "ipa": "ʈʂan˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "上课前，同学们在操场上站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请大家快点儿站队。”", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们站队去食堂吃饭。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育课开始了，我们先站队，再跑步。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是不好好站队，老师很生气。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，学生们在楼里站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家站队的时候，不要说话。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们按高矮站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军训的时候，我们每天早上都站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铃响了，孩子们赶快到门口站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "站了队", "label": "完成体"}, {"form": "站过队", "label": "经历体"}, {"form": "站好队", "label": "结果补语式"}, {"form": "站隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按顺序排成一行站好（本义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b076924c-de4b-472c-a356-ba993cc371b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92457, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站队", "is_correct": true, "explanation": "站队：按顺序排成一行，与“操场上”和“上课前”的场景相符。"}, {"text": "下课", "is_correct": false, "explanation": "语义：“上课前”还没有上课，说“下课”与时间矛盾。"}, {"text": "退休", "is_correct": false, "explanation": "语义：句子的主语是“同学们”，学生不能“退休”。"}, {"text": "结账", "is_correct": false, "explanation": "搭配：“结账”指付款，与“操场上”“上课前”没有搭配关系。"}], "explanations": {"站队": "站队：按顺序排成一行，与“操场上”和“上课前”的场景相符。", "下课": "语义：“上课前”还没有上课，说“下课”与时间矛盾。", "退休": "语义：句子的主语是“同学们”，学生不能“退休”。", "结账": "搭配：“结账”指付款，与“操场上”“上课前”没有搭配关系。"}, "sentence_index": 0, "correct_answer": "站队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班决定站队参加明天的比赛。", "explanation": "这里应该用〈组队〉。站队指按顺序站成一排，或在立场上选边，不指组成队伍去参加活动。"}, {"text": "这次比赛，我们班站队拿到了年级第一名。", "explanation": "这里应该用〈取得〉。站队指按顺序站成一排，或在立场上选边，不能表示通过比赛拿到名次。"}, {"text": "他在家里站队刷牙，刷了很久。", "explanation": "这里不能用“站队”表示刷牙。站队指按顺序排成一行或在立场上选边，与刷牙无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "站队", "is_correct": true, "explanation": "站队：按顺序站成一排，与“大家……的时候”和“不要说话”都相符。"}, {"text": "大喊", "is_correct": false, "explanation": "语义：“大喊”与“不要说话”的要求矛盾。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”是天气现象，“大家”不能下雨，句子说不通。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”是植物长出芽，“大家”不能发芽。"}], "explanations": {"站队": "站队：按顺序站成一排，与“大家……的时候”和“不要说话”都相符。", "大喊": "语义：“大喊”与“不要说话”的要求矛盾。", "下雨": "搭配：“下雨”是天气现象，“大家”不能下雨，句子说不通。", "发芽": "语义：“发芽”是植物长出芽，“大家”不能发芽。"}, "sentence_index": 6, "correct_answer": "站队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上在教室里站队，给大家煮早饭。", "explanation": "这里“站队”不能表示做饭。站队指排成一行，或在立场上选边，不指干活或烹饪。"}, {"text": "他一个人在厨房里站队炒菜。", "explanation": "这里“站队”不能表示做饭。站队指多人按顺序排成一行，一个人炒菜不能说站队。"}, {"text": "我们在图书馆门口站队写作业。", "explanation": "这里“站队”不能表示一起写作业。站队指排成一行或在立场上选边，不指和别人一起行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "体育课上，老师让我们先站队好。", "corrected_sentence": "体育课上，老师让我们先站好队。", "error_description": "错误：“站队好”。正确：“站好队”，补语“好”要放在“站”和“队”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们了站队，就一起出发。", "corrected_sentence": "他们站了队，就一起出发。", "error_description": "错误：“了”放在“站”前。正确：“站了队”，“了”要放在“站”和“队”之间，不说“了站队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
