INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92458, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻选择支持哪一方。", "primary_collocate": null, "pronunciation": "zhàn duì", "ipa": "ʈʂan˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "在这件事上，你打算跟谁站队？", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里有两派，他谁也不想站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架的时候，朋友们都不愿意站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板问我支持哪一边，我不想站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上马上站队，支持新办法。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和姐姐吵起来，妈妈不站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举前，很多人早就站队了。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别逼我站队，他们两个都是我朋友。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里分成两派，班长希望大家都不要站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们吵架，我从来不乱站队。", "target_word": "站队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "站了队", "label": "完成体"}, {"form": "站过队", "label": "经历体"}, {"form": "站隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比喻选择支持哪一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b076924c-de4b-472c-a356-ba993cc371b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站队", "is_correct": true, "explanation": "站队：选择支持哪一方，与“在这件事上”和“跟谁”的说法相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”与选择立场无关，句子说的是支持谁，不是做清洁。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与“这件事”的立场选择毫无关系，句子说不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与“这件事”的立场选择无关，句子说不通。"}], "explanations": {"站队": "站队：选择支持哪一方，与“在这件事上”和“跟谁”的说法相符。", "打扫": "语义：“打扫”与选择立场无关，句子说的是支持谁，不是做清洁。", "洗澡": "语义：“洗澡”与“这件事”的立场选择毫无关系，句子说不通。", "散步": "语义：“散步”与“这件事”的立场选择无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "站队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚上在门口站队，负责看门。", "explanation": "这里应该用〈站岗〉。站队指排成一行或在立场上选边，不指站在某处值守。"}, {"text": "在超市里，他站队挑水果，挑了很久。", "explanation": "这里应该用〈挑选〉。站队指排成一行或在立场上选边，不指在货架前挑选东西。"}, {"text": "他在饭店里站队点菜，点了很久。", "explanation": "这里不能用“站队”表示点菜。站队指排成一行或在立场上选边，点菜应说“点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "站队", "is_correct": true, "explanation": "站队：选择支持某一方，与“选举前”的政治语境相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与“选举”无关，“选举前早就考试了”说不通。"}, {"text": "洗碗", "is_correct": false, "explanation": "语义：“洗碗”与选举没有关联，句子在语境上说不通。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：“下棋”与“选举前”的语境不相关，不能表达在选举中的表态。"}], "explanations": {"站队": "站队：选择支持某一方，与“选举前”的政治语境相符。", "考试": "语义：“考试”与“选举”无关，“选举前早就考试了”说不通。", "洗碗": "语义：“洗碗”与选举没有关联，句子在语境上说不通。", "下棋": "语义：“下棋”与“选举前”的语境不相关，不能表达在选举中的表态。"}, "sentence_index": 6, "correct_answer": "站队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道数学题很难，我站队了很久才做出来。", "explanation": "这里应该用〈思考〉。站队指排成一行或在争论中选择支持哪一方，不能表示动脑筋解题。"}, {"text": "下课铃响了，他第一个跑出去站队睡觉。", "explanation": "这里不能用“站队”表示睡觉。站队指排成一行或在立场上选边，睡觉应说“睡”。"}, {"text": "妈妈让我们在门口站队洗澡。", "explanation": "这里不能用“站队”表示洗澡。站队指排成一行或在立场上选边，洗澡应直接说“洗澡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快就了站队，支持新方案。", "corrected_sentence": "他很快就站了队，支持新方案。", "error_description": "错误：“了”放在“站”前。正确：“站了队”，“了”要放在“站”和“队”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不想跟他很站队。", "corrected_sentence": "我不想跟他站队。", "error_description": "错误形式“很站队”，正确形式“站队”。“站队”是动词，不能受程度副词“很”修饰，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通信是两个人用写信的方式互相联系、知道消息。", "primary_collocate": null, "pronunciation": "tōng xìn", "ipa": "tʰʊŋ˥ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我和老同学一直通信。", "target_word": "通信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们两个人每个月通信一次。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，我常和奶奶通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们已经通信三年了。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和远方的朋友通信很多年了，从没见过面。", "target_word": "通信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年轻时，常和在外地的哥哥通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们只通信，不打电话。", "target_word": "通信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们先通信，后见面。", "target_word": "通信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈和姐姐每星期通信，聊家里的事。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王和笔友通信二十年，感情很深。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个人之间用书信互相联系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a18bcdf7-86f3-4acd-8a8e-ebb3966c20cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通信", "is_correct": true, "explanation": "正确。“通信”指互相写信联系，与“我和老同学一直……”的往来相符。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指人或事物开始出现，不能和老同学一直相互进行。"}, {"text": "逝世", "is_correct": false, "explanation": "语义：“逝世”指死亡，不能和老同学“一直”相互进行。"}, {"text": "降落", "is_correct": false, "explanation": "搭配：“降落”多用于飞机、降落伞，人与人之间不能用它表示往来。"}], "explanations": {"通信": "正确。“通信”指互相写信联系，与“我和老同学一直……”的往来相符。", "诞生": "语义：“诞生”指人或事物开始出现，不能和老同学一直相互进行。", "逝世": "语义：“逝世”指死亡，不能和老同学“一直”相互进行。", "降落": "搭配：“降落”多用于飞机、降落伞，人与人之间不能用它表示往来。"}, "sentence_index": 0, "correct_answer": "通信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天通信了老王，问了一件事。", "explanation": "这里应该用〈联系〉。通信要用“和某人通信”，不能直接带人作宾语；找人询问要用〈联系〉。"}, {"text": "我昨天通信了他明天开会的事。", "explanation": "这里应该用〈通知〉。通信是双方互相传递消息，不能带“开会的事”作宾语；告诉别人某事要用〈通知〉。"}, {"text": "周末我去医院通信奶奶。", "explanation": "这里应该用〈看望〉。通信只表示互相传递消息，不能表示到场探望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通信", "is_correct": true, "explanation": "正确。“通信”指互相传递消息，与“他们只……，不打电话”的语境相符。"}, {"text": "通话", "is_correct": false, "explanation": "语义：“通话”就是打电话，与后半句“不打电话”直接矛盾。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人下落不明，与“他们只……”所说的两人之间的交往不相符。"}, {"text": "流血", "is_correct": false, "explanation": "搭配：“流血”不能用于两人之间的交流，句意不通。"}], "explanations": {"通信": "正确。“通信”指互相传递消息，与“他们只……，不打电话”的语境相符。", "通话": "语义：“通话”就是打电话，与后半句“不打电话”直接矛盾。", "失踪": "语义：“失踪”指人下落不明，与“他们只……”所说的两人之间的交往不相符。", "流血": "搭配：“流血”不能用于两人之间的交流，句意不通。"}, "sentence_index": 6, "correct_answer": "通信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在工作中通信了很多经验。", "explanation": "这里应该用〈积累〉。通信指传递消息，不能用来表示长期积累经验。"}, {"text": "他很会通信道理，大家都愿意听。", "explanation": "这里应该用〈讲〉。通信指双方传递消息，不能用来表示讲述道理。"}, {"text": "他每天通信打游戏到凌晨，连饭都忘了吃。", "explanation": "这里应该用〈玩〉。通信指双方传递消息，不能表示玩游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和笔友一直通信得。", "corrected_sentence": "我和笔友一直通信。", "error_description": "动词“通信”后多加了助词“得”。“得”需要补语，句子不完整。删去“得”，应为“我和笔友一直通信。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩每周通信两个。", "corrected_sentence": "我们俩每周通信两次。", "error_description": "“两个”的量词用错，表示次数应用“次”。应为“每周通信两次”，动作次数的量词不能换成“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
