INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92460, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92460, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用书信、电话、电报等方式传递消息。", "primary_collocate": null, "pronunciation": "tōng xìn", "ipa": "tʰʊŋ˥ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "山里没有网，只能用电话通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争时期，人们常用电报通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前人们靠书信通信，现在用手机。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子太远，很难和外界通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船在海上，用无线电和岸上通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候没有电话，人们怎么通信呢？", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪封山，村民好几天没法和外面通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在山顶用对讲机通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人不会上网，只用电话和家人通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机没电了，我们就没法通信了。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通信员", "label": "复合"}, {"form": "通信卫星", "label": "复合"}], "register": "中性", "sense_fingerprint": "用书信、电话、电报等方式传递消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a18bcdf7-86f3-4acd-8a8e-ebb3966c20cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通信", "is_correct": true, "explanation": "正确。“通信”指用电话等方式传递消息，与“只能用电话……”相符。"}, {"text": "上网", "is_correct": false, "explanation": "语义：“上网”需要网络，与前半句“山里没有网”直接矛盾。"}, {"text": "充电", "is_correct": false, "explanation": "搭配：“充电”一般说给手机或电池充电，不能说“用电话充电”这样的手段。"}, {"text": "开车", "is_correct": false, "explanation": "语义：句中用电话“开车”不合逻辑，与传递消息的语境无关。"}], "explanations": {"通信": "正确。“通信”指用电话等方式传递消息，与“只能用电话……”相符。", "上网": "语义：“上网”需要网络，与前半句“山里没有网”直接矛盾。", "充电": "搭配：“充电”一般说给手机或电池充电，不能说“用电话充电”这样的手段。", "开车": "语义：句中用电话“开车”不合逻辑，与传递消息的语境无关。"}, "sentence_index": 0, "correct_answer": "通信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师一下午都在通信擦黑板，累坏了。", "explanation": "这里应该用〈擦〉。通信指传递消息，不能表示擦黑板。"}, {"text": "他把杯子通信给了我。", "explanation": "这里应该用〈递〉。通信指双方传递消息，不能表示把实物交到别人手里，此处要用〈递〉。"}, {"text": "周末我去医院通信奶奶。", "explanation": "这里应该用〈照顾〉。通信只表示互相传递消息，不能表示照料别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通信", "is_correct": true, "explanation": "正确。“通信”指用书信、电话等传递消息，“和外面通信”与大雪封山、联系不上的语境相符。"}, {"text": "长高", "is_correct": false, "explanation": "语义：“长高”是身体变化，不能说“和外面长高”，句意不通。"}, {"text": "变色", "is_correct": false, "explanation": "语义：“变色”指颜色改变，不能“和外面变色”，与封山语境无关。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：“下雪”是天气现象，不能由人“和外面下雪”，句意荒谬。"}], "explanations": {"通信": "正确。“通信”指用书信、电话等传递消息，“和外面通信”与大雪封山、联系不上的语境相符。", "长高": "语义：“长高”是身体变化，不能说“和外面长高”，句意不通。", "变色": "语义：“变色”指颜色改变，不能“和外面变色”，与封山语境无关。", "下雪": "语义：“下雪”是天气现象，不能由人“和外面下雪”，句意荒谬。"}, "sentence_index": 6, "correct_answer": "通信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次培训，他通信了很多经验。", "explanation": "这里应该用〈积累〉。通信指传递消息，不能用来表示积累经验。"}, {"text": "他很会通信道理，大家都爱听。", "explanation": "这里应该用〈讲〉。通信指双方传递消息，不能用来表示讲述道理。"}, {"text": "他每天通信游戏到凌晨，连饭都忘了吃。", "explanation": "这里应该用〈玩〉。通信指用电报等方式传递消息，不能表示玩游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们每天被电话通信。", "corrected_sentence": "他们每天用电话通信。", "error_description": "错误形式：“被电话通信”。正确形式：“用电话通信”。表示手段要用“用”引出，“被”表示被动，不能用于“通信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每天通信着两次。", "corrected_sentence": "他们每天通信两次。", "error_description": "错误形式：“通信着两次”。正确形式：“通信两次”。“着”表示动作持续，不能和表示次数的“两次”连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eed21684-75f1-46ee-966f-b6b37ad4dbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
