INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92461, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "愿意去做。", "primary_collocate": null, "pronunciation": "kěn", "ipa": "kʰən˨˩˦", "syllable_count": 1, "sentences": [{"text": "妈妈哄了半天，孩子还是不肯吃药。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很忙，但还是肯帮我。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟只肯吃甜的东西。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你肯不肯和我一起去？", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她肯花时间学习，进步很快。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁肯借钱给他？", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们三番五次地请求，老板还是不肯给我们加工资。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不肯离开门口。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友肯听我说话，我很高兴。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不肯告诉我真正的原因。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不肯", "label": "否定形式"}, {"form": "肯不肯", "label": "正反疑问形式"}], "register": "中性", "sense_fingerprint": "后接动词，表示愿意做某事，常用否定式“不肯”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92461, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "肯", "is_correct": true, "explanation": "正确。肯表示愿意去做某事。"}, {"text": "很", "is_correct": false, "explanation": "h 与 k 声母不同，hěn 与 kěn 只差声母，意思是程度副词“很”。"}, {"text": "看", "is_correct": false, "explanation": "kàn（第四声）与 kěn（第三声）声调不同，意思是观看。"}, {"text": "砍", "is_correct": false, "explanation": "kǎn 与 kěn 韵母不同（a 与 e），意思是用刀斧等物体切断。"}, {"text": "恨", "is_correct": false, "explanation": "hèn 与 kěn 声母和声调都不同，意思是怨恨、讨厌。"}], "explanations": {"肯": "正确。肯表示愿意去做某事。", "很": "h 与 k 声母不同，hěn 与 kěn 只差声母，意思是程度副词“很”。", "看": "kàn（第四声）与 kěn（第三声）声调不同，意思是观看。", "砍": "kǎn 与 kěn 韵母不同（a 与 e），意思是用刀斧等物体切断。", "恨": "hèn 与 kěn 声母和声调都不同，意思是怨恨、讨厌。"}, "sentence_index": null, "correct_answer": "肯"}, "level_3": {"options": [{"text": "肯", "is_correct": true, "explanation": "正确。“不肯”表示孩子不愿意吃药，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能修饰“吃药”这样的动作，“不很吃药”不成立。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”后面要接施事者，“不被吃药”说不通。"}, {"text": "比", "is_correct": false, "explanation": "语法：“比”用于比较，后面要接比较对象，“不比吃药”在此不成句。"}], "explanations": {"肯": "正确。“不肯”表示孩子不愿意吃药，符合句意。", "很": "语法：“很”是程度副词，不能修饰“吃药”这样的动作，“不很吃药”不成立。", "被": "语法：“被”后面要接施事者，“不被吃药”说不通。", "比": "语法：“比”用于比较，后面要接比较对象，“不比吃药”在此不成句。"}, "sentence_index": 0, "correct_answer": "肯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他肯生病，所以今天没来上课。", "explanation": "这里应该用〈会〉。肯表示愿意去做某事，生病是身体状况，不能说“肯”，应说“会”。"}, {"text": "孩子肯害怕黑夜，所以不敢一个人睡。", "explanation": "这里应该用〈容易〉。肯表示愿意去做某事，害怕是感受，不能说“肯”，应说“容易”。"}, {"text": "他肯听懂这门外语，老师都很惊讶。", "explanation": "这里应该用〈能〉。肯表示愿意去做，听懂外语是能力，要说“能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92461, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "肯", "is_correct": true, "explanation": "正确。肯表示愿意去做某事。"}, {"text": "狠", "is_correct": false, "explanation": "h 与 k 声母不同，hěn 与 kěn 只差声母，意思是凶狠。"}, {"text": "坎", "is_correct": false, "explanation": "kǎn 与 kěn 韵母不同（a 与 e），意思是坑、土坡。"}, {"text": "砍", "is_correct": false, "explanation": "kǎn 与 kěn 韵母不同（a 与 e），意思是用刀斧切断。"}], "explanations": {"肯": "正确。肯表示愿意去做某事。", "狠": "h 与 k 声母不同，hěn 与 kěn 只差声母，意思是凶狠。", "坎": "kǎn 与 kěn 韵母不同（a 与 e），意思是坑、土坡。", "砍": "kǎn 与 kěn 韵母不同（a 与 e），意思是用刀斧切断。"}, "sentence_index": null, "correct_answer": "肯"}, "level_3": {"options": [{"text": "肯", "is_correct": true, "explanation": "正确。“老板不肯给我们加工资”表示老板拒绝，“不肯”符合句意。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能修饰“给我们加工资”这样的动作，“不非常给我们加工资”不成句。"}, {"text": "从", "is_correct": false, "explanation": "语法：“从”是介词，后面要接处所或起点，“不从给我们加工资”说不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”是身体动作，不能放在“还是不___给我们加工资”的位置，句子说不通。"}], "explanations": {"肯": "正确。“老板不肯给我们加工资”表示老板拒绝，“不肯”符合句意。", "非常": "语法：“非常”是程度副词，不能修饰“给我们加工资”这样的动作，“不非常给我们加工资”不成句。", "从": "语法：“从”是介词，后面要接处所或起点，“不从给我们加工资”说不通。", "咳嗽": "搭配：“咳嗽”是身体动作，不能放在“还是不___给我们加工资”的位置，句子说不通。"}, "sentence_index": 6, "correct_answer": "肯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他肯被大家夸奖。", "explanation": "这里应该用〈希望〉。肯表示愿意去做，希望被夸奖要说“希望”。"}, {"text": "这里肯停车。", "explanation": "这里应该用〈可以〉。肯表示愿意去做，允许停车要说“可以”。"}, {"text": "这个孩子肯考第一名，我很放心。", "explanation": "这里应该用〈想〉。肯表示愿意去做，想取得好成绩要说“想”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宝宝不肯过喝牛奶，妈妈很着急。", "corrected_sentence": "宝宝不肯喝牛奶，妈妈很着急。", "error_description": "错误在“肯”后面加了“过”。“过”不能直接放在能愿动词“肯”之后，应说“宝宝不肯喝牛奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不说肯出真相，大家都很失望。", "corrected_sentence": "他不肯说出真相，大家都很失望。", "error_description": "词序错误：“肯”应放在“说出”前面，说成“说肯出”不通。应说“不肯说出真相”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
