INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92462, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92462, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "愿意；同意。", "primary_collocate": null, "pronunciation": "kěn", "ipa": "kʰən˨˩˦", "syllable_count": 1, "sentences": [{"text": "我再三请求，他终于肯了。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不肯，我只好留在家里。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一直不肯，后来才答应。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师肯了，我们就能去玩。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说什么也不肯，我没办法。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她肯不肯，你去问问。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱太低，卖家不肯。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你肯的话，我们现在走。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事，经理已经肯了。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我提了三次，他都不肯。", "target_word": "肯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不肯", "label": "否定形式"}, {"form": "肯了", "label": "体标"}], "register": "中性", "sense_fingerprint": "单独作谓语，表示对请求或提议表示同意，如“他不肯”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac20f1ec-8dc4-4601-9b9f-1107d67c8ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92462, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "肯", "is_correct": true, "explanation": "正确。肯表示同意、答应。"}, {"text": "很", "is_correct": false, "explanation": "h 与 k 声母不同，hěn 与 kěn 只差声母，意思是程度副词“很”。"}, {"text": "看", "is_correct": false, "explanation": "kàn（第四声）与 kěn（第三声）声调不同，意思是观看。"}, {"text": "砍", "is_correct": false, "explanation": "kǎn 与 kěn 韵母不同（a 与 e），意思是用刀斧等物体切断。"}, {"text": "恨", "is_correct": false, "explanation": "hèn 与 kěn 声母和声调都不同，意思是怨恨、讨厌。"}], "explanations": {"肯": "正确。肯表示同意、答应。", "很": "h 与 k 声母不同，hěn 与 kěn 只差声母，意思是程度副词“很”。", "看": "kàn（第四声）与 kěn（第三声）声调不同，意思是观看。", "砍": "kǎn 与 kěn 韵母不同（a 与 e），意思是用刀斧等物体切断。", "恨": "hèn 与 kěn 声母和声调都不同，意思是怨恨、讨厌。"}, "sentence_index": null, "correct_answer": "肯"}, "level_3": {"options": [{"text": "肯", "is_correct": true, "explanation": "正确。“再三请求”之后“终于肯了”，表示终于同意，符合语境。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能单独作谓语带“了”，“他终于很了”不成句。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，后面必须接宾语和动词，“他终于把了”不成句。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的动作，与“再三请求”后的结果无关，句子说不通。"}], "explanations": {"肯": "正确。“再三请求”之后“终于肯了”，表示终于同意，符合语境。", "很": "语法：“很”是程度副词，不能单独作谓语带“了”，“他终于很了”不成句。", "把": "语法：“把”是介词，后面必须接宾语和动词，“他终于把了”不成句。", "咳嗽": "语义：“咳嗽”是身体的动作，与“再三请求”后的结果无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "肯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个苹果肯甜，我们都爱吃。", "explanation": "这里应该用〈很〉。肯表示同意或愿意，形容味道不能用“肯”，应说“很甜”。"}, {"text": "他肯生病，所以没去参加会议。", "explanation": "这里应该用〈会〉。肯表示同意或愿意，生病是身体状况，不能说“肯”，应说“会”。"}, {"text": "他肯生气，所以不理我了。", "explanation": "这里应该用〈容易〉。肯表示同意或愿意，生气是情绪，不能说“肯”，应说“容易”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92462, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "肯", "is_correct": true, "explanation": "正确。肯表示同意、答应。"}, {"text": "狠", "is_correct": false, "explanation": "h 与 k 声母不同，hěn 与 kěn 只差声母，意思是凶狠。"}, {"text": "坎", "is_correct": false, "explanation": "kǎn 与 kěn 韵母不同（a 与 e），意思是坑、土坡。"}, {"text": "困", "is_correct": false, "explanation": "kùn 与 kěn 韵母和声调都不同，意思是困倦或被围住。"}], "explanations": {"肯": "正确。肯表示同意、答应。", "狠": "h 与 k 声母不同，hěn 与 kěn 只差声母，意思是凶狠。", "坎": "kǎn 与 kěn 韵母不同（a 与 e），意思是坑、土坡。", "困": "kùn 与 kěn 韵母和声调都不同，意思是困倦或被围住。"}, "sentence_index": null, "correct_answer": "肯"}, "level_3": {"options": [{"text": "肯", "is_correct": true, "explanation": "正确。“价钱太低”之后，卖家“不肯”卖，表示拒绝，符合句意。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的动作，与价钱无关，句子说不通。"}, {"text": "劝", "is_correct": false, "explanation": "配价：“劝”后面要带宾语，“卖家不劝”不完整。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与“价钱太低”没有联系，句子说不通。"}], "explanations": {"肯": "正确。“价钱太低”之后，卖家“不肯”卖，表示拒绝，符合句意。", "咳嗽": "语义：“咳嗽”是身体的动作，与价钱无关，句子说不通。", "劝": "配价：“劝”后面要带宾语，“卖家不劝”不完整。", "散步": "语义：“散步”与“价钱太低”没有联系，句子说不通。"}, "sentence_index": 6, "correct_answer": "肯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门肯开了，我们可以进去了。", "explanation": "这里应该用〈打开〉。肯表示愿意或同意，门被推开要说“打开”，不能用“肯”。"}, {"text": "这个计划肯成功，大家都很放心。", "explanation": "这里应该用〈会〉。肯表示愿意或同意，计划能否成功不能说“肯”，应说“会”。"}, {"text": "孩子肯害怕打雷，所以总是哭。", "explanation": "这里应该用〈容易〉。肯表示愿意或同意，害怕是感受，不能说“肯”，应说“容易”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我求了很久，爸爸终于肯过了。", "corrected_sentence": "我求了很久，爸爸终于肯了。", "error_description": "错误在“肯”后面加了“过”。表示同意的“肯”不带“过”，应说“终于肯了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我劝了半天，奶奶还是不肯着。", "corrected_sentence": "我劝了半天，奶奶还是不肯。", "error_description": "错误在“肯”后面加了“着”。表示同意的“肯”不带“着”，应说“奶奶还是不肯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1f37fe-0e5f-48f0-a760-ce7de4563ee3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
