INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92463, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "笑点是让人一听就想笑的地方。", "primary_collocate": null, "pronunciation": "xiào diǎn", "ipa": "ɕjɑʊ̯˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个故事的笑点在最后一句话。", "target_word": "笑点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没听懂他的笑点，大家都笑了，我却没笑。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很有意思，每句话都有笑点。", "target_word": "笑点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个笑话的笑点很难懂，我听完没笑。", "target_word": "笑点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲课时加了几个笑点，学生们都笑了。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我讲了一个笑话，我找了半天也没找到笑点。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的笑点很多，我们看得一直在笑。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把笑点放在最后说，所以大家笑得更大声。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小品的笑点很自然，大家都笑得很开心。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲笑话时先停一下，再说出笑点。", "target_word": "笑点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "笑點", "label": "繁体"}], "register": "口语", "sense_fingerprint": "笑点：笑话、节目里让人一听就想笑的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "字数", "is_correct": false, "explanation": "语义：字数是数量，不能说“字数在最后一句话”"}, {"text": "笑点", "is_correct": true, "explanation": "正确：笑点是引人发笑的地方，故事的笑点可以出现在最后一句话"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是交易中的数字，不能放在故事的某一句话里"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色是外观属性，不能说“颜色在最后一句话”"}], "explanations": {"字数": "语义：字数是数量，不能说“字数在最后一句话”", "笑点": "正确：笑点是引人发笑的地方，故事的笑点可以出现在最后一句话", "价格": "语义：价格是交易中的数字，不能放在故事的某一句话里", "颜色": "体貌：颜色是外观属性，不能说“颜色在最后一句话”"}, "sentence_index": 0, "correct_answer": "笑点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他讲了一部笑点，大家都笑了。", "explanation": "这里应该用〈个〉。笑点是抽象的，不用“部”，“部”用于电影、书等作品。"}, {"text": "他讲了一个很长的笑点，大家都没笑。", "explanation": "这里应该用〈笑话〉。笑点指引人发笑的地方，不是整个故事，所以不能说“讲了一个很长的笑点”。"}, {"text": "大家的笑点很响，整个教室都听得见。", "explanation": "这里应该用〈笑声〉。笑点不发出声音，“很响”和“听得见”说的是笑声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "票价", "is_correct": false, "explanation": "搭配：票价说“高”“低”，不说“很多”，所以“票价很多”不成立"}, {"text": "笑点", "is_correct": true, "explanation": "正确：笑点多，观众才会一直笑"}, {"text": "时长", "is_correct": false, "explanation": "搭配：时长说“长”“短”，不说“很多”，所以“时长很多”不成立"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是让人发笑的原因，也不能说“年龄很多”"}], "explanations": {"票价": "搭配：票价说“高”“低”，不说“很多”，所以“票价很多”不成立", "笑点": "正确：笑点多，观众才会一直笑", "时长": "搭配：时长说“长”“短”，不说“很多”，所以“时长很多”不成立", "年龄": "语义：年龄不是让人发笑的原因，也不能说“年龄很多”"}, "sentence_index": 6, "correct_answer": "笑点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在餐厅点了一份笑点。", "explanation": "这里应该用〈点心〉。“点”的对象是饭菜、点心，笑点是引人发笑的地方，不能点。"}, {"text": "他讲完，脸上挂着笑点。", "explanation": "这里应该用〈笑容〉。笑容是脸上的表情，笑点是引人发笑的地方，不能挂在脸上。"}, {"text": "他讲完，眼里带着笑点。", "explanation": "这里应该用〈笑意〉。笑意是脸上或眼里露出的笑，笑点不是表情，不能带在眼里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小品有三部笑点，观众笑了好几次。", "corrected_sentence": "这部小品有三个笑点，观众笑了好几次。", "error_description": "错误在“笑点”的量词。“部”用于电影、书等作品，笑点要用“个”。正确形式是“三个笑点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "讲到结尾时，他故意停了一下，再说出来笑点。", "corrected_sentence": "讲到结尾时，他故意停了一下，再说出笑点。", "error_description": "错误在“来”的位置。“说出”是动词带补语，“来”不能插在“出”和宾语“笑点”之间；去掉“来”，应说“再说出笑点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92464, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92464, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92464, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "引人发笑的地方。", "primary_collocate": null, "pronunciation": "xiào diǎn", "ipa": "ɕjɑʊ̯˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个视频的笑点是小狗的表情，我一看就笑了。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的笑话没有笑点，听了没人笑。", "target_word": "笑点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个笑话太长了，笑点在最后才出现。", "target_word": "笑点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段相声的笑点一个接一个，我笑得肚子疼。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这个笑话的笑点忘了，只记得开头。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了半天，我还是不知道笑点在哪儿。", "target_word": "笑点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟的笑话笑点很怪，只有他自己在笑。", "target_word": "笑点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家电视台的节目笑点不多，看着有点没意思。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了他讲的故事，我才明白笑点原来在名字上。", "target_word": "笑点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的笑点不用解释，大家一听就会笑。", "target_word": "笑点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "笑點", "label": "繁体"}], "register": "口语", "sense_fingerprint": "笑点：相声、视频、故事中引人发笑的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时长", "is_correct": false, "explanation": "语义：时长说的是视频的长度，不能说“时长是小狗的表情”"}, {"text": "笑点", "is_correct": true, "explanation": "正确：笑点是视频中引人发笑的地方，可以是小狗的表情"}, {"text": "配音", "is_correct": false, "explanation": "语义：配音是声音，不是表情，不能说“配音是小狗的表情”"}, {"text": "分辨率", "is_correct": false, "explanation": "搭配：分辨率说的是画面参数，不与“是小狗的表情”搭配"}], "explanations": {"时长": "语义：时长说的是视频的长度，不能说“时长是小狗的表情”", "笑点": "正确：笑点是视频中引人发笑的地方，可以是小狗的表情", "配音": "语义：配音是声音，不是表情，不能说“配音是小狗的表情”", "分辨率": "搭配：分辨率说的是画面参数，不与“是小狗的表情”搭配"}, "sentence_index": 0, "correct_answer": "笑点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段相声有一座笑点，我笑得肚子疼。", "explanation": "这里应该用〈个〉。“座”用于山、楼等大型建筑，笑点不用“座”。"}, {"text": "她看着我，脸上挂着笑点。", "explanation": "这里应该用〈笑脸〉。笑脸是人的表情，笑点是引人发笑的地方，不能挂在脸上。"}, {"text": "台下笑点很响，经久不息。", "explanation": "这里应该用〈掌声〉。笑点不发出声音，“很响”和“经久不息”说的是掌声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": false, "explanation": "语义：重量说的是轻重，不能说“弟弟的笑话重量很怪”"}, {"text": "笑点", "is_correct": true, "explanation": "正确：笑点很怪，所以只有他自己在笑"}, {"text": "年份", "is_correct": false, "explanation": "语义：年份是时间，不能说“年份很怪”来解释只有他自己在笑"}, {"text": "体积", "is_correct": false, "explanation": "搭配：体积说大小，不说“很怪”"}], "explanations": {"重量": "语义：重量说的是轻重，不能说“弟弟的笑话重量很怪”", "笑点": "正确：笑点很怪，所以只有他自己在笑", "年份": "语义：年份是时间，不能说“年份很怪”来解释只有他自己在笑", "体积": "搭配：体积说大小，不说“很怪”"}, "sentence_index": 6, "correct_answer": "笑点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他讲了一根笑点，大家都笑了。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，笑点不用“根”。"}, {"text": "他在地图上找到了一个笑点。", "explanation": "这里应该用〈地点〉。笑点是笑话里引人发笑的地方，不是地图上的位置，不能在地图上找到。"}, {"text": "他讲完，眼里满是笑点。", "explanation": "这里应该用〈笑意〉。笑意是眼里露出的笑，笑点不是表情，不能满在眼里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段相声有三张笑点，观众笑得很开心。", "corrected_sentence": "这段相声有三个笑点，观众笑得很开心。", "error_description": "错误在“笑点”的量词。“张”用于纸、桌子等扁平的东西，笑点要用“个”。正确形式是“三个笑点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说了出一个笑点，大家都笑了。", "corrected_sentence": "他说出了一个笑点，大家都笑了。", "error_description": "错误在“了”的位置。“说出”是动词带补语，“出”要紧跟“说”，“了”应放在“出”的后面，正确形式是“说出了一个笑点”，不能说“说了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
