INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92466, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，从；自从。", "primary_collocate": null, "pronunciation": "zì dǎ", "ipa": "tsɨ˥˩ ta˨˩˦", "syllable_count": 2, "sentences": [{"text": "自打搬到这儿，我就没睡过好觉。", "target_word": "自打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自打上个月起，他天天跑步。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打去年，这里的路就好走多了。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打他当了经理，就很少回家吃饭。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打下了雨，天气就一直很冷。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打买了手机，爷爷每天都看新闻。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打工作以后，我再没去过那家书店。", "target_word": "自打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自打孩子上学，家里安静多了。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打到了北京，她的汉语进步很快。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我自打小时候就爱吃妈妈做的面。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "介词，引出时间起点，自从某事某时以来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1928561-c547-4f0d-a7bb-b100578bce76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自打", "is_correct": true, "explanation": "正确：“自打”是介词，引出时间起点，与“搬到这儿”之后的情况相符。"}, {"text": "对", "is_correct": false, "explanation": "配价：介词“对”要接对象，不能直接接“搬到这儿”这样的事件，句子不通。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”要接表示人的对象，不能接事件，句子不成立。"}, {"text": "凭", "is_correct": false, "explanation": "语义：“凭”表示凭借、依据，句中说的不是凭借什么，语义不合。"}], "explanations": {"自打": "正确：“自打”是介词，引出时间起点，与“搬到这儿”之后的情况相符。", "对": "配价：介词“对”要接对象，不能直接接“搬到这儿”这样的事件，句子不通。", "替": "配价：“替”要接表示人的对象，不能接事件，句子不成立。", "凭": "语义：“凭”表示凭借、依据，句中说的不是凭借什么，语义不合。"}, "sentence_index": 0, "correct_answer": "自打"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自打他，我就很少回家吃饭。", "explanation": "这里应该用〈因为〉。“自打”后要接时间或事件，不能只接一个人；这里要表达原因，应说“因为他”。"}, {"text": "自打明天起，我就每天早起跑步。", "explanation": "这里应该用〈从〉。“自打”引出的是已经发生的时间起点，不能接将来的“明天”，计划中的起点要说“从明天起”。"}, {"text": "自打天黑，他才回家。", "explanation": "这里应该用〈直到〉。“自打”表示从某个时间开始，表示一直到某时为止要用“直到”，这里说的是等到天黑才回家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自打", "is_correct": true, "explanation": "正确：“自打……以后”引出工作这个时间起点，与后面的否定句相符。"}, {"text": "比", "is_correct": false, "explanation": "配价：“比”要接比较对象，“比工作以后”不能成句。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据、标准，与“工作以后”这一时间起点不符。"}, {"text": "通过", "is_correct": false, "explanation": "语义：“通过”表示经由的途径，“工作以后”不是途径，句意不通。"}], "explanations": {"自打": "正确：“自打……以后”引出工作这个时间起点，与后面的否定句相符。", "比": "配价：“比”要接比较对象，“比工作以后”不能成句。", "按照": "语义：“按照”表示依据、标准，与“工作以后”这一时间起点不符。", "通过": "语义：“通过”表示经由的途径，“工作以后”不是途径，句意不通。"}, "sentence_index": 6, "correct_answer": "自打"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我自打明年就要去北京工作。", "explanation": "这里应该用〈从〉。“自打”只引出已经过去的时间起点，“明年”是将来，应说“从明年”。"}, {"text": "我自打很聪明，就爱吃妈妈做的面。", "explanation": "这里应该用〈从小〉。“自打”后要接时间起点，“很聪明”是状态，不能作起点；说“从小”才表示自幼起。"}, {"text": "我自打现在就爱吃妈妈做的面。", "explanation": "这里的“自打”指从过去某时起，“现在”不能作为过去的起点，应换成过去的某个时间点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自打从去年冬天起，我就没再喝过酒。", "corrected_sentence": "自打去年冬天起，我就没再喝过酒。", "error_description": "多余的介词：“自打”已经引出时间起点，后面不能再加“从”，应删去“从”，说“自打去年冬天起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自打在他退休以后，就天天钓鱼。", "corrected_sentence": "自打他退休以后，就天天钓鱼。", "error_description": "多余的介词：“自打”后直接加“在”不通，应说“自打他退休以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa91cff2-257c-479e-a898-cac1ca292afa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
