INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92467, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "第三方是除了你和我以外的另一个人或单位。", "primary_collocate": null, "pronunciation": "dì sān fāng", "ipa": "ti˥˩ san˥ faŋ˥", "syllable_count": 3, "sentences": [{"text": "除了你和我，还有第三方知道这件事。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里只有我们两人，没有第三方。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信不能让第三方看到。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事最好请第三方来作证。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的谈话不想让第三方听到。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资料不能交给第三方。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他谈话时，没有第三方在场。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个秘密不要告诉第三方。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次见面没有第三方参加。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛有第三方来看着，很公平。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "第三方公司", "label": "复合"}], "register": "中性", "sense_fingerprint": "除了你和我以外的另一个人或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92467, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "第三方", "is_correct": true, "explanation": "正确。第三方指除了你和我以外的另一个人或单位，正好可以知道这件事。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是家电，不能知道事情。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“知道”要求有意识的主体，椅子不能充当主语。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，没有认知能力，不能知道这件事。"}], "explanations": {"第三方": "正确。第三方指除了你和我以外的另一个人或单位，正好可以知道这件事。", "空调": "语义：空调是家电，不能知道事情。", "椅子": "配价：“知道”要求有意识的主体，椅子不能充当主语。", "冰箱": "语义：冰箱是家电，没有认知能力，不能知道这件事。"}, "sentence_index": 0, "correct_answer": "第三方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次买卖的第三方就是买家自己。", "explanation": "这里应该用〈当事人〉。〈第三方〉指你我双方以外的人或单位，买家本身是当事人，不能说是第三方。"}, {"text": "门口站着一辆第三方。", "explanation": "这里应该用〈个〉。“辆”用于车，第三方指人或单位，不能用“辆”来数。"}, {"text": "我们在第三方吃了午饭。", "explanation": "这里应该用〈饭馆〉。〈第三方〉指人或单位，不能用作吃饭的场所；表示地点要说〈饭馆〉之类的场所词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "第三方", "is_correct": true, "explanation": "正确。第三方指除了你和我以外的人，可以不在场，也可以在场。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡不是人，不能在场参与谈话。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“在场”一般用于人或单位，不能说“早饭在场”。"}, {"text": "眼镜", "is_correct": false, "explanation": "配价：“在场”的主体要能参与谈话，眼镜不能充当。"}], "explanations": {"第三方": "正确。第三方指除了你和我以外的人，可以不在场，也可以在场。", "灯泡": "语义：灯泡不是人，不能在场参与谈话。", "早饭": "搭配：“在场”一般用于人或单位，不能说“早饭在场”。", "眼镜": "配价：“在场”的主体要能参与谈话，眼镜不能充当。"}, "sentence_index": 6, "correct_answer": "第三方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里摆着一台第三方。", "explanation": "这里应该用〈个〉。“台”用于机器、电器，不能用来数第三方。"}, {"text": "这个第三方很好吃。", "explanation": "这里应该用〈菜〉。〈第三方〉指人或单位，不能用来形容食物；形容食物好吃要说“这道菜很好吃”，“菜”是食物。"}, {"text": "我收到了一封第三方。", "explanation": "这里应该用〈个〉。“封”用于信件，不能用来数第三方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋里还有一扇第三方，他没说话。", "corrected_sentence": "屋里还有一个第三方，他没说话。", "error_description": "错误：“一扇第三方”；正确：“一个第三方”。“扇”用于门窗，第三方指人或单位，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们不要让一块第三方知道这个秘密。", "corrected_sentence": "我们不要让一个第三方知道这个秘密。", "error_description": "错误：“一块第三方”；正确：“一个第三方”。第三方指人或单位，“块”用于块状物，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
