INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当事双方之外的另一方。", "primary_collocate": null, "pronunciation": "dì sān fāng", "ipa": "ti˥˩ san˥ faŋ˥", "syllable_count": 3, "sentences": [{"text": "这件事需要第三方来判断。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买家和卖家请第三方检查了汽车。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司闹了纠纷后，请第三方出面调解。", "target_word": "第三方", "complexity_tier": "T3", "furigana": "liǎng jiā gōng sī nào le jiū fēn hòu, qǐng dì sān fāng chū miàn tiáo jiě.", "sentence_source": "generated"}, {"text": "这次检查由第三方负责。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第三方的意见比较公平。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同上写着第三方的名字。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题，双方都想让第三方来解决。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不帮我们任何一方，是中立的第三方。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第三方没有参加这次谈话。", "target_word": "第三方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时，钱要先交给第三方保管。", "target_word": "第三方", "complexity_tier": "T3", "furigana": "mǎi dōng xi shí, qián yào xiān jiāo gěi dì sān fāng bǎo guǎn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "第三方公司", "label": "复合"}], "register": "中性", "sense_fingerprint": "当事双方之外的另一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "第三方", "is_correct": true, "explanation": "正确。第三方指当事双方之外的另一方，可以中立地来判断这件事。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人或机构，无法对事情作出判断。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“判断”要求有意识的主体，石头不能充当“来判断”的主语。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不能对纠纷或事情作判断。"}], "explanations": {"第三方": "正确。第三方指当事双方之外的另一方，可以中立地来判断这件事。", "天气": "语义：天气不是人或机构，无法对事情作出判断。", "石头": "配价：“判断”要求有意识的主体，石头不能充当“来判断”的主语。", "饭菜": "语义：饭菜是食物，不能对纠纷或事情作判断。"}, "sentence_index": 0, "correct_answer": "第三方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次纠纷的第三方就是买家和卖家自己。", "explanation": "这里应该用〈当事人〉。〈第三方〉指当事双方之外的另一方，买家和卖家本身是当事人，不能说自己是第三方。"}, {"text": "我们找了一只第三方来检查。", "explanation": "这里应该用〈家〉。第三方指人或机构，量词用“家”或“个”，“只”用于动物或成对的东西。"}, {"text": "路上遇到一个第三方，他向我问路。", "explanation": "这里应该用〈陌生人〉。〈第三方〉专指纠纷、交易等当事双方之外的一方，不用来指路上偶然遇到的人，那种人应说〈陌生人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "第三方", "is_correct": true, "explanation": "正确。第三方指当事双方之外的另一方，可以作为调解或解决问题的一方。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷是偷东西的人，不能担任解决纠纷的一方。"}, {"text": "花园", "is_correct": false, "explanation": "配价：“解决问题”的主体要能作决定，花园不能充当。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾是废弃物，不能作为解决问题的一方。"}], "explanations": {"第三方": "正确。第三方指当事双方之外的另一方，可以作为调解或解决问题的一方。", "小偷": "语义：小偷是偷东西的人，不能担任解决纠纷的一方。", "花园": "配价：“解决问题”的主体要能作决定，花园不能充当。", "垃圾": "语义：垃圾是废弃物，不能作为解决问题的一方。"}, "sentence_index": 6, "correct_answer": "第三方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的妻子发现他有了第三方。", "explanation": "这里应该用〈第三者〉。〈第三方〉指当事双方之外的另一方，不指介入他人感情关系的人；插足者要说〈第三者〉。"}, {"text": "这份合同的第三方是甲方和乙方，双方都要签字。", "explanation": "这里应该用〈当事人〉。甲方和乙方本身是合同的当事人，〈第三方〉指当事双方之外的另一方，不能说甲乙双方是第三方。"}, {"text": "景点里来了一位第三方，他拍了很多照片。", "explanation": "这里应该用〈游客〉。〈第三方〉专指纠纷、交易等当事双方之外的一方，不用来指景点里偶遇的游客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个人吵起来后，他们请了一块第三方出面劝架。", "corrected_sentence": "两个人吵起来后，他们请了一个第三方出面劝架。", "error_description": "错误：“一块第三方”；正确：“一个第三方”。第三方指人或单位，“块”用于块状物，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次查账我们请了一条第三方。", "corrected_sentence": "这次查账我们请了一家第三方。", "error_description": "错误：“一条第三方”；正确：“一家第三方”。第三方指机构时用量词“家”，“条”用于细长的东西，不能用来数“第三方”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
