INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92469, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海上刮来的很大很大的风。", "primary_collocate": null, "pronunciation": "tái fēng", "ipa": "tʰai˧˥ fəŋ˥", "syllable_count": 2, "sentences": [{"text": "今天有台风，你别出海了。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，海边的风很大。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的台风把树吹倒了。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风过后，天气马上变好了。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说下周会有一个台风。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民看到台风要来，都回家了。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风刮了一整夜，我没睡好。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场台风让学校放假了。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上的台风越来越近了。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来的时候，我们不出门，在家看书。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "台风天", "label": "复合词"}, {"form": "颱風", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从海上刮来的大风，日常说法，指带来大风大雨的天气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "台风", "is_correct": true, "explanation": "正确：“今天有”后接恶劣天气，且与“你别出海了”构成因果。"}, {"text": "拼音", "is_correct": false, "explanation": "语义：拼音不是天气，“今天有拼音”与“你别出海了”之间没有因果。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是天气，“今天有钢琴”与“你别出海了”之间没有因果。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不是天气，“今天有咖啡”与“你别出海了”之间没有因果。"}], "explanations": {"台风": "正确：“今天有”后接恶劣天气，且与“你别出海了”构成因果。", "拼音": "语义：拼音不是天气，“今天有拼音”与“你别出海了”之间没有因果。", "钢琴": "语义：钢琴不是天气，“今天有钢琴”与“你别出海了”之间没有因果。", "咖啡": "语义：咖啡不是天气，“今天有咖啡”与“你别出海了”之间没有因果。"}, "sentence_index": 0, "correct_answer": "台风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海上刮来一只台风，渔船都回港了。", "explanation": "这里应该用〈场〉。台风是一次气象过程，量词用“场”；“只”多用于动物或单个物件，不能拿来数台风。"}, {"text": "夏天常在傍晚下台风，路面全湿了。", "explanation": "这里应该用〈暴雨〉。台风是强风，不说“下”，下的是雨。"}, {"text": "沙漠里刮起了台风，能见度很低。", "explanation": "这里应该用〈沙尘暴〉。台风是海上刮来的风，沙漠中的大风应说沙尘暴，台风不用来指沙漠里的风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台风", "is_correct": true, "explanation": "正确：台风能“刮”，符合“刮了一整夜，我没睡好”的语境。"}, {"text": "大雨", "is_correct": false, "explanation": "搭配：“刮”用于风，雨要说“下”，不能说“大雨刮了一整夜”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不会“刮”，句子在语义上说不通。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子不会“刮”，“蚊子刮了一整夜”说不通。"}], "explanations": {"台风": "正确：台风能“刮”，符合“刮了一整夜，我没睡好”的语境。", "大雨": "搭配：“刮”用于风，雨要说“下”，不能说“大雨刮了一整夜”。", "歌曲": "语义：歌曲不会“刮”，句子在语义上说不通。", "蚊子": "语义：蚊子不会“刮”，“蚊子刮了一整夜”说不通。"}, "sentence_index": 6, "correct_answer": "台风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气像台风一样温柔。", "explanation": "这里应该用〈春风〉。台风风力猛烈，不能用来比喻温柔的性格。"}, {"text": "午后的台风很温暖，我们去公园吧。", "explanation": "这里应该用〈阳光〉。台风是强风，不能形容温暖的感觉。"}, {"text": "台风飘落下来，盖住了街道。", "explanation": "这里应该用〈雪花〉。台风是风，不会飘落，飘落的是雪花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨晚一只台风刮得很厉害，好多树被吹倒了。", "corrected_sentence": "昨晚一场台风刮得很厉害，好多树被吹倒了。", "error_description": "错误：“一只台风”，正确：“一场台风”。台风是一次气象过程，量词用“场”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只台风来的时候，我们都待在家里。", "corrected_sentence": "这场台风来的时候，我们都待在家里。", "error_description": "错误：“这只台风”，正确：“这场台风”。台风是一次气象过程，量词用“场”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
