INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "发生在西北太平洋上的强烈热带气旋，风力很大。", "primary_collocate": null, "pronunciation": "tái fēng", "ipa": "tʰai˧˥ fəŋ˥", "syllable_count": 2, "sentences": [{"text": "今年第三号台风在西北太平洋形成。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象台说台风明天会登陆广东。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风的中心风力有十四级。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风是一种强烈的热带气旋。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风每年夏天都会影响沿海地区。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象台发布了台风黄色预警。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风登陆后，风力慢慢减弱。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路径图显示这个台风正往北移动。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个台风的名字叫“海燕”。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在观察台风的移动方向。", "target_word": "台风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "台风季", "label": "复合词"}, {"form": "颱風", "label": "繁体"}], "register": "书面", "sense_fingerprint": "气象学术语，西北太平洋上的强热带气旋，有编号、登陆、风力等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "台风", "is_correct": true, "explanation": "正确：“第三号”是热带气旋的编号方式，“在西北太平洋形成”符合台风。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹不编号，也不会在海上“形成”并被排为第三号。"}, {"text": "雾霾", "is_correct": false, "explanation": "搭配：编号“第三号”只用于热带气旋，不能用于雾霾。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声不编号，也不会在西北太平洋“形成”，句子说不通。"}], "explanations": {"台风": "正确：“第三号”是热带气旋的编号方式，“在西北太平洋形成”符合台风。", "彩虹": "语义：彩虹不编号，也不会在海上“形成”并被排为第三号。", "雾霾": "搭配：编号“第三号”只用于热带气旋，不能用于雾霾。", "雷声": "语义：雷声不编号，也不会在西北太平洋“形成”，句子说不通。"}, "sentence_index": 0, "correct_answer": "台风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天常在傍晚下台风。", "explanation": "这里应该用〈暴雨〉。台风不说“下”，下的是雨。"}, {"text": "台风是一种强烈的冷空气过程。", "explanation": "这里应该用〈寒潮〉。台风是热带气旋，不是冷空气过程。"}, {"text": "台风是海底地震引起的巨浪。", "explanation": "这里应该用〈海啸〉。台风是海上的热带气旋，不是海底地震引起的巨浪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台风", "is_correct": true, "explanation": "正确：“登陆”专用于台风、风暴等热带气旋，且与“风力慢慢减弱”相符。"}, {"text": "大雨", "is_correct": false, "explanation": "搭配：“登陆”一般用于台风、风暴等，不说“大雨登陆”。"}, {"text": "雪崩", "is_correct": false, "explanation": "语义：雪崩不会登陆，句子说不通。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹不会登陆，也与“风力慢慢减弱”无关。"}], "explanations": {"台风": "正确：“登陆”专用于台风、风暴等热带气旋，且与“风力慢慢减弱”相符。", "大雨": "搭配：“登陆”一般用于台风、风暴等，不说“大雨登陆”。", "雪崩": "语义：雪崩不会登陆，句子说不通。", "彩虹": "语义：彩虹不会登陆，也与“风力慢慢减弱”无关。"}, "sentence_index": 6, "correct_answer": "台风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "气象台记录到一只台风正在登陆。", "explanation": "这里应该用〈场〉。台风是一次气象过程，量词用“场”；“只”多用于动物或单个物件，不能拿来数台风。"}, {"text": "傍晚的台风轻轻吹过湖面。", "explanation": "这里应该用〈微风〉。台风风力强烈，不能形容“轻轻吹过”的风。"}, {"text": "台风映红了天空。", "explanation": "这里应该用〈晚霞〉。台风是风，不能“映红”天空，映红天空的是晚霞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只台风刮得很厉害，沿海地区受灾严重。", "corrected_sentence": "这场台风刮得很厉害，沿海地区受灾严重。", "error_description": "错误：“这只台风”，正确：“这场台风”。台风是一次气象过程，量词用“场”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台风登陆着广东，很多房屋被毁。", "corrected_sentence": "台风登陆了广东，很多房屋被毁。", "error_description": "错误：“登陆着广东”，正确：“登陆了广东”。表示动作已经完成要用“了”，“着”表示动作持续，不能用于“登陆”这种一次性完成的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
