INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92471, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "管它是说不用管这件事。", "primary_collocate": null, "pronunciation": "guǎn tā", "ipa": "kuan˨˩ tʰa˥", "syllable_count": 2, "sentences": [{"text": "管它下不下雨，我们都去。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它是谁做的，好吃就行。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它贵不贵，我喜欢就买。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它呢，明天再说吧。", "target_word": "管它", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别人怎么说，管它呢！", "target_word": "管它", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "管它几点了，先睡觉再说。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服脏了就脏了，管它呢。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它路多远，我们走着去吧。", "target_word": "管它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管它考得好不好，先好好玩一天。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它对不对，先试试看。", "target_word": "管它", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "管它呢", "label": "口语常用形式"}], "register": "口语", "sense_fingerprint": "管它：说这件事不用管，不必去操心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92471, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "管它", "is_correct": true, "explanation": "管它：说这件事不用管，不必去操心"}, {"text": "惯他", "is_correct": false, "explanation": "guàn tā（第四声）与 guǎn tā（第三声）声调不同，意思是溺爱他"}, {"text": "赶他", "is_correct": false, "explanation": "gǎn tā 与 guǎn tā 少了介音 u，意思是把他赶走"}, {"text": "关他", "is_correct": false, "explanation": "guān（第一声）与 guǎn（第三声）声调不同，意思是关押他"}], "explanations": {"管它": "管它：说这件事不用管，不必去操心", "惯他": "guàn tā（第四声）与 guǎn tā（第三声）声调不同，意思是溺爱他", "赶他": "gǎn tā 与 guǎn tā 少了介音 u，意思是把他赶走", "关他": "guān（第一声）与 guǎn（第三声）声调不同，意思是关押他"}, "sentence_index": null, "correct_answer": "管它"}, "level_3": {"options": [{"text": "管它", "is_correct": true, "explanation": "管它：表示不去理会、不在乎，引出“下不下雨”无所谓"}, {"text": "担心", "is_correct": false, "explanation": "语义：担心表示忧虑，与“我们都去”的满不在乎相悖"}, {"text": "在乎", "is_correct": false, "explanation": "语义：在乎表示看重，与“我们都去”的满不在乎相反"}, {"text": "管理", "is_correct": false, "explanation": "搭配：“管理”后接事务或人员，不能说“管理下不下雨”"}], "explanations": {"管它": "管它：表示不去理会、不在乎，引出“下不下雨”无所谓", "担心": "语义：担心表示忧虑，与“我们都去”的满不在乎相悖", "在乎": "语义：在乎表示看重，与“我们都去”的满不在乎相反", "管理": "搭配：“管理”后接事务或人员，不能说“管理下不下雨”"}, "sentence_index": 0, "correct_answer": "管它"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生的纪律由班主任来管它。", "explanation": "这里应该用〈管理〉。管它只表示不去理会，不能表示“管理”的意思"}, {"text": "我很管它这次考试的成绩。", "explanation": "这里应该用〈在乎〉。管它表示不去理会，不能受“很”修饰，也不能表示在乎。"}, {"text": "他对别人的看法管它得很厉害，整天睡不好觉。", "explanation": "这里应该用〈在意〉。管它表示不去理会，不能表示很在乎别人的看法"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管它", "is_correct": true, "explanation": "管它：表示不去理会、不在乎，与“脏了就脏了”的态度一致"}, {"text": "清洗", "is_correct": false, "explanation": "语义：清洗表示洗净，与“脏了就脏了”的无所谓态度相悖"}, {"text": "收拾", "is_correct": false, "explanation": "语义：收拾表示整理，与“脏了就脏了”的无所谓态度相悖"}, {"text": "惦记", "is_correct": false, "explanation": "语义：惦记表示挂念，与“脏了就脏了”的不在乎相反"}], "explanations": {"管它": "管它：表示不去理会、不在乎，与“脏了就脏了”的态度一致", "清洗": "语义：清洗表示洗净，与“脏了就脏了”的无所谓态度相悖", "收拾": "语义：收拾表示整理，与“脏了就脏了”的无所谓态度相悖", "惦记": "语义：惦记表示挂念，与“脏了就脏了”的不在乎相反"}, "sentence_index": 6, "correct_answer": "管它"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈管它得很严，我们都不敢出去玩。", "explanation": "这里应该用〈管束〉。管它表示不去理会，不能表示严格地约束、管教"}, {"text": "我们要管它身边的小动物。", "explanation": "这里应该用〈爱护〉。管它表示不去理会，说“管它小动物”与爱护的意思正好相反"}, {"text": "消防员管它得很认真，居民们都很放心。", "explanation": "这里应该用〈处理〉。管它表示不去理会，不能表示认真地处理事情"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "管它了结果怎么样，我们先去试试。", "corrected_sentence": "管它结果怎么样，我们先去试试。", "error_description": "“管它”是固定说法，后面不能加“了”。错误在于“管它了”，应改为“管它结果怎么样”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管它地多贵，买了再说吧。", "corrected_sentence": "管它多贵，买了再说吧。", "error_description": "“管它”后面不能加结构助词“地”。错误在于“管它地”，应删去“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
