INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92472, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "口语，表示不去理会，不在乎。", "primary_collocate": null, "pronunciation": "guǎn ta", "ipa": "kuan˨˩ tʰa˥", "syllable_count": 2, "sentences": [{"text": "管它别人怎么看，我做我自己。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它天气多冷，他都要去游泳。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它三七二十一，先吃了再说。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它呢，开心最重要。", "target_word": "管它", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "管它什么规矩，他想怎么做就怎么做。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱不够就不够，管它呢！", "target_word": "管它", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "管它输还是赢，玩得开心就好。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说什么，我才不管它呢。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它谁对谁错，我只想早点回家。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管它是真是假，我先听听再说。", "target_word": "管它", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "管它呢", "label": "口语常用形式"}], "register": "口语", "sense_fingerprint": "管它：口语，表示不理会、不在乎的态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92472, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "管它", "is_correct": true, "explanation": "管它：口语，表示不理会、不在乎的态度"}, {"text": "惯他", "is_correct": false, "explanation": "guàn tā（第四声）与 guǎn tā（第三声）声调不同，意思是溺爱他"}, {"text": "赶他", "is_correct": false, "explanation": "gǎn tā 与 guǎn tā 少了介音 u，意思是把他赶走"}, {"text": "关他", "is_correct": false, "explanation": "guān tā（第一声）与 guǎn tā（第三声）声调不同，意思是把他关起来"}], "explanations": {"管它": "管它：口语，表示不理会、不在乎的态度", "惯他": "guàn tā（第四声）与 guǎn tā（第三声）声调不同，意思是溺爱他", "赶他": "gǎn tā 与 guǎn tā 少了介音 u，意思是把他赶走", "关他": "guān tā（第一声）与 guǎn tā（第三声）声调不同，意思是把他关起来"}, "sentence_index": null, "correct_answer": "管它"}, "level_3": {"options": [{"text": "管它", "is_correct": true, "explanation": "管它：表示不理会、不在乎，引出“我做我自己”的态度"}, {"text": "讨好", "is_correct": false, "explanation": "搭配：“讨好”的对象是人，不能说“讨好别人怎么看”"}, {"text": "担忧", "is_correct": false, "explanation": "语义：担忧表示忧虑，与“我做我自己”的不在乎相悖"}, {"text": "介绍", "is_correct": false, "explanation": "搭配：“介绍”后接人或事物本身，不说“介绍别人怎么看”"}], "explanations": {"管它": "管它：表示不理会、不在乎，引出“我做我自己”的态度", "讨好": "搭配：“讨好”的对象是人，不能说“讨好别人怎么看”", "担忧": "语义：担忧表示忧虑，与“我做我自己”的不在乎相悖", "介绍": "搭配：“介绍”后接人或事物本身，不说“介绍别人怎么看”"}, "sentence_index": 0, "correct_answer": "管它"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我非常在乎这次考试，管它考得怎么样。", "explanation": "这里应该用〈担心〉。管它表示不在乎，与前面的“非常在乎”矛盾"}, {"text": "她最关心孩子的健康，管它孩子病没病。", "explanation": "这里应该用〈关心〉。管它表示不去理会，与“最关心”矛盾"}, {"text": "这件事对我特别重要，管它办没办好。", "explanation": "这里应该用〈在意〉。管它表示无所谓，与“特别重要”矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管它", "is_correct": true, "explanation": "管它：表示不在乎，引出“输还是赢”无所谓的态度"}, {"text": "介意", "is_correct": false, "explanation": "语义：介意表示在乎，与“玩得开心就好”的不在乎相反"}, {"text": "争取", "is_correct": false, "explanation": "搭配：“争取”后接目标，不说“争取输还是赢”"}, {"text": "注重", "is_correct": false, "explanation": "语义：注重表示看重，与“玩得开心就好”的态度相悖"}], "explanations": {"管它": "管它：表示不在乎，引出“输还是赢”无所谓的态度", "介意": "语义：介意表示在乎，与“玩得开心就好”的不在乎相反", "争取": "搭配：“争取”后接目标，不说“争取输还是赢”", "注重": "语义：注重表示看重，与“玩得开心就好”的态度相悖"}, "sentence_index": 6, "correct_answer": "管它"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈急得睡不着，管它儿子回没回家。", "explanation": "这里应该用〈担心〉。管它表示不在乎，与“急得睡不着”矛盾"}, {"text": "他特别在意别人的看法，管它别人怎么说。", "explanation": "这里应该用〈在意〉。管它表示不理会，与“特别在意”矛盾"}, {"text": "这份工作我很重视，管它做得好不好。", "explanation": "这里应该用〈重视〉。管它表示无所谓，与“很重视”矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很管它别人说什么，我还是我行我素。", "corrected_sentence": "管它别人说什么，我还是我行我素。", "error_description": "“很”不能修饰“管它”。错误在于“很管它”，应去掉“很”，改为“管它别人说什么”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管它了别人笑不笑，我照样做自己的事。", "corrected_sentence": "管它别人笑不笑，我照样做自己的事。", "error_description": "“管它”是固定说法，后面不能加“了”。错误在于“管它了”，应改为“管它别人笑不笑”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
