INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92473, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "用来数船的字。", "primary_collocate": null, "pronunciation": "sōu", "ipa": "sɔu˥", "syllable_count": 1, "sentences": [{"text": "湖上有一艘小帆船。", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边停着两艘轮船。", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见远处有一艘帆船。", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘客船今天晚上八点开。", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司买了五艘新货轮。", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有一艘破旧的轮船。", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子画了一艘大轮船。", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那艘科考船要去南极。", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这艘客轮去哪儿？", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把那艘旧帆船卖了。", "target_word": "艘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数船的量词，用于帆船、客船、轮船、科考船等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e57226eb-7676-4c4b-9e91-9ee86200188c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92473, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "艘", "is_correct": true, "explanation": "sōu，量词，用于数船只，是本题正确答案。"}, {"text": "收", "is_correct": false, "explanation": "shōu（收）与 sōu 声母不同（sh 与 s），意思是收取、收回，不用于船只。"}, {"text": "松", "is_correct": false, "explanation": "sōng（松）与 sōu 韵母不同（ong 与 ou），意思是松树、松开。"}, {"text": "都", "is_correct": false, "explanation": "dōu（都）与 sōu 声母不同（d 与 s），意思是全部、都。"}, {"text": "叟", "is_correct": false, "explanation": "sǒu（叟）与 sōu 声调不同（三声与一声），意思是老年男子。"}], "explanations": {"艘": "sōu，量词，用于数船只，是本题正确答案。", "收": "shōu（收）与 sōu 声母不同（sh 与 s），意思是收取、收回，不用于船只。", "松": "sōng（松）与 sōu 韵母不同（ong 与 ou），意思是松树、松开。", "都": "dōu（都）与 sōu 声母不同（d 与 s），意思是全部、都。", "叟": "sǒu（叟）与 sōu 声调不同（三声与一声），意思是老年男子。"}, "sentence_index": null, "correct_answer": "艘"}, "level_3": {"options": [{"text": "艘", "is_correct": true, "explanation": "正确。“一艘小帆船”是船只的常用说法，量词“艘”用于船只。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车辆，不说“一辆小帆船”。"}, {"text": "架", "is_correct": false, "explanation": "搭配：“架”用于飞机、机器等，不用于帆船。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于画、布等平面的东西，帆船是立体的船只，与句意不合。"}], "explanations": {"艘": "正确。“一艘小帆船”是船只的常用说法，量词“艘”用于船只。", "辆": "搭配：“辆”用于车辆，不说“一辆小帆船”。", "架": "搭配：“架”用于飞机、机器等，不用于帆船。", "幅": "语义：“幅”用于画、布等平面的东西，帆船是立体的船只，与句意不合。"}, "sentence_index": 0, "correct_answer": "艘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆客船今天晚上八点开。", "explanation": "这里应该用〈艘〉。“辆”用于车辆，客船是船只，应说“这艘客船”。"}, {"text": "这部客船今天晚上八点开。", "explanation": "这里应该用〈艘〉。“部”用于机器、作品等，客船是船只，应用“艘”。"}, {"text": "这张客船今天晚上八点开。", "explanation": "这里应该用〈艘〉。“张”用于桌子、纸等平面的东西，不用于客船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92473, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "艘", "is_correct": true, "explanation": "sōu，量词，用于数船只，是本题正确答案。"}, {"text": "抽", "is_correct": false, "explanation": "chōu（抽）与 sōu 声母不同（ch 与 s），意思是抽出、抽取。"}, {"text": "都", "is_correct": false, "explanation": "dōu（都）与 sōu 声母不同（d 与 s），意思是全部、都。"}, {"text": "偷", "is_correct": false, "explanation": "tōu（偷）与 sōu 声母不同（t 与 s），意思是偷窃。"}, {"text": "嗽", "is_correct": false, "explanation": "sòu（嗽）与 sōu 声调不同（四声与一声），意思是咳嗽。"}], "explanations": {"艘": "sōu，量词，用于数船只，是本题正确答案。", "抽": "chōu（抽）与 sōu 声母不同（ch 与 s），意思是抽出、抽取。", "都": "dōu（都）与 sōu 声母不同（d 与 s），意思是全部、都。", "偷": "tōu（偷）与 sōu 声母不同（t 与 s），意思是偷窃。", "嗽": "sòu（嗽）与 sōu 声调不同（四声与一声），意思是咳嗽。"}, "sentence_index": null, "correct_answer": "艘"}, "level_3": {"options": [{"text": "艘", "is_correct": true, "explanation": "正确。“画了一艘大轮船”是船只的常用说法，量词“艘”用于船只。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、桥等固定不动的大型物体，轮船不能用“座”。"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器、设备，轮船是船只，不说“一台轮船”。"}, {"text": "颗", "is_correct": false, "explanation": "语义：“颗”指小而圆的东西，大轮船与句意不合。"}], "explanations": {"艘": "正确。“画了一艘大轮船”是船只的常用说法，量词“艘”用于船只。", "座": "语义：“座”指山、桥等固定不动的大型物体，轮船不能用“座”。", "台": "搭配：“台”用于机器、设备，轮船是船只，不说“一台轮船”。", "颗": "语义：“颗”指小而圆的东西，大轮船与句意不合。"}, "sentence_index": 6, "correct_answer": "艘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们把那台旧帆船卖了。", "explanation": "这里应该用〈艘〉。“台”用于机器、设备，帆船是船只，不用“台”。"}, {"text": "他们把那颗旧帆船卖了。", "explanation": "这里应该用〈艘〉。“颗”用于小而圆的东西，帆船不能用“颗”。"}, {"text": "他们把那座旧帆船卖了。", "explanation": "这里应该用〈艘〉。“座”用于山、桥等固定的大型物体，帆船不用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version 