INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92475, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管理学院是教人怎么管好一个公司的学校。", "primary_collocate": null, "pronunciation": "guǎn lǐ xué yuàn", "ipa": "kwan˨˩ li˨˩ ɕɥɛ˧˥ ɥan˥˩", "syllable_count": 4, "sentences": [{"text": "她想去管理学院学习。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理学院教你怎么管好公司。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在管理学院工作。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所管理学院离地铁站很近。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业于一所有名的管理学院。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理学院的学生常去公司看看。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们城市新建了一所管理学院。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理学院里有很多外国老师。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理学院门口有一家小咖啡店。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，管理学院对你很有用。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "管理學院", "label": "繁体"}], "register": "中性", "sense_fingerprint": "教人怎么管好公司的学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92475, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管理学院", "is_correct": true, "explanation": "正确。管理学院是教人怎么管好公司的学校，可以去那里学习。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是学习的场所，句子说“去”学习。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“去……学习”要求地点是场所，饺子不能作学习的地点。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不是学习的场所。"}], "explanations": {"管理学院": "正确。管理学院是教人怎么管好公司的学校，可以去那里学习。", "冰箱": "语义：冰箱不是学习的场所，句子说“去”学习。", "饺子": "搭配：“去……学习”要求地点是场所，饺子不能作学习的地点。", "老虎": "语义：老虎是动物，不是学习的场所。"}, "sentence_index": 0, "correct_answer": "管理学院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妹妹在管理学院学医。", "explanation": "这里应该用〈医学院〉。管理学院教管理类学科，学医要去医学院。"}, {"text": "她在管理学院学钢琴。", "explanation": "这里应该用〈音乐学院〉。管理学院不教音乐，学钢琴要去音乐学院。"}, {"text": "我们学校有一条管理学院。", "explanation": "这里应该用〈所〉。学院这类机构用量词“所”，“条”用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92475, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管理学院", "is_correct": true, "explanation": "正确。管理学院是教人怎么管好公司的学校，可以新建。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "搭配：“新建”一般用于建筑或机构，不搭配食物“鸡蛋”。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不是人造的事物，不能说“新建”。"}, {"text": "春天", "is_correct": false, "explanation": "搭配：“新建”不搭配时间名词“春天”。"}], "explanations": {"管理学院": "正确。管理学院是教人怎么管好公司的学校，可以新建。", "鸡蛋": "搭配：“新建”一般用于建筑或机构，不搭配食物“鸡蛋”。", "小猫": "语义：小猫是动物，不是人造的事物，不能说“新建”。", "春天": "搭配：“新建”不搭配时间名词“春天”。"}, "sentence_index": 6, "correct_answer": "管理学院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "管理学院是一门研究如何管好公司的学科，很有用。", "explanation": "这里应该用〈管理学〉。〈管理学院〉是教授管理类学科的学校机构，不是学科名称，不能说它“是一门学科”。"}, {"text": "妈妈说，一本管理学院对你很有用。", "explanation": "这里应该用〈所〉。学院用量词“所”，“本”用于书籍。"}, {"text": "我的爷爷就是管理学院。", "explanation": "这里应该用〈管理学家〉。〈管理学院〉是学校机构，不是人，指人要说〈管理学家〉或“管理学院的老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥考上了一位管理学院。", "corrected_sentence": "我哥哥考上了一所管理学院。", "error_description": "错误：“一位管理学院”；正确：“一所管理学院”。学院属于机构，量词用“所”，“位”只用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他毕业于一辆管理学院。", "corrected_sentence": "他毕业于一所管理学院。", "error_description": "错误：“一辆管理学院”；正确：“一所管理学院”。学院属于机构，量词用“所”，“辆”用于车，不能用来数学院。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
