INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高等学校中教授管理类学科的学院。", "primary_collocate": null, "pronunciation": "guǎn lǐ xué yuàn", "ipa": "kwan˨˩ li˨˩ ɕɥɛ˧˥ ɥan˥˩", "syllable_count": 4, "sentences": [{"text": "这所大学的管理学院有三个专业。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理学院开设了市场和会计课程。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在管理学院读研究生。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理学院的院长明天要开会。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理学院的老师研究公司管理。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从管理学院毕业后进了银行。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里，管理学院的楼在图书馆旁边。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理学院每年招收两百名新生。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理学院的课程包括经济学和统计学。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想申请那所大学的管理学院。", "target_word": "管理学院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "管理學院", "label": "繁体"}], "register": "中性", "sense_fingerprint": "高等学校中教授管理类学科的学院", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2027ec5-4154-47d2-ac12-142bce975538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管理学院", "is_correct": true, "explanation": "正确。管理学院是高等学校中教授管理类学科的学院，可以设有专业。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是藏书和阅读的场所，不设专业。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“有……专业”搭配的是学院或系，不搭配“食堂”。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆是体育活动的场所，不设专业。"}], "explanations": {"管理学院": "正确。管理学院是高等学校中教授管理类学科的学院，可以设有专业。", "图书馆": "语义：图书馆是藏书和阅读的场所，不设专业。", "食堂": "搭配：“有……专业”搭配的是学院或系，不搭配“食堂”。", "体育馆": "语义：体育馆是体育活动的场所，不设专业。"}, "sentence_index": 0, "correct_answer": "管理学院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所大学的管理学院教法律。", "explanation": "这里应该用〈法学院〉。管理学院教授管理类学科，不教法律。"}, {"text": "管理学院是研究组织如何运作的学科，许多大学都设有相关课程。", "explanation": "这里应该用〈管理学〉。〈管理学院〉是教授管理类学科的学校机构，不是学科名称，不能说它“是一门学科”。"}, {"text": "这所大学有一台管理学院。", "explanation": "这里应该用〈所〉。学院用量词“所”，“台”用于机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管理学院", "is_correct": true, "explanation": "正确。管理学院是大学里的学院，它的楼可以在图书馆旁边。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是建筑物，没有“楼”。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文字作品，不能有楼。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“故事的楼”不成立，“楼”要用建筑或机构来修饰。"}], "explanations": {"管理学院": "正确。管理学院是大学里的学院，它的楼可以在图书馆旁边。", "空气": "语义：空气不是建筑物，没有“楼”。", "小说": "语义：小说是文字作品，不能有楼。", "故事": "搭配：“故事的楼”不成立，“楼”要用建筑或机构来修饰。"}, "sentence_index": 6, "correct_answer": "管理学院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想报考那所大学的管理学院，毕业后当医生。", "explanation": "这里应该用〈医学院〉。管理学院教管理类学科，想当医生要去医学院。"}, {"text": "他想申请那所大学的一扇管理学院。", "explanation": "这里应该用〈所〉。“扇”用于门窗，学院不能用“扇”来数。"}, {"text": "他是那所大学的管理学院。", "explanation": "这里应该用〈教授〉。〈管理学院〉是学校机构，不能用来指人；指人要说“管理学院的教授”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所大学新建了一条管理学院。", "corrected_sentence": "这所大学新建了一所管理学院。", "error_description": "错误：“一条管理学院”；正确：“一所管理学院”。学院属于机构，量词用“所”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的女儿在一辆管理学院任教。", "corrected_sentence": "她的女儿在一所管理学院任教。", "error_description": "错误：“一辆管理学院”；正确：“一所管理学院”。学院属于机构，量词用“所”，“辆”用于车，不能用来数学院。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeffa5a4-9bca-41ea-bd4e-584677e98aa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
