INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92477, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看一看，把意思讲明白。", "primary_collocate": null, "pronunciation": "jiě dú", "ipa": "tɕjɛ˨˩ tu˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈帮我解读这封信。", "target_word": "解读", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谁能解读墙上的这几个字？", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导游给我们解读了这幅画。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带着我们解读课文。", "target_word": "解读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边看地图，一边给我解读。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请解读一下这句话的意思。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷正在解读一本旧书。", "target_word": "解读", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生给我解读了检查单。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些符号很难解读。", "target_word": "解读", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生们解读着这首短诗。", "target_word": "解读", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解读了", "label": "体标"}, {"form": "解读着", "label": "体标"}, {"form": "解读过", "label": "体标"}, {"form": "解读者", "label": "复合"}, {"form": "解讀", "label": "繁体"}], "register": "书面", "sense_fingerprint": "看过文字、图画、符号等之后，把其中的意思讲给别人听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "煎", "is_correct": false, "explanation": "语义：“煎”的对象是食物，不能用于“这封信”。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”要求咀嚼的对象是食物，与“这封信”不符。"}, {"text": "解读", "is_correct": true, "explanation": "“妈妈帮我解读这封信”指妈妈读懂信的内容并讲给我听，与“帮我”和“这封信”相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能说“洗这封信”。"}], "explanations": {"煎": "语义：“煎”的对象是食物，不能用于“这封信”。", "嚼": "语义：“嚼”要求咀嚼的对象是食物，与“这封信”不符。", "解读": "“妈妈帮我解读这封信”指妈妈读懂信的内容并讲给我听，与“帮我”和“这封信”相符。", "洗": "搭配：“洗”不能说“洗这封信”。"}, "sentence_index": 0, "correct_answer": "解读"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把法语解读成了英语。", "explanation": "这里应该用〈翻译〉。“解读”是说明文字的意思，不指语言之间的转换，应说“翻译”。"}, {"text": "他解读了一只鸡。", "explanation": "这里应该用〈宰〉。“解读”是把文字、信息讲明白，不指处理一只鸡；宰杀禽畜要说“宰”。"}, {"text": "他解读干净了黑板。", "explanation": "这里应该用〈擦〉。“解读”指说明意思，不能用来指擦拭黑板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：“喝”的宾语应为饮品，与“旧书”不符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应为食物，不能说“吃一本旧书”。"}, {"text": "解读", "is_correct": true, "explanation": "“爷爷正在解读一本旧书”指爷爷读懂并讲解旧书的内容，与“正在”和“一本旧书”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象应为歌曲，不能说“唱一本旧书”。"}], "explanations": {"喝": "语义：“喝”的宾语应为饮品，与“旧书”不符。", "吃": "搭配：“吃”的宾语应为食物，不能说“吃一本旧书”。", "解读": "“爷爷正在解读一本旧书”指爷爷读懂并讲解旧书的内容，与“正在”和“一本旧书”相符。", "唱": "语义：“唱”的对象应为歌曲，不能说“唱一本旧书”。"}, "sentence_index": 6, "correct_answer": "解读"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人解读了屋顶。", "explanation": "这里应该用〈修补〉。“解读”指说明意思，不能用来指修补屋顶。"}, {"text": "阿姨解读了房间。", "explanation": "这里应该用〈打扫〉。“解读”指说明意思，不能用来指打扫房间。"}, {"text": "他解读了鞋带。", "explanation": "这里应该用〈系〉。“解读”指说明意思，不能用来指系鞋带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经解读了完这封信了。", "corrected_sentence": "我已经解读完这封信了。", "error_description": "结果补语“完”要紧跟动词，“解读”与“完”之间不能插入“了”；应为“解读完这封信了”，“解读了完”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前请他解读着过这封信。", "corrected_sentence": "我以前请他解读过这封信。", "error_description": "“过”表示经历，要紧跟动词“解读”，“着”与“过”不能同用；应为“解读过这封信”，“解读着过”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
