INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92478, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分析并解释，使人理解。", "primary_collocate": null, "pronunciation": "jiě dú", "ipa": "tɕjɛ˨˩ tu˧˥", "syllable_count": 2, "sentences": [{"text": "老师正在解读这首诗。", "target_word": "解读", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家解读了新的政策。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你解读一下这张图表。", "target_word": "解读", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "记者用简单的话解读了这个消息。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这份报告解读得很清楚。", "target_word": "解读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家从不同的角度解读这件事。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她认真解读了合同里的每一条。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师解读课文时，学生都听得很认真。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位经济学家解读了今年的数据。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视上有专家在解读这个新闻。", "target_word": "解读", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "解读了", "label": "体标"}, {"form": "解读着", "label": "体标"}, {"form": "解读过", "label": "体标"}, {"form": "解读者", "label": "复合"}, {"form": "解讀", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对政策、数据、作品等进行分析并加以解释，让别人明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应为食物，不能说“吃这首诗”。"}, {"text": "解读", "is_correct": true, "explanation": "“老师正在解读这首诗”指老师分析并讲解诗的意思，与“正在”和“这首诗”都相符。"}, {"text": "熬", "is_correct": false, "explanation": "搭配：“熬”多用于熬汤、熬粥，不能说“熬这首诗”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的宾语应为饮品，与“这首诗”不符。"}], "explanations": {"吃": "搭配：“吃”的宾语应为食物，不能说“吃这首诗”。", "解读": "“老师正在解读这首诗”指老师分析并讲解诗的意思，与“正在”和“这首诗”都相符。", "熬": "搭配：“熬”多用于熬汤、熬粥，不能说“熬这首诗”。", "喝": "语义：“喝”的宾语应为饮品，与“这首诗”不符。"}, "sentence_index": 0, "correct_answer": "解读"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把英文解读成了中文。", "explanation": "这里应该用〈翻译〉。“解读”是分析说明意思，不指语言之间的转换，把英文变成中文要说“翻译”。"}, {"text": "医生用药解读，救活了中毒的病人。", "explanation": "这里应该用〈解毒〉。“解读”与“解毒”读音相同，但“解读”指分析说明，不能用来指消除毒性。"}, {"text": "她解读了一杯水。", "explanation": "这里应该用〈化验〉。“解读”是把文字、数据等信息讲明白，不指检测液体的成分；检测一杯水的成分要说“化验”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能用于“合同里的每一条”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“每一条”（条款）搭配。"}, {"text": "解读", "is_correct": true, "explanation": "“她认真解读了合同里的每一条”指她仔细分析并理解了各项条款，与“认真”和“合同”相符。"}, {"text": "炒", "is_correct": false, "explanation": "语义：“炒”的对象是食物，不能说“炒合同里的每一条”。"}], "explanations": {"煮": "语义：“煮”的对象是食物，不能用于“合同里的每一条”。", "洗": "搭配：“洗”不能与“每一条”（条款）搭配。", "解读": "“她认真解读了合同里的每一条”指她仔细分析并理解了各项条款，与“认真”和“合同”相符。", "炒": "语义：“炒”的对象是食物，不能说“炒合同里的每一条”。"}, "sentence_index": 6, "correct_answer": "解读"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生正在解读一只青蛙。", "explanation": "这里应该用〈解剖〉。“解读”用于说明文字、信息的意思，不能用于切开实物。"}, {"text": "工人解读好了那台机器。", "explanation": "这里应该用〈修〉。“解读”指说明意思，不能用来指修理机器。"}, {"text": "他解读了绳子。", "explanation": "这里应该用〈解开〉。“解读”指说明意思，不能用于解开绳子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "专家正在解读了这份报告。", "corrected_sentence": "专家正在解读这份报告。", "error_description": "“正在”表示动作进行，不与“了”同用，应为“正在解读这份报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学者们已经解读了过这份文件。", "corrected_sentence": "学者们已经解读过这份文件。", "error_description": "“过”是动态助词，要紧跟动词“解读”，“了”与“过”不能连用于同一动词；应为“已经解读过这份文件”，“解读了过”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
