INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92479, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "终究是说到最后，还是会这样。", "primary_collocate": null, "pronunciation": "zhōng jiū", "ipa": "ʈʂʊŋ˥ tɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "再好的朋友，终究也会分开。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谎话说多了，终究会有人知道。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时间终究会让人忘记这件事。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "努力终究不会白费。", "target_word": "终究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天终究会来的。", "target_word": "终究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他再想躲，终究还是要面对。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事情终究要有个结果。", "target_word": "终究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做错的事，终究要自己负责。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路再长，终究会走到头。", "target_word": "终究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "再黑的夜，终究会天亮。", "target_word": "终究", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "终究：说到最后，结果还是会这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终究", "is_correct": true, "explanation": "终究：说到最后还是会这样，与“也会分开”的结果相合"}, {"text": "幸好", "is_correct": false, "explanation": "语义：幸好表示庆幸，与“分开”这一结果不合"}, {"text": "已经", "is_correct": false, "explanation": "体貌：已经表示已然，与“会分开”的将来相悖"}, {"text": "刚刚", "is_correct": false, "explanation": "体貌：刚刚表示不久前已发生，与“会分开”的将来相悖"}], "explanations": {"终究": "终究：说到最后还是会这样，与“也会分开”的结果相合", "幸好": "语义：幸好表示庆幸，与“分开”这一结果不合", "已经": "体貌：已经表示已然，与“会分开”的将来相悖", "刚刚": "体貌：刚刚表示不久前已发生，与“会分开”的将来相悖"}, "sentence_index": 0, "correct_answer": "终究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们终究刚刚开始学习这门课。", "explanation": "这里应该用〈起初〉。终究表示最后的结果，不能用于刚开始的事"}, {"text": "你终究快点写作业吧。", "explanation": "这里应该用〈赶紧〉。终究表示最终结果，不能用于催促别人立即行动"}, {"text": "你终究再说一遍，好吗？", "explanation": "这里应该用〈请〉。终究表示最终结果，不能用于请求别人做事"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终究", "is_correct": true, "explanation": "终究：说到最后必然如此，与“要有个结果”相合"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示少有，与“要有个结果”的必然性相悖"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：曾经表示过去，与“要”的将来相悖"}, {"text": "险些", "is_correct": false, "explanation": "语义：险些表示几乎发生却未发生，与“要有个结果”不合"}], "explanations": {"终究": "终究：说到最后必然如此，与“要有个结果”相合", "偶尔": "语义：偶尔表示少有，与“要有个结果”的必然性相悖", "曾经": "体貌：曾经表示过去，与“要”的将来相悖", "险些": "语义：险些表示几乎发生却未发生，与“要有个结果”不合"}, "sentence_index": 6, "correct_answer": "终究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天终究去跑步。", "explanation": "这里应该用〈总是〉。终究表示最后的结果，不表示习惯或经常"}, {"text": "我们终究先吃饭，再去看电影。", "explanation": "这里应该用〈首先〉。终究表示最后的结果，不表示先后次序"}, {"text": "我很喜欢这部电影，终究每周都看。", "explanation": "这里应该用〈经常〉。终究表示最后的结果，不能表示经常发生"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终究的会回来，你别担心。", "corrected_sentence": "他终究会回来，你别担心。", "error_description": "副词误加“的”：“终究”是副词，后面不能加“的”再接“会”。正确形式：他终究会回来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个秘密很终究要被揭开。", "corrected_sentence": "这个秘密终究要被揭开。", "error_description": "“终究”是副词，不能被“很”修饰。错误在于“很终究”，应去掉“很”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
