INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92480, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，到底，最终。", "primary_collocate": null, "pronunciation": "zhōng jiū", "ipa": "ʈʂʊŋ˥ tɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "他终究是个孩子，别太严格。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想了很久，终究还是答应了。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子终究要长大。", "target_word": "终究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他找了半年，终究没有找到。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱终究不是最重要的。", "target_word": "终究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们终究还是走到了一起。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们终究是一家人。", "target_word": "终究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "梦想终究要靠自己去实现。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她跑得再快，终究还是输了。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人终究还是离开了家乡。", "target_word": "终究", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "终究：副词，表示到底、最终", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终究", "is_correct": true, "explanation": "终究：到底、最终，与“是个孩子，别太严格”的判断相合"}, {"text": "幸好", "is_correct": false, "explanation": "语义：幸好表示庆幸，与“是个孩子，别太严格”的判断不合"}, {"text": "刚刚", "is_correct": false, "explanation": "体貌：刚刚表示不久前，与“是个孩子”的既定状态不合"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示不常，与“是个孩子”的身份相悖"}], "explanations": {"终究": "终究：到底、最终，与“是个孩子，别太严格”的判断相合", "幸好": "语义：幸好表示庆幸，与“是个孩子，别太严格”的判断不合", "刚刚": "体貌：刚刚表示不久前，与“是个孩子”的既定状态不合", "偶尔": "语义：偶尔表示不常，与“是个孩子”的身份相悖"}, "sentence_index": 0, "correct_answer": "终究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终究一边看书一边吃饭。", "explanation": "这里应该用〈同时〉。终究表示最终结果，不能用于两个动作同时进行"}, {"text": "请你终究别迟到。", "explanation": "这里应该用〈千万〉。终究表示最终结果，不用于祈使句中的叮嘱"}, {"text": "你等等，我终究一会儿就回来。", "explanation": "这里应该用〈马上〉。终究表示最终结果，不能表示即将发生"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终究", "is_correct": true, "explanation": "终究：到底、最终，与“是一家人”的关系相合"}, {"text": "险些", "is_correct": false, "explanation": "语义：险些表示几乎发生却未发生，与“是一家人”的事实不合"}, {"text": "忽然", "is_correct": false, "explanation": "语义：忽然表示突然，与“是一家人”的既定关系不合"}, {"text": "刚才", "is_correct": false, "explanation": "体貌：刚才表示不久前，与“是”所表示的恒定关系矛盾"}], "explanations": {"终究": "终究：到底、最终，与“是一家人”的关系相合", "险些": "语义：险些表示几乎发生却未发生，与“是一家人”的事实不合", "忽然": "语义：忽然表示突然，与“是一家人”的既定关系不合", "刚才": "体貌：刚才表示不久前，与“是”所表示的恒定关系矛盾"}, "sentence_index": 6, "correct_answer": "终究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些苹果终究多少钱？", "explanation": "这里应该用〈一共〉。终究表示最终结果，不表示数量的总计"}, {"text": "我们终究动身吧。", "explanation": "这里应该用〈马上〉。终究表示最终结果，不能用于表示即刻的行动"}, {"text": "我终究去公园跑步，一周三四次。", "explanation": "这里应该用〈经常〉。终究表示最终结果，不表示经常的习惯"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事终究我的错，我愿意承担。", "corrected_sentence": "这件事终究是我的错，我愿意承担。", "error_description": "漏掉了“是”。“终究”后面要接判断动词“是”，应为“终究是我的错”，不能说“终究我的错”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈很终究会同意的，你别担心。", "corrected_sentence": "妈妈终究会同意的，你别担心。", "error_description": "“终究”是副词，不能被“很”修饰。错误在于“很终究”，应去掉“很”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
