INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92482, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "客套话，请对方按自己的意愿行事。", "primary_collocate": null, "pronunciation": "qǐng biàn", "ipa": "tɕʰiŋ˨˩˦ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "客人说想看看，我说：“请便。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我可以先坐下吗？”“请便。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问我能不能开窗，我说请便。", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说：“我想先走了。”我说：“请便！”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友问：“我能用你的电脑吗？”我答：“请便。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生说：“你们想坐哪儿，请便。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我想自己看看。”“好的，请便。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想休息一下，我说：“请便。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员笑着说：“您请便，有事叫我。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我能拍照吗？”“请便，不用客气。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "回答对方请求时单独使用的客套话，表示同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e57226eb-7676-4c4b-9e91-9ee86200188c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "请便", "is_correct": true, "explanation": "正确。客人想看看，回答“请便”表示同意对方随意看，与句意相合。"}, {"text": "请假", "is_correct": false, "explanation": "语义：“请假”是请求休假，不能用来回应客人想看看。"}, {"text": "请问", "is_correct": false, "explanation": "语义：“请问”是开口询问，与“想看看”的意思不合。"}, {"text": "请示", "is_correct": false, "explanation": "语域：“请示”是正式的请求指示用语，不用于这种日常客套应答。"}], "explanations": {"请便": "正确。客人想看看，回答“请便”表示同意对方随意看，与句意相合。", "请假": "语义：“请假”是请求休假，不能用来回应客人想看看。", "请问": "语义：“请问”是开口询问，与“想看看”的意思不合。", "请示": "语域：“请示”是正式的请求指示用语，不用于这种日常客套应答。"}, "sentence_index": 0, "correct_answer": "请便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她说：“谢谢你。”我说：“请便！”", "explanation": "这里应该用〈不客气〉。“请便”是请对方自行其是，不用来回应感谢。"}, {"text": "他踩了我一脚，连忙说：“请便。”", "explanation": "这里应该用〈对不起〉。“请便”是客套话，表示让对方自便，不能用来道歉。"}, {"text": "我问：“请便，车站在哪儿？”", "explanation": "这里应该用〈请问〉。“请便”不用于开口询问，询问时要说“请问”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请便", "is_correct": true, "explanation": "正确。“好的，请便”是同意对方自行其是的应答客套话，与句意相合。"}, {"text": "请客", "is_correct": false, "explanation": "语义：“请客”是请人吃饭，回应“想自己看看”时句意不通。"}, {"text": "请讲", "is_correct": false, "explanation": "语义：“请讲”是请对方说话，与“想自己看看”的意思不合。"}, {"text": "请假", "is_correct": false, "explanation": "搭配：“请假”是请求休假，不能用来回应对方想自己看看。"}], "explanations": {"请便": "正确。“好的，请便”是同意对方自行其是的应答客套话，与句意相合。", "请客": "语义：“请客”是请人吃饭，回应“想自己看看”时句意不通。", "请讲": "语义：“请讲”是请对方说话，与“想自己看看”的意思不合。", "请假": "搭配：“请假”是请求休假，不能用来回应对方想自己看看。"}, "sentence_index": 6, "correct_answer": "请便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“对不起，我踩到您了。”“请便。”", "explanation": "这里应该用〈没关系〉。“请便”是请对方自便，不能用来回应道歉。"}, {"text": "“你的东西会不会丢？”“请便。”", "explanation": "这里应该用〈请放心〉。“请便”是请对方按自己的意愿行事，不能用来宽慰对方。"}, {"text": "“地上有水。”“请便。”", "explanation": "这里应该用〈请小心〉。“请便”是请对方按自己的意愿行事，不能用来提醒对方小心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“我能用一下洗手间吗？”“请便了。”", "corrected_sentence": "“我能用一下洗手间吗？”“请便。”", "error_description": "错误在“请便”后加了“了”。作为应答的客套话，“请便”后面不能加“了”，应直接说“请便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“我可以先走吗？”“不请便吧。”", "corrected_sentence": "“我可以先走吗？”“请便吧。”", "error_description": "错误在“请便”前加了“不”。“请便”是同意对方的客套话，不能否定，应说“请便吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
