INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92483, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说到某一件事。", "primary_collocate": null, "pronunciation": "jiǎng dào", "ipa": "tɕjɑŋ˨˩˦ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "老师讲到了第五课。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到这里，大家有问题吗？", "target_word": "讲到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他讲到小时候的故事。", "target_word": "讲到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "讲到吃，我最有发言权。", "target_word": "讲到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷讲到战争，眼睛红了。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到旅行，她的话就多起来。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到中国的历史，他说得特别好。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈讲到工作，叹了口气。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们聊天时讲到过这家饭馆。", "target_word": "讲到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上经理讲到明年的计划。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "讲到了", "label": "体标（了）"}, {"form": "讲到过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "说话时涉及到某件事或某个话题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92483, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "讲到", "is_correct": true, "explanation": "“讲到”（jiǎng dào）是正确答案，意思是说到某件事。"}, {"text": "降到", "is_correct": false, "explanation": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是降低到某个程度。"}, {"text": "减到", "is_correct": false, "explanation": "jiǎn 与 jiǎng 韵母不同（an 与 ang），意思是减少到某个数量。"}, {"text": "想到", "is_correct": false, "explanation": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是想起、想到。"}], "explanations": {"讲到": "“讲到”（jiǎng dào）是正确答案，意思是说到某件事。", "降到": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是降低到某个程度。", "减到": "jiǎn 与 jiǎng 韵母不同（an 与 ang），意思是减少到某个数量。", "想到": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是想起、想到。"}, "sentence_index": null, "correct_answer": "讲到"}, "level_3": {"options": [{"text": "讲到", "is_correct": true, "explanation": "“讲到”表示说到第五课的内容，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，不能接“第五课”。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是物理动作，撕一门课的说法不能成立。"}, {"text": "吃到", "is_correct": false, "explanation": "搭配：“吃到”不能接“第五课”这样的教学内容，句子不通。"}], "explanations": {"讲到": "“讲到”表示说到第五课的内容，符合句意。", "喝": "搭配：“喝”的宾语应是饮品，不能接“第五课”。", "撕": "语义：“撕”是物理动作，撕一门课的说法不能成立。", "吃到": "搭配：“吃到”不能接“第五课”这样的教学内容，句子不通。"}, "sentence_index": 0, "correct_answer": "讲到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙讲到了包里。", "explanation": "这里应该用〈放〉。讲到表示提及话题，不能表示把钥匙放进某处；这一意思要用“放”。"}, {"text": "他把这本书讲到了桌子上。", "explanation": "这里应该用〈放〉。讲到表示提及话题，不能带着实物移到某处；把书放到桌子上要用“放”。"}, {"text": "妈妈把碗讲到了柜子里。", "explanation": "这里应该用〈放〉。讲到表示提及话题，不能表示把碗放进某处；这一意思要用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92483, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "讲到", "is_correct": true, "explanation": "“讲到”（jiǎng dào）是正确答案，意思是说到某件事。"}, {"text": "将到", "is_correct": false, "explanation": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是快要到。"}, {"text": "抢到", "is_correct": false, "explanation": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺到。"}, {"text": "捡到", "is_correct": false, "explanation": "jiǎn 与 jiǎng 韵母不同（an 与 ang），意思是拾到、捡到。"}], "explanations": {"讲到": "“讲到”（jiǎng dào）是正确答案，意思是说到某件事。", "将到": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是快要到。", "抢到": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺到。", "捡到": "jiǎn 与 jiǎng 韵母不同（an 与 ang），意思是拾到、捡到。"}, "sentence_index": null, "correct_answer": "讲到"}, "level_3": {"options": [{"text": "讲到", "is_correct": true, "explanation": "“讲到”表示谈话中说到中国的历史，符合句意。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记历史与“说得特别好”相矛盾，句子不通。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”用于文件、数据，不能接“历史”作谈话内容。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑历史与“说得特别好”的语境不合，句子不通。"}], "explanations": {"讲到": "“讲到”表示谈话中说到中国的历史，符合句意。", "忘记": "语义：忘记历史与“说得特别好”相矛盾，句子不通。", "删除": "搭配：“删除”用于文件、数据，不能接“历史”作谈话内容。", "嘲笑": "语义：嘲笑历史与“说得特别好”的语境不合，句子不通。"}, "sentence_index": 6, "correct_answer": "讲到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经理把计划讲到了桌子下。", "explanation": "这里应该用〈放〉。讲到表示提及话题，不能把计划放到某处；计划不是可以放置的实物，把东西放到桌下要用“放”。"}, {"text": "经理把这张桌子讲到了墙边。", "explanation": "这里应该用〈推〉。讲到表示提及话题，不能表示推动实物到某处；推动桌子要用“推”。"}, {"text": "经理讲到会议室门口，就转身出去了。", "explanation": "这里应该用〈走〉。讲到表示谈到某件事，不能表示走到某地；“走到会议室门口”要用“走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈讲到过了昨天的聚会。", "corrected_sentence": "妈妈讲到了昨天的聚会。", "error_description": "错误形式是“讲到过了”：“过”（经历）与“了”（完成）叠用在“讲到”后面，表达不自然；这里只用“了”表示完成，正确形式是“讲到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议上他把讲到了这个问题。", "corrected_sentence": "会议上他讲到了这个问题。", "error_description": "错误形式是“把讲到了这个问题”，正确形式是“讲到了这个问题”。“把”字句要求宾语提到动词前，而“讲到”的宾语“这个问题”应直接放在动词后，不能加“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
