INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92484, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "谈到；说到。", "primary_collocate": null, "pronunciation": "jiǎng dào", "ipa": "tɕjɑŋ˨˩˦ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "讲到钱，他有点不好意思。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到音乐，大家都很兴奋。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到这件事，她还很生气。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到价格，老板不愿多说。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说明会上，老师讲到考试的方法。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到健康，医生建议多运动。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到学习，他总有很多想法。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到未来，他充满了信心。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "讲到做饭，我比不上我姐姐。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天开会时，他讲到了环保问题。", "target_word": "讲到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "讲到了", "label": "体标（了）"}, {"form": "讲到过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "谈话中提到、涉及某个话题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6312ee1-cc85-480e-9e11-314a38805b1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92484, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "讲到", "is_correct": true, "explanation": "“讲到”（jiǎng dào）是正确答案，意思是谈到某个话题。"}, {"text": "降到", "is_correct": false, "explanation": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是降低到某个程度。"}, {"text": "减到", "is_correct": false, "explanation": "jiǎn 与 jiǎng 韵母不同（an 与 ang），意思是减少到某个数量。"}, {"text": "想到", "is_correct": false, "explanation": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是想起、想到。"}], "explanations": {"讲到": "“讲到”（jiǎng dào）是正确答案，意思是谈到某个话题。", "降到": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是降低到某个程度。", "减到": "jiǎn 与 jiǎng 韵母不同（an 与 ang），意思是减少到某个数量。", "想到": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是想起、想到。"}, "sentence_index": null, "correct_answer": "讲到"}, "level_3": {"options": [{"text": "讲到", "is_correct": true, "explanation": "“讲到”表示谈话涉及钱这个话题，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔钱”表示丢弃钱，与“他有点不好意思”的语境不合，句子不通。"}, {"text": "印", "is_correct": false, "explanation": "语义：“印钱”指印制货币，不能作为一般谈话中的动作，句子不通。"}, {"text": "铸", "is_correct": false, "explanation": "语义：“铸钱”指铸造货币，与句中的谈话语境不合。"}], "explanations": {"讲到": "“讲到”表示谈话涉及钱这个话题，符合句意。", "扔": "语义：“扔钱”表示丢弃钱，与“他有点不好意思”的语境不合，句子不通。", "印": "语义：“印钱”指印制货币，不能作为一般谈话中的动作，句子不通。", "铸": "语义：“铸钱”指铸造货币，与句中的谈话语境不合。"}, "sentence_index": 0, "correct_answer": "讲到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把眼镜讲到了桌上。", "explanation": "这里应该用〈放〉。讲到表示提及话题，不能表示把眼镜放到某处；这一意思要用“放”。"}, {"text": "他把杯子讲到了桌子上。", "explanation": "这里应该用〈放〉。讲到表示提及话题，不能把杯子移到某处；把杯子放到桌子上要用“放”。"}, {"text": "妈妈把菜讲到了冰箱里。", "explanation": "这里应该用〈放〉。讲到表示提及话题，不能表示把菜放进某处；这一意思要用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92484, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "讲到", "is_correct": true, "explanation": "“讲到”（jiǎng dào）是正确答案，意思是谈到某个话题。"}, {"text": "将到", "is_correct": false, "explanation": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是快要到。"}, {"text": "抢到", "is_correct": false, "explanation": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺到。"}, {"text": "捡到", "is_correct": false, "explanation": "jiǎn 与 jiǎng 韵母不同（an 与 ang），意思是拾到、捡到。"}], "explanations": {"讲到": "“讲到”（jiǎng dào）是正确答案，意思是谈到某个话题。", "将到": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是快要到。", "抢到": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺到。", "捡到": "jiǎn 与 jiǎng 韵母不同（an 与 ang），意思是拾到、捡到。"}, "sentence_index": null, "correct_answer": "讲到"}, "level_3": {"options": [{"text": "讲到", "is_correct": true, "explanation": "“讲到”表示谈话中提到学习这个话题，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能接“学习”。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦拭物体，不能接“学习”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，不能接“学习”。"}], "explanations": {"讲到": "“讲到”表示谈话中提到学习这个话题，符合句意。", "吃": "搭配：“吃”的宾语应是食物，不能接“学习”。", "擦": "搭配：“擦”用于擦拭物体，不能接“学习”。", "喝": "搭配：“喝”的宾语应是饮品，不能接“学习”。"}, "sentence_index": 6, "correct_answer": "讲到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经理把合同讲到了抽屉里。", "explanation": "这里应该用〈放〉。讲到表示提及话题，不能把合同放到某处；把合同放进抽屉要用“放”。"}, {"text": "我讲到教室门口，就进去了。", "explanation": "这里应该用〈走〉。讲到表示谈到某件事，不能表示走到某地；“走到教室门口”要用“走”。"}, {"text": "这本书讲到了我的桌子上。", "explanation": "这里应该用〈放〉。讲到表示提及话题，不能把书放到某处；把书放到桌子上要用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板讲到过了房租的事。", "corrected_sentence": "老板讲到了房租的事。", "error_description": "错误形式是“讲到过了”：“过”（经历）与“了”（完成）叠用在“讲到”后面，表达不自然；这里只用“了”表示完成，正确形式是“讲到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个老师讲到的过那位作家。", "corrected_sentence": "这个老师讲到过那位作家。", "error_description": "错误形式是“讲到的过”，正确形式是“讲到过”。“的”不能插在动词补语“到”和体标“过”之间，“讲到过”中的“过”应直接紧跟“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c73c3855-31f5-4796-b66d-21a7a8336ea2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
