INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92485, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "线图是用线画出来的图。", "primary_collocate": null, "pronunciation": "xiàn tú", "ipa": "ɕjɛn˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "老师在黑板上画了一张线图。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张线图是用黑线画出来的。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用笔画了一张房子的线图。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先画线图，再给它涂颜色。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张线图很简单，只有几条线。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把花的线图交给了美术老师。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上有一张小狗的线图。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线图画好以后，我们再上色。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢看汽车的线图。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张线图里没有一点颜色。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "折线图", "label": "复合"}], "register": "中性", "sense_fingerprint": "只用线条画成的图画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62eac6f8-55d8-4516-a7c5-4d8181c28db1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92485, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线图", "is_correct": true, "explanation": "线图是用线条画出来的图，黑板上可以画一张线图，与“画了一张”搭配。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“画”的对象是图画，照片要用“拍”，不能说“画了一张照片”。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸是画图用的材料，不是画出来的东西，“画了一张纸”说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：句中已有“黑板上”，不能在黑板上再画出一块黑板。"}], "explanations": {"线图": "线图是用线条画出来的图，黑板上可以画一张线图，与“画了一张”搭配。", "照片": "搭配：“画”的对象是图画，照片要用“拍”，不能说“画了一张照片”。", "纸": "语义：纸是画图用的材料，不是画出来的东西，“画了一张纸”说不通。", "黑板": "语义：句中已有“黑板上”，不能在黑板上再画出一块黑板。"}, "sentence_index": 0, "correct_answer": "线图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们迷路了，就打开手机上的线图找路。", "explanation": "这里应该用〈地图〉。线图是用线条画出来的图画，不能用来找路，找路要看〈地图〉。"}, {"text": "他把线图穿进了针眼。", "explanation": "这里把〈线图〉当成了〈缝衣线〉。线图是画出来的图，不是缝衣线，不能穿进针眼。"}, {"text": "他对着线图弹钢琴，一个音都没弹错。", "explanation": "这里应该用〈乐谱〉。线图是用线画出来的图，不记录音符，弹钢琴要看〈乐谱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线图", "is_correct": true, "explanation": "书上可以有一张小狗的线图，这是用线条画出来的图，符合句子。"}, {"text": "成绩单", "is_correct": false, "explanation": "搭配：成绩单指学生的分数记录，不说“小狗的成绩单”。"}, {"text": "课表", "is_correct": false, "explanation": "语义：课表是安排课程的表格，与小狗无关，书上不会有小狗的课表。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单是饭馆点菜用的，书上不会有小狗的菜单。"}], "explanations": {"线图": "书上可以有一张小狗的线图，这是用线条画出来的图，符合句子。", "成绩单": "搭配：成绩单指学生的分数记录，不说“小狗的成绩单”。", "课表": "语义：课表是安排课程的表格，与小狗无关，书上不会有小狗的课表。", "菜单": "语义：菜单是饭馆点菜用的，书上不会有小狗的菜单。"}, "sentence_index": 6, "correct_answer": "线图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手机给风景拍了一张线图。", "explanation": "这里应该用〈照片〉。线图是画出来的，不是拍出来的，不能用“拍”。"}, {"text": "地铁司机沿着线图一直开到了终点站。", "explanation": "这里应该用〈线路〉。线图是画出来的图，地铁只能沿着线路行驶，不能沿着一张图开。"}, {"text": "他用线图做了一个蛋糕。", "explanation": "这里把〈线图〉误当成了〈面粉〉这类食材。线图是用线画出来的图，不能当材料做蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在厨房的墙上挂了一只线图。", "corrected_sentence": "妈妈在厨房的墙上挂了一张线图。", "error_description": "错误：量词用了“只”。正确：“一张线图”。线图是平面的图画，量词要用“张”，“只”不能用于线图。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理把这只线图改好了。", "corrected_sentence": "经理把这张线图改好了。", "error_description": "错误：量词用了“只”。正确：“这张线图”。线图是平面的图画，量词要用“张”，“只”不能用于线图。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
