INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92486, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以线条表示数量变化或结构的图。", "primary_collocate": null, "pronunciation": "xiàn tú", "ipa": "ɕjɛn˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "这张线图表示今年气温的变化。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从线图可以看出，销量越来越高。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们看线图回答问题。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线图上的线一直往上走。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张线图说明人口在增加。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理用线图给大家讲了这个月的情况。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线图显示，价格去年下半年下降了。", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看这张线图，哪个月雨最多？", "target_word": "线图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张线图表示公司利润的增长。", "target_word": "线图", "complexity_tier": "T3", "furigana": "zhè zhāng xiàn tú biǎo shì gōng sī lì rùn de zēng zhǎng", "sentence_source": "generated"}, {"text": "他把两年的降雨量画成了一张线图。", "target_word": "线图", "complexity_tier": "T3", "furigana": "tā bǎ liǎng nián de jiàng yǔ liàng huà chéng le yì zhāng xiàn tú", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "折线图", "label": "复合"}], "register": "中性", "sense_fingerprint": "用线条表示数量变化或结构的图表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62eac6f8-55d8-4516-a7c5-4d8181c28db1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线图", "is_correct": true, "explanation": "线图用线条表示数量或结构，可以表示气温的变化，符合句子。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱记录做菜的步骤，不表示气温的变化。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“表示”后接的是数据或变化，照片一般说“拍下”或“记录”。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单记录费用明细，不表示气温的变化。"}], "explanations": {"线图": "线图用线条表示数量或结构，可以表示气温的变化，符合句子。", "菜谱": "语义：菜谱记录做菜的步骤，不表示气温的变化。", "照片": "搭配：“表示”后接的是数据或变化，照片一般说“拍下”或“记录”。", "账单": "语义：账单记录费用明细，不表示气温的变化。"}, "sentence_index": 0, "correct_answer": "线图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张线图的每根柱子都不一样高，最高的是十月。", "explanation": "这里应该用〈柱状图〉。线图用线条的走势表示变化，每根柱子高矮表示数量要说〈柱状图〉。"}, {"text": "我们迷路了，就看着线图找到了回家的路。", "explanation": "这里应该用〈地图〉。线图用线条表示数量变化或结构，不能用来找路，找路要看〈地图〉。"}, {"text": "这张线图的每一块都代表一个地区的比例，大小不一样。", "explanation": "这里应该用〈饼图〉。线图用线条表示数量变化，没有分成块的比例，各部分占比要说〈饼图〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线图", "is_correct": true, "explanation": "线图可以显示价格的变化，“线图显示，价格……下降了”说得通。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片记录个人信息，不显示价格的变化。"}, {"text": "天气预报", "is_correct": false, "explanation": "搭配：天气预报只报天气，不报价格，“显示”后接价格的不是它。"}, {"text": "体检报告", "is_correct": false, "explanation": "语义：体检报告记录身体检查的结果，不显示价格的变化。"}], "explanations": {"线图": "线图可以显示价格的变化，“线图显示，价格……下降了”说得通。", "名片": "语义：名片记录个人信息，不显示价格的变化。", "天气预报": "搭配：天气预报只报天气，不报价格，“显示”后接价格的不是它。", "体检报告": "语义：体检报告记录身体检查的结果，不显示价格的变化。"}, "sentence_index": 6, "correct_answer": "线图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手机给风景拍了一张线图。", "explanation": "这里应该用〈照片〉。线图是画出来的图表，不是拍出来的，不能用“拍”。"}, {"text": "妈妈对着线图教我弹钢琴，我一个音都没弹错。", "explanation": "这里应该用〈乐谱〉。线图表示数量或结构，不记录音符，弹钢琴要看〈乐谱〉。"}, {"text": "这张线图的人物表情很生动，像一幅肖像。", "explanation": "这里把〈线图〉当成了〈人像画〉。线图表示数量或结构，画不出人物表情，人物画要说〈人像画〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师用一只线图展示了考试成绩的变化。", "corrected_sentence": "老师用一张线图展示了考试成绩的变化。", "error_description": "错误：量词用了“只”。正确：“一张线图”。线图是平面图表，量词要用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理把这只线图改好了。", "corrected_sentence": "经理把这张线图改好了。", "error_description": "错误：量词用了“只”。正确：“这张线图”。线图是平面图表，量词要用“张”，“只”不能用于线图。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
