INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有很多钱，开工厂请人干活来赚钱的人。", "primary_collocate": null, "pronunciation": "zī běn jiā", "ipa": "tsɹ̩˥ pən˨˩˦ tɕja˥", "syllable_count": 3, "sentences": [{"text": "他是一个资本家。", "target_word": "资本家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "资本家很有钱。", "target_word": "资本家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位资本家开了很多工厂。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "资本家请工人给他干活。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个资本家住在大房子里。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的爷爷是一位有名的资本家。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "资本家用赚来的钱又开了一家新工厂。", "target_word": "资本家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天工作很多小时，资本家却不给他们多少钱。", "target_word": "资本家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位资本家看着工厂里的工人，心里想着赚钱。", "target_word": "资本家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的资本家把工人的工资压得很低。", "target_word": "资本家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "資本家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有很多钱、开工厂请人干活赚钱的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "银行", "is_correct": false, "explanation": "语义：银行是机构，不能指人，“他是一个银行”句意不通。"}, {"text": "资本家", "is_correct": true, "explanation": "正确：“资本家”指占有资本、雇人赚钱的人，可以用“一个”指人。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“一个”不能配“书”，书要用“本”，而且书不是人。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能充当“他是……”所指的人。"}], "explanations": {"银行": "语义：银行是机构，不能指人，“他是一个银行”句意不通。", "资本家": "正确：“资本家”指占有资本、雇人赚钱的人，可以用“一个”指人。", "书": "搭配：“一个”不能配“书”，书要用“本”，而且书不是人。", "桌子": "语义：桌子是家具，不能充当“他是……”所指的人。"}, "sentence_index": 0, "correct_answer": "资本家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "资本家每天早上在学校给学生上课。", "explanation": "这里应该用〈教师〉。给学生上课的是教师；资本家指占有资本、雇用工人获利的人，不以教课为业。"}, {"text": "资本家每天早上五点下地干活。", "explanation": "这里应该用〈农民〉。下地干活的是农民；资本家占有资本、雇人获利，不亲自从事农活。"}, {"text": "资本家每天在街角卖煎饼。", "explanation": "这里应该用〈小贩〉。沿街卖煎饼的是小贩；资本家指占有大量资本的人，不是街边小商贩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不会赚钱，也不会开工厂，句意不通。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生没有资本，不会用赚来的钱开工厂。"}, {"text": "资本家", "is_correct": true, "explanation": "正确：只有占有资本的资本家，才能用赚来的钱再开一家新工厂。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐没有资本，不可能用赚来的钱再开一家新工厂。"}], "explanations": {"小狗": "语义：小狗是动物，不会赚钱，也不会开工厂，句意不通。", "学生": "语义：学生没有资本，不会用赚来的钱开工厂。", "资本家": "正确：只有占有资本的资本家，才能用赚来的钱再开一家新工厂。", "乞丐": "语义：乞丐没有资本，不可能用赚来的钱再开一家新工厂。"}, "sentence_index": 6, "correct_answer": "资本家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村来了一只资本家。", "explanation": "这里应该用〈位〉或〈个〉。“只”多用于动物，指人的资本家不能用“只”。"}, {"text": "那条资本家很有钱。", "explanation": "这里应该用〈位〉或〈个〉。“条”多用于细长的东西，指人的资本家不能用“条”。"}, {"text": "工厂里来了一头资本家。", "explanation": "这里应该用〈位〉或〈个〉。“头”多用于牲畜，用来指人不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只资本家。", "corrected_sentence": "他是一位资本家。", "error_description": "量词错误：“资本家”指人，应用“位”或“个”，不能用“只”（“只”多用于动物）。正确说法是“一位资本家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的父亲年轻时是一位资本家们。", "corrected_sentence": "他的父亲年轻时是一位资本家。", "error_description": "复数错误：“一位”表示单数，不能与表示复数的“们”同用，应说“一位资本家”，不能说“一位资本家们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
