INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "占有资本、雇用工人并获取利润的人。", "primary_collocate": null, "pronunciation": "zī běn jiā", "ipa": "tsɹ̩˥ pən˨˩˦ tɕja˥", "syllable_count": 3, "sentences": [{"text": "资本家想赚钱。", "target_word": "资本家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不是资本家。", "target_word": "资本家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "资本家雇了很多工人。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在老电影里，资本家常常很坏。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的资本家今天来了。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "资本家买下了这家工厂。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一百年前，这个城市有很多资本家。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "资本家出钱开工厂，工人出力气干活。", "target_word": "资本家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她读过一本书，写的是一位资本家的故事。", "target_word": "资本家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的资本家只想多赚钱，不关心工人过得好不好。", "target_word": "资本家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "資本家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "占有资本、雇用工人并获取利润的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会想赚钱，句意不通。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫没有赚钱的念头，“小猫想赚钱”不合常理。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不会想赚钱，句意不通。"}, {"text": "资本家", "is_correct": true, "explanation": "正确：这里指占有资本、想赚钱的人，与“想赚钱”搭配。"}], "explanations": {"桌子": "语义：桌子是家具，不会想赚钱，句意不通。", "小猫": "语义：小猫没有赚钱的念头，“小猫想赚钱”不合常理。", "月亮": "语义：月亮不会想赚钱，句意不通。", "资本家": "正确：这里指占有资本、想赚钱的人，与“想赚钱”搭配。"}, "sentence_index": 0, "correct_answer": "资本家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "资本家每天早上五点下地干活。", "explanation": "这里应该用〈农民〉。下地干活的是农民；资本家占有资本、雇人获利，不亲自从事农活。"}, {"text": "资本家每天早上五点在工地上搬砖。", "explanation": "这里应该用〈工人〉。搬砖的是工人；资本家指占有资本、雇用工人获利的人，不亲自做体力活。"}, {"text": "资本家每天在街角卖煎饼。", "explanation": "这里应该用〈小贩〉。沿街卖煎饼的是小贩；资本家不是街边小商贩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：一百年前还没有手机，句中的时间背景与“手机”不合。"}, {"text": "恐龙", "is_correct": false, "explanation": "语义：一百年前的城市里没有恐龙，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：一百年前还没有电脑，“有很多电脑”与句中时间不合。"}, {"text": "资本家", "is_correct": true, "explanation": "正确：一百年前的城市里，有很多占有资本、雇用工人的资本家。"}], "explanations": {"手机": "语义：一百年前还没有手机，句中的时间背景与“手机”不合。", "恐龙": "语义：一百年前的城市里没有恐龙，句意不通。", "电脑": "语义：一百年前还没有电脑，“有很多电脑”与句中时间不合。", "资本家": "正确：一百年前的城市里，有很多占有资本、雇用工人的资本家。"}, "sentence_index": 6, "correct_answer": "资本家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天来了一条资本家。", "explanation": "这里应该用〈位〉或〈个〉。“条”多用于细长的东西，指人的资本家不能用“条”。"}, {"text": "门口站着一只资本家。", "explanation": "这里应该用〈位〉或〈个〉。“只”多用于动物，指人的资本家不能用“只”。"}, {"text": "我认识一头资本家。", "explanation": "这里应该用〈位〉或〈个〉。“头”多用于牲畜，用来指人不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的邻居是一只资本家。", "corrected_sentence": "他的邻居是一位资本家。", "error_description": "量词错误：“资本家”指人，应用“位”或“个”，不能用“只”（“只”多用于动物）。正确说法是“一位资本家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前过当资本家。", "corrected_sentence": "他以前当过资本家。", "error_description": "位置错误：体标“过”应紧跟动词“当”之后，说“当过资本家”；不能放在动词前面，写成“过当资本家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92491, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
