INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92491, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "用在“为了……”之后，说明做某事的目的。", "primary_collocate": null, "pronunciation": "qǐ jiàn", "ipa": "tɕʰi˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "为了安全起见，请系好安全带。", "target_word": "起见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了方便起见，我们在门口见面。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了省事起见，我们叫外卖吧。", "target_word": "起见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保险起见，你再检查一遍。", "target_word": "起见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了公平起见，大家都抽签。", "target_word": "起见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了清楚起见，老师把题写在黑板上。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了健康起见，他不再抽烟了。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了节省时间起见，我们坐地铁去。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了准确起见，我又问了一次。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了稳妥起见，先给他打个电话。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "与“为了”搭配，说明做某事的目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92491, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "起见", "is_correct": true, "explanation": "正确答案。起见读作 qǐ jiàn，助词，用在“为了……”之后表示做事的目的。"}, {"text": "七件", "is_correct": false, "explanation": "qī（第一声）与 qǐ（第三声）声调不同，七件是数量短语，意思是七件物品。"}, {"text": "旗舰", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，旗舰意思是领头的大型船只或产品。"}, {"text": "器件", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，器件意思是机器的零件。"}, {"text": "起降", "is_correct": false, "explanation": "jiàng 与 jiàn 韵母不同（ang／an），起降意思是飞机起飞和降落。"}, {"text": "其间", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，其间意思是其中、期间。"}], "explanations": {"起见": "正确答案。起见读作 qǐ jiàn，助词，用在“为了……”之后表示做事的目的。", "七件": "qī（第一声）与 qǐ（第三声）声调不同，七件是数量短语，意思是七件物品。", "旗舰": "qí（第二声）与 qǐ（第三声）声调不同，旗舰意思是领头的大型船只或产品。", "器件": "qì（第四声）与 qǐ（第三声）声调不同，器件意思是机器的零件。", "起降": "jiàng 与 jiàn 韵母不同（ang／an），起降意思是飞机起飞和降落。", "其间": "qí（第二声）与 qǐ（第三声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，其间意思是其中、期间。"}, "sentence_index": null, "correct_answer": "起见"}, "level_3": {"options": [{"text": "起见", "is_correct": true, "explanation": "正确答案。“为了安全起见”表示做事是为了安全这一目的。"}, {"text": "来说", "is_correct": false, "explanation": "配价：“来说”要和“对／就”配合（对安全来说），不能直接接在“为了安全”之后。"}, {"text": "而已", "is_correct": false, "explanation": "语义：“而已”表示“仅此而已”，与“请系好安全带”这一提醒的语气不协调。"}, {"text": "而定", "is_correct": false, "explanation": "搭配：“而定”前面须有“视……”，说“为了安全而定”不成立。"}], "explanations": {"起见": "正确答案。“为了安全起见”表示做事是为了安全这一目的。", "来说": "配价：“来说”要和“对／就”配合（对安全来说），不能直接接在“为了安全”之后。", "而已": "语义：“而已”表示“仅此而已”，与“请系好安全带”这一提醒的语气不协调。", "而定": "搭配：“而定”前面须有“视……”，说“为了安全而定”不成立。"}, "sentence_index": 0, "correct_answer": "起见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了吃醋起见，他没有参加聚会。", "explanation": "这里不能用〈起见〉。〈起见〉表示为达到某个目的而主动去做，“吃醋”是心理反应，不是可以主动追求的目的，应说“因为吃醋，他没有参加聚会”。"}, {"text": "为了他已经回家起见，我们先去吃饭。", "explanation": "这里不能用〈起见〉。〈起见〉要接尚未实现、可以主动去做的目的，“已经回家”是既成事实，不能作为目的，应说“因为他已经回家，我们先去吃饭”。"}, {"text": "为了他昨天长高起见，我们让他多吃饭。", "explanation": "这里不能用〈起见〉。〈起见〉要接尚未实现、可以主动去做的目的，“昨天长高”是已经发生的事，不能作为目的，应说“为了让他长得更高，我们让他多吃饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起见", "is_correct": true, "explanation": "正确答案。“为了健康起见”表示戒烟是为了健康这一目的。"}, {"text": "而言", "is_correct": false, "explanation": "配价：“而言”要和“对／就”配合（对健康而言），不能直接接在“为了健康”之后。"}, {"text": "以来", "is_correct": false, "explanation": "语义：“以来”表示从某个时间点开始，不表示做事的目的，与“不再抽烟”的意图不符。"}, {"text": "所致", "is_correct": false, "explanation": "搭配：“所致”前面须是原因，说“为了健康所致”不成立。"}], "explanations": {"起见": "正确答案。“为了健康起见”表示戒烟是为了健康这一目的。", "而言": "配价：“而言”要和“对／就”配合（对健康而言），不能直接接在“为了健康”之后。", "以来": "语义：“以来”表示从某个时间点开始，不表示做事的目的，与“不再抽烟”的意图不符。", "所致": "搭配：“所致”前面须是原因，说“为了健康所致”不成立。"}, "sentence_index": 6, "correct_answer": "起见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了天气起见，我们明天去爬山。", "explanation": "这里不能用〈起见〉。〈起见〉表示为达到某个目的而主动去做，“天气”是外部条件，不能作为主动去做的目的；这里应该用〈根据〉，说“根据天气，我们明天去爬山”。"}, {"text": "为了他的哭泣起见，我们先去吃饭。", "explanation": "这里不能用〈起见〉。〈起见〉后面接的是人主动想达到的目的，“哭泣”是状态，不是可以去做的目的，应说“因为他在哭，我们先去吃饭”。"}, {"text": "为了他上个月考试没过起见，我们给他找了老师。", "explanation": "这里不能用〈起见〉。〈起见〉要接想要达到的目的，“考试没过”是已经发生的事，不能作为目的，应说“因为他上个月考试没过，我们给他找了老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了安全起见了，我们先回家。", "corrected_sentence": "为了安全起见，我们先回家。", "error_description": "“起见”是固定的目的标记，后面不能加“了”。正确的说法是“为了安全起见，我们先回家”，不能说“为了安全起见了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了省钱的起见，我们坐公交去。", "corrected_sentence": "为了省钱起见，我们坐公交去。", "error_description": "“起见”要直接跟在目的词语之后，中间不能加“的”。正确的说法是“为了省钱起见”，“省钱的起见”不是固定用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
