INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词性后缀，用在“为了……”之后，表示目的。", "primary_collocate": null, "pronunciation": "qǐ jiàn", "ipa": "tɕʰi˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "为了安全起见，孩子不能一个人出门。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了卫生起见，请不要用手拿。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了大家的方便起见，门开到十点。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保密起见，这件事别告诉别人。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了礼貌起见，他还是写了一封信。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了环保起见，商店不给塑料袋。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了孩子的学习起见，我们搬到学校旁边。", "target_word": "起见", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "为了准时起见，他六点就起床了。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了谨慎起见，我们再开一次会。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了好记起见，我把号码写在手上。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "后缀，放在“为了……”之后表示目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4df999a-4c7c-4b43-996e-aedee108069c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "起见", "is_correct": true, "explanation": "正确答案。起见读作 qǐ jiàn，后缀，放在“为了……”之后表示目的。"}, {"text": "七件", "is_correct": false, "explanation": "qī（第一声）与 qǐ（第三声）声调不同，七件是数量短语，意思是七件物品。"}, {"text": "旗舰", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，旗舰意思是领头的大型船只或产品。"}, {"text": "器件", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，器件意思是机器的零件。"}, {"text": "起降", "is_correct": false, "explanation": "jiàng 与 jiàn 韵母不同（ang／an），起降意思是飞机起飞和降落。"}, {"text": "其间", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，其间意思是其中、期间。"}], "explanations": {"起见": "正确答案。起见读作 qǐ jiàn，后缀，放在“为了……”之后表示目的。", "七件": "qī（第一声）与 qǐ（第三声）声调不同，七件是数量短语，意思是七件物品。", "旗舰": "qí（第二声）与 qǐ（第三声）声调不同，旗舰意思是领头的大型船只或产品。", "器件": "qì（第四声）与 qǐ（第三声）声调不同，器件意思是机器的零件。", "起降": "jiàng 与 jiàn 韵母不同（ang／an），起降意思是飞机起飞和降落。", "其间": "qí（第二声）与 qǐ（第三声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，其间意思是其中、期间。"}, "sentence_index": null, "correct_answer": "起见"}, "level_3": {"options": [{"text": "起见", "is_correct": true, "explanation": "正确答案。“为了安全起见”表示孩子不能单独出门是为了安全这一目的。"}, {"text": "来说", "is_correct": false, "explanation": "配价：“来说”要和“对／就”配合（对孩子来说），不能直接接在“为了安全”之后。"}, {"text": "而已", "is_correct": false, "explanation": "语义：“而已”表示“仅此而已”，与“孩子不能一个人出门”这一限制的语气不协调。"}, {"text": "而定", "is_correct": false, "explanation": "搭配：“而定”前面须有“视……”，说“为了安全而定”不成立。"}], "explanations": {"起见": "正确答案。“为了安全起见”表示孩子不能单独出门是为了安全这一目的。", "来说": "配价：“来说”要和“对／就”配合（对孩子来说），不能直接接在“为了安全”之后。", "而已": "语义：“而已”表示“仅此而已”，与“孩子不能一个人出门”这一限制的语气不协调。", "而定": "搭配：“而定”前面须有“视……”，说“为了安全而定”不成立。"}, "sentence_index": 0, "correct_answer": "起见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了他刚才的生气起见，我们没有说话。", "explanation": "这里不能用〈起见〉。〈起见〉要接尚未达到、可以主动去做的目的，“生气”是已经发生的情绪，不能作为目的，应说“因为他生气，我们没有说话”。"}, {"text": "为了昨天丢了钱包起见，他今天很不高兴。", "explanation": "这里不能用〈起见〉。〈起见〉要接想要达到的目的，“丢了钱包”是已经发生的事，是原因不是目的，应说“因为昨天丢了钱包，他今天很不高兴”。"}, {"text": "为了这个月已经瘦了五斤起见，我们一起跑步。", "explanation": "这里不能用〈起见〉。〈起见〉要接尚未实现、可以主动去做的目的，“已经瘦了五斤”是既成结果，不能作为目的，应说“为了继续减重，我们一起跑步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起见", "is_correct": true, "explanation": "正确答案。“为了孩子的学习起见”表示搬家是为了孩子的学习这一目的。"}, {"text": "而言", "is_correct": false, "explanation": "配价：“而言”要和“对／就”配合（对孩子的学习而言），不能直接接在“为了……”之后。"}, {"text": "以来", "is_correct": false, "explanation": "语义：“以来”表示从某个时间点开始，不表示做事的目的，与“搬到学校旁边”的意图不符。"}, {"text": "所致", "is_correct": false, "explanation": "搭配：“所致”前面须是原因，说“为了孩子的学习所致”不成立。"}], "explanations": {"起见": "正确答案。“为了孩子的学习起见”表示搬家是为了孩子的学习这一目的。", "而言": "配价：“而言”要和“对／就”配合（对孩子的学习而言），不能直接接在“为了……”之后。", "以来": "语义：“以来”表示从某个时间点开始，不表示做事的目的，与“搬到学校旁边”的意图不符。", "所致": "搭配：“所致”前面须是原因，说“为了孩子的学习所致”不成立。"}, "sentence_index": 6, "correct_answer": "起见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了下雨起见，我们明天去爬山。", "explanation": "这里不能用〈起见〉。〈起见〉表示为达到某个目的而主动去做，“下雨”是外部条件，不能作为主动去做的目的；这里应该用〈根据〉，说“根据天气，我们明天去爬山”。"}, {"text": "为了路上堵车起见，他迟到了。", "explanation": "这里不能用〈起见〉。〈起见〉要接主动想达到的目的，“堵车”是造成结果的原因，不是目的，应说“因为路上堵车，他迟到了”。"}, {"text": "为了她已经吃饱起见，我们让她多吃饭。", "explanation": "这里不能用〈起见〉。〈起见〉要接尚未实现、可以主动去做的目的，“已经吃饱”是既成事实，且与“让她多吃饭”的目的相矛盾，应说“她已经吃饱，不必再让她多吃饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了卫生起见了，大家先洗手。", "corrected_sentence": "为了卫生起见，大家先洗手。", "error_description": "“起见”是固定的目的标记，后面不能加“了”。正确的说法是“为了卫生起见，大家先洗手”，不能说“为了卫生起见了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了安静的起见，大家分开走。", "corrected_sentence": "为了安静起见，大家分开走。", "error_description": "“起见”前面不能加“的”，应直接跟在目的词语之后。正确的说法是“为了安静起见”，“安静的起见”不是固定用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69c045a6-9097-4962-a1dc-e57ea2afc512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92493, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解开", "is_correct": true, "explanation": "反义：“解开”是把系紧打的结松开，与“系带”的动作正相反。"}, {"text": "缝补", "is_correct": false, "explanation": "无反义关系：“缝补”指用针线修补破损处，与打结无关。"}, {"text": "挂起", "is_correct": false, "explanation": "无反义关系：“挂起”指悬挂，与系带的动作不构成反义。"}, {"text": "擦亮", "is_correct": false, "explanation": "无反义关系：“擦亮”指擦拭使其发光，与打结无关。"}], "correct_answer": "解开", "explanations": {"解开": "反义：“解开”是把系紧打的结松开，与“系带”的动作正相反。", "缝补": "无反义关系：“缝补”指用针线修补破损处，与打结无关。", "挂起": "无反义关系：“挂起”指悬挂，与系带的动作不构成反义。", "擦亮": "无反义关系：“擦亮”指擦拭使其发光，与打结无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92493, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解开", "is_correct": true, "explanation": "反义：“解开”是把系紧打的结松开，与“系带”的动作正相反。"}, {"text": "收拾", "is_correct": false, "explanation": "无反义关系：“收拾”指整理归置物品，与打结无关。"}, {"text": "叠好", "is_correct": false, "explanation": "无反义关系：“叠好”指把衣物折叠整齐，不是系带的反义。"}, {"text": "缠绕", "is_correct": false, "explanation": "无反义关系：“缠绕”指东西绕在一起，与系带是同类动作，不构成反义。"}], "correct_answer": "解开", "explanations": {"解开": "反义：“解开”是把系紧打的结松开，与“系带”的动作正相反。", "收拾": "无反义关系：“收拾”指整理归置物品，与打结无关。", "叠好": "无反义关系：“叠好”指把衣物折叠整齐，不是系带的反义。", "缠绕": "无反义关系：“缠绕”指东西绕在一起，与系带是同类动作，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92493, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把绳子或带子绑起来打结。", "primary_collocate": null, "pronunciation": "jì dài", "ipa": "tɕi˥˩ tai˥˩", "syllable_count": 2, "sentences": [{"text": "这件浴袍要在腰前系带。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教孩子怎么系带。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在包裹外面系带，别让它散开。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发扎好，再在帽子下面系带。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩的围裙要在背后系带。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶弯着腰，慢慢地系带。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "系带的时候，手不要太用力。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了半天才学会系带。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，帽子要系带才不会掉。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先系带，再背起书包出门。", "target_word": "系带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "系带子", "label": "复合"}, {"form": "系鞋带", "label": "复合"}, {"form": "繫帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把绳子或带子绑起来打结", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b076924c-de4b-472c-a356-ba993cc371b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92493, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌是发声的动作，浴袍在腰前不能用来唱歌。"}, {"text": "刷牙", "is_correct": false, "explanation": "语义：刷牙是清洁口腔的动作，不能在腰前进行。"}, {"text": "煮饭", "is_correct": false, "explanation": "搭配：“煮饭”的对象是米，不能说“在腰前煮饭”。"}, {"text": "系带", "is_correct": true, "explanation": "正确：“系带”指把带子系紧打结，与浴袍在腰前用带子系住相符。"}], "explanations": {"唱歌": "语义：唱歌是发声的动作，浴袍在腰前不能用来唱歌。", "刷牙": "语义：刷牙是清洁口腔的动作，不能在腰前进行。", "煮饭": "搭配：“煮饭”的对象是米，不能说“在腰前煮饭”。", "系带": "正确：“系带”指把带子系紧打结，与浴袍在腰前用带子系住相符。"}, "sentence_index": 0, "correct_answer": "系带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件风衣的系带很长。", "explanation": "这里的“系带”指名词“带子”，是另一义项的用法；本义项中的“系带”是动词，表示把绳子绑起来打结。"}, {"text": "妈妈把裙子的系带剪短了。", "explanation": "这里的“系带”指名词“带子”，是另一义项的用法；本义项中的“系带”是动词，表示把绳子绑起来打结。"}, {"text": "他的围裙系带断了，只好换一条。", "explanation": "这里的“系带”指名词“带子”，是另一义项的用法；本义项中的“系带”是动词，表示把绳子绑起来打结。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攥紧", "is_correct": false, "explanation": "语义：攥紧本身就要用力，与“手不要太用力”的要求相矛盾。"}, {"text": "猛拉", "is_correct": false, "explanation": "语义：猛拉需要用力，与“手不要太用力”的提醒矛盾。"}, {"text": "撕扯", "is_correct": false, "explanation": "语义：撕扯需要用力拉扯，与“手不要太用力”的提醒相矛盾。"}, {"text": "系带", "is_correct": true, "explanation": "正确：“系带”作主语，指系带的动作，后面的提醒指的是手不能太用力。"}], "explanations": {"攥紧": "语义：攥紧本身就要用力，与“手不要太用力”的要求相矛盾。", "猛拉": "语义：猛拉需要用力，与“手不要太用力”的提醒矛盾。", "撕扯": "语义：撕扯需要用力拉扯，与“手不要太用力”的提醒相矛盾。", "系带": "正确：“系带”作主语，指系带的动作，后面的提醒指的是手不能太用力。"}, "sentence_index": 6, "correct_answer": "系带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的书包系带断了，只好用手拎着。", "explanation": "这里的“系带”指名词“带子”，是另一义项的用法；本义项中的“系带”是动词，表示把绳子绑起来打结。"}, {"text": "帽子的系带被风吹得乱飞。", "explanation": "这里的“系带”指名词“带子”，是另一义项的用法；本义项中的“系带”是动词，表示把绳子绑起来打结。"}, {"text": "这件大衣的系带太长，拖到了地上。", "explanation": "这里的“系带”指名词“带子”，是另一义项的用法；本义项中的“系带”是动词，表示把绳子绑起来打结。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她弯腰很系带，动作很利落。", "corrected_sentence": "她弯腰系带，动作很利落。", "error_description": "错误形式“很系带”，正确形式“系带”。“很”是程度副词，不能修饰动词“系带”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她了系带以后，我们就出门了。", "corrected_sentence": "她系带以后，我们就出门了。", "error_description": "错误形式“了系带”，正确形式“系带”。“了”是完成标记，不能放在动词前面，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92495, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
