INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92495, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "软软的，没有硬骨头的身体。", "primary_collocate": null, "pronunciation": "ruǎn tǐ", "ipa": "ʐwan˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "蜗牛的软体躲在硬壳里。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "它的软体没有一根骨头。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛞蝓的软体一碰就缩起来。", "target_word": "软体", "complexity_tier": "T3", "furigana": "kuò yú de ruǎn tǐ yí pèng jiù suō qǐ lái.", "sentence_source": "generated"}, {"text": "章鱼的软体能钻进小洞。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "螺的软体藏在壳里。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海蜗牛露出软体，在石头上慢慢爬。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河蚌打开壳，里面是白色的软体。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乌贼受惊时，会把软体缩进去。", "target_word": "软体", "complexity_tier": "T3", "furigana": "wū zéi shòu jīng shí, huì bǎ ruǎn tǐ suō jìn qù.", "sentence_source": "generated"}, {"text": "海鸟把贝壳里的软体吃了。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "壳坏了，软体就露在外面了。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "软体动物", "label": "复合"}], "register": "中性", "sense_fingerprint": "指动物柔软、没有骨头的身体部分，常藏在硬壳里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 蛞 (Zipf 2.23)']::text[], 'e57226eb-7676-4c4b-9e91-9ee86200188c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92495, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "软体", "is_correct": true, "explanation": "正确：软体指动物体内柔软、没有骨骼的身体部分。"}, {"text": "软底", "is_correct": false, "explanation": "dǐ（第三声）与 tǐ（第三声）声母不同（d / t），意思是软底，指柔软的鞋底。"}, {"text": "软笔", "is_correct": false, "explanation": "bǐ（第三声）与 tǐ（第三声）声母不同（b / t），意思是软笔，指毛笔等软笔。"}, {"text": "软梯", "is_correct": false, "explanation": "tī（第一声）与 tǐ（第三声）声调不同，意思是软梯，指可以卷起来的绳梯。"}, {"text": "软尺", "is_correct": false, "explanation": "chǐ（第三声）与 tǐ（第三声）声母不同（ch / t），意思是软尺，指可以弯曲的卷尺。"}], "explanations": {"软体": "正确：软体指动物体内柔软、没有骨骼的身体部分。", "软底": "dǐ（第三声）与 tǐ（第三声）声母不同（d / t），意思是软底，指柔软的鞋底。", "软笔": "bǐ（第三声）与 tǐ（第三声）声母不同（b / t），意思是软笔，指毛笔等软笔。", "软梯": "tī（第一声）与 tǐ（第三声）声调不同，意思是软梯，指可以卷起来的绳梯。", "软尺": "chǐ（第三声）与 tǐ（第三声）声母不同（ch / t），意思是软尺，指可以弯曲的卷尺。"}, "sentence_index": null, "correct_answer": "软体"}, "level_3": {"options": [{"text": "软体", "is_correct": true, "explanation": "正确：软体指蜗牛柔软的身体部分，可以躲进硬壳里。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是身体部位，不能躲进硬壳里。"}, {"text": "叶子", "is_correct": false, "explanation": "语义：叶子是植物的部分，与蜗牛的身体无关，不能躲进硬壳。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：“影子”不能说躲在硬壳里，这里要说蜗牛的身体部分。"}], "explanations": {"软体": "正确：软体指蜗牛柔软的身体部分，可以躲进硬壳里。", "颜色": "语义：颜色不是身体部位，不能躲进硬壳里。", "叶子": "语义：叶子是植物的部分，与蜗牛的身体无关，不能躲进硬壳。", "影子": "搭配：“影子”不能说躲在硬壳里，这里要说蜗牛的身体部分。"}, "sentence_index": 0, "correct_answer": "软体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜗牛的软体很坚硬，背在身上。", "explanation": "这里应该用〈壳〉。软体是柔软的身体，坚硬的外壳不能叫软体。"}, {"text": "河边的软体很厚，踩上去陷得很深。", "explanation": "这里应该用〈软泥〉。软体指柔软无骨的身体，河边湿软的泥要说〈软泥〉，不能说软体。"}, {"text": "鸡的软体很脆，嚼起来很香。", "explanation": "这里应该用〈软骨〉。软体指没有骨骼的身体，鸡关节里嚼起来很脆的部分是软骨，不能叫软体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92495, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "软体", "is_correct": true, "explanation": "正确：这里指河蚌壳里柔软的身体部分，是白色的。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是金属零件，不会出现在河蚌壳里。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是写字用的文具，不会在河蚌壳里。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是穿戴的物品，与河蚌壳里的东西不符。"}], "explanations": {"软体": "正确：这里指河蚌壳里柔软的身体部分，是白色的。", "螺丝": "语义：螺丝是金属零件，不会出现在河蚌壳里。", "粉笔": "语义：粉笔是写字用的文具，不会在河蚌壳里。", "手套": "语义：手套是穿戴的物品，与河蚌壳里的东西不符。"}, "sentence_index": 6, "correct_answer": "软体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条软体很长，可以浇花。", "explanation": "这里应该用〈软管〉。软体指柔软无骨的身体，浇花用的橡胶管要说〈软管〉。"}, {"text": "蛇蜕下了一层软体。", "explanation": "这里应该用〈皮〉。软体指柔软的身体部分，蛇蜕下的是皮，不能说软体。"}, {"text": "西瓜的软体很甜，吃起来很爽口。", "explanation": "这里应该用〈果肉〉。软体指动物的身体，西瓜里柔软的部分叫果肉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92495, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "壳里藏着一本软体，一碰就缩了回去。", "corrected_sentence": "壳里藏着一团软体，一碰就缩了回去。", "error_description": "量词错误：“软体”指壳里柔软的身体，应用量词“团”，不能用“本”（“本”用于书本）。改为：一团软体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92495, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河蚌一受惊，就把一颗软体缩进壳里。", "corrected_sentence": "河蚌一受惊，就把一团软体缩进壳里。", "error_description": "量词错误：“软体”应用量词“团”，不能用“颗”（“颗”用于圆粒状的东西）。改为：一团软体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
