INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把礼物赠给别人，表示心意。", "primary_collocate": null, "pronunciation": "sòng rén", "ipa": "sʊŋ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "过年的时候，这盒茶叶是用来送人的。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很大方，常常买礼物送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手工皂很漂亮，自己用或者送人都好。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中秋节快到了，我想买些月饼送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶酒不便宜，我打算留着送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢自己做小礼物送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友过生日，我想买一本书送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些明信片是我旅行时买的，准备回家送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷种的橘子又大又甜，常常拿来送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前，我买了很多小礼物送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送了人", "label": "体标"}, {"form": "送过人", "label": "体标"}, {"form": "送人情", "label": "复合"}], "register": "口语", "sense_fingerprint": "把礼物或特产赠给别人表示心意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b189c5-928f-4b14-9e03-b75e919a5733') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92502, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "送人", "is_correct": true, "explanation": "正确答案。送人（sòng rén）意思是把礼物赠给别人。"}, {"text": "松仁", "is_correct": false, "explanation": "sōng（第一声）与 sòng（第四声）声调不同，意思是松子的果仁。"}, {"text": "众人", "is_correct": false, "explanation": "zhòng 与 sòng 声母不同，意思是许多人。"}, {"text": "动人", "is_correct": false, "explanation": "dòng 与 sòng 声母不同，意思是感人。"}], "explanations": {"送人": "正确答案。送人（sòng rén）意思是把礼物赠给别人。", "松仁": "sōng（第一声）与 sòng（第四声）声调不同，意思是松子的果仁。", "众人": "zhòng 与 sòng 声母不同，意思是许多人。", "动人": "dòng 与 sòng 声母不同，意思是感人。"}, "sentence_index": null, "correct_answer": "送人"}, "level_3": {"options": [{"text": "送人", "is_correct": true, "explanation": "正确。送人在此表示茶叶是用来赠给别人的。"}, {"text": "挂起", "is_correct": false, "explanation": "语义：茶叶不是用来挂的，与“用来……的”语境不合。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的对象是可燃物，茶叶不能用来点燃。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象不是茶叶，搭配不成立。"}], "explanations": {"送人": "正确。送人在此表示茶叶是用来赠给别人的。", "挂起": "语义：茶叶不是用来挂的，与“用来……的”语境不合。", "点燃": "搭配：“点燃”的对象是可燃物，茶叶不能用来点燃。", "洗": "搭配：“洗”的对象不是茶叶，搭配不成立。"}, "sentence_index": 0, "correct_answer": "送人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这几本书送人，每本收了一块钱。", "explanation": "这里应该用〈卖〉。送人是无偿给别人，收钱的交易要用卖。"}, {"text": "这台电脑我送人，每月收他的租金。", "explanation": "这里应该用〈出租〉。送人是无偿给别人，每月收租金要用出租。"}, {"text": "我把这本书送人，换了一双鞋回来。", "explanation": "这里应该用〈交换〉。送人是白白给出，拿东西换回要用交换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送人", "is_correct": true, "explanation": "正确。送人在此表示买书是为了赠给朋友。"}, {"text": "寄", "is_correct": false, "explanation": "配价：“寄”缺少收件对象，“我想买一本书寄”句子不完整。"}, {"text": "递交", "is_correct": false, "explanation": "语域：“递交”偏正式书面，口语里不这样说。"}, {"text": "交", "is_correct": false, "explanation": "配价：“交”缺少“交给谁”的成分，不能单独这样用。"}], "explanations": {"送人": "正确。送人在此表示买书是为了赠给朋友。", "寄": "配价：“寄”缺少收件对象，“我想买一本书寄”句子不完整。", "递交": "语域：“递交”偏正式书面，口语里不这样说。", "交": "配价：“交”缺少“交给谁”的成分，不能单独这样用。"}, "sentence_index": 6, "correct_answer": "送人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书我送人，但对方要求每月还我钱。", "explanation": "这里应该用〈借〉。送人是永久给出，每月还钱说明是借出，要用借。"}, {"text": "这件首饰我送人，从当铺换回了两百块钱。", "explanation": "这里应该用〈典当〉。送人是白白给出，押给当铺换钱要用典当。"}, {"text": "这把伞我送人，让他付了五十块钱。", "explanation": "这里应该用〈卖〉。送人是白白给出，收钱要用卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几套文具是我在国外买的，准备回来送过人。", "corrected_sentence": "这几套文具是我在国外买的，准备回来送人。", "error_description": "“准备”指以后的打算，不能用表示经历的“过”，应去掉“过”，说“准备回来送人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一些小礼物，想带回去送了人。", "corrected_sentence": "我买了一些小礼物，想带回去送人。", "error_description": "“想”表示打算，后面的“送人”还没有发生，不能加“了”，应去掉“了”，说“想带回去送人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2599719d-3706-449e-820c-06258b5064e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
