INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92503, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "联手是大家合在一起做同一件事。", "primary_collocate": null, "pronunciation": "lián shǒu", "ipa": "ljɛn˧˥ ʂoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们几个同学联手做了一份小报。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司联手推出了新手机。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居们联手把院子打扫得很干净。", "target_word": "联手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和姐姐联手给妈妈准备了生日礼物。", "target_word": "联手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家联手做饭，一个小时就做好了。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们联手完成了老师给的作业。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的人联手修了一条小路，走路方便多了。", "target_word": "联手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们联手布置教室，下午就弄好了。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三个朋友联手开了一家小咖啡店，生意很好。", "target_word": "联手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩联手做了一道菜，大家都说好吃。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "联手了", "label": "体标"}, {"form": "聯手", "label": "繁体"}], "register": "中性", "sense_fingerprint": "联手：几个人或几方合在一起做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92503, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "语义：“放弃做”与“做了一份小报”矛盾，不能用在这里"}, {"text": "联手", "is_correct": true, "explanation": "正确：几个同学合在一起做同一件事，正是“联手”的意思"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝做”与“做了一份小报”矛盾，不能用在这里"}, {"text": "单干", "is_correct": false, "explanation": "搭配：“单干”指一个人或一方独自干，不与“几个同学”搭配"}], "explanations": {"放弃": "语义：“放弃做”与“做了一份小报”矛盾，不能用在这里", "联手": "正确：几个同学合在一起做同一件事，正是“联手”的意思", "拒绝": "语义：“拒绝做”与“做了一份小报”矛盾，不能用在这里", "单干": "搭配：“单干”指一个人或一方独自干，不与“几个同学”搭配"}, "sentence_index": 0, "correct_answer": "联手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥联手了两岸。", "explanation": "这里应该用〈连接〉。联手要求人或多方一起行动，桥不能联手，应说“连接两岸”。"}, {"text": "他联手做完了一份报告。", "explanation": "这里应该用〈独自〉。联手要求两方或多人一起行动，一个人做报告不能说联手。"}, {"text": "我每周都和他联手，问问近况。", "explanation": "这里应该用〈联系〉。联手指共同做事，不指保持接触，问候近况要用联系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反对", "is_correct": false, "explanation": "语义：“反对修了一条小路”与“走路方便多了”矛盾，不能用在这里"}, {"text": "联手", "is_correct": true, "explanation": "正确：村里的人合在一起修路，所以走路方便了"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止修了一条小路”与“修了一条小路”矛盾"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：拆除针对已有的东西，不接“修了一条小路”，且拆路会让走路不便，与“方便多了”矛盾"}], "explanations": {"反对": "语义：“反对修了一条小路”与“走路方便多了”矛盾，不能用在这里", "联手": "正确：村里的人合在一起修路，所以走路方便了", "阻止": "语义：“阻止修了一条小路”与“修了一条小路”矛盾", "拆除": "搭配：拆除针对已有的东西，不接“修了一条小路”，且拆路会让走路不便，与“方便多了”矛盾"}, "sentence_index": 6, "correct_answer": "联手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先在家联手，学会了做菜。", "explanation": "这里应该用〈练手〉。练手指练习本领，联手指多人一起行动，两者不能互换。"}, {"text": "他联手做完了一道菜，没人帮忙。", "explanation": "这里应该用〈单干〉。联手要求多人一起做，“没人帮忙”说明只有一个人做，所以不能说联手。"}, {"text": "他联手做了一道菜，没让别人知道。", "explanation": "这里应该用〈偷偷〉。句中只有“他”一人，联手要求多人共同行动，独自暗中做应说“偷偷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们几个同学跟老师联手了做了一份小报。", "corrected_sentence": "我们几个同学跟老师联手做了一份小报。", "error_description": "错误在“了”的位置。“了”应放在动词“做”的后面，不能放在“联手”后面。正确形式是“跟老师联手做了一份小报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里的人把联手修完了一条小路，走路方便多了。", "corrected_sentence": "村里的人联手修完了一条小路，走路方便多了。", "error_description": "错误在“把”字句。“联手”是动词，不能放在“把”后面作宾语；去掉“把”，应说“村里的人联手修完了一条小路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
