INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92504, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "联合起来共同行动。", "primary_collocate": null, "pronunciation": "lián shǒu", "ipa": "ljɛn˧˥ ʂoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "两个国家联手应对这次大雨。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小动物们联手赶走了大老虎。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队和球迷联手，想赢下这场比赛。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几家商店联手降价，吸引了很多客人。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两位警察联手抓住了小偷。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们联手向学校提出了一个建议。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们联手对付对手，终于赢了比赛。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生和护士联手，把病人救了回来。", "target_word": "联手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想解决这个问题，我们必须联手行动。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国联手打击坏人，让街上安全了不少。", "target_word": "联手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "联手了", "label": "体标"}, {"form": "聯手", "label": "繁体"}], "register": "中性", "sense_fingerprint": "联手：联合起来共同行动，常用于应对、对付某事或某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忽视", "is_correct": false, "explanation": "语义：忽视就是不去理会，与“应对这次大雨”矛盾"}, {"text": "联手", "is_correct": true, "explanation": "正确：两个国家联合起来共同应对大雨"}, {"text": "逃避", "is_correct": false, "explanation": "语义：逃避就是躲开，与“应对这次大雨”矛盾"}, {"text": "躲避", "is_correct": false, "explanation": "搭配：“躲避”多搭配危险、责任，不说“躲避应对大雨”"}], "explanations": {"忽视": "语义：忽视就是不去理会，与“应对这次大雨”矛盾", "联手": "正确：两个国家联合起来共同应对大雨", "逃避": "语义：逃避就是躲开，与“应对这次大雨”矛盾", "躲避": "搭配：“躲避”多搭配危险、责任，不说“躲避应对大雨”"}, "sentence_index": 0, "correct_answer": "联手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两队互相攻击，却一直在联手。", "explanation": "这里应该用〈对抗〉。联手指双方合作，对抗指双方相互抵抗，两队互相攻击时不能说联手。"}, {"text": "他联手对付了小偷。", "explanation": "这里应该用〈独自〉。联手要求两方或多人一起行动，一个人对付小偷不能说联手。"}, {"text": "我每个星期都和他联手，给他打电话问候。", "explanation": "这里应该用〈联系〉。联手指共同行动，不指经常往来，打电话问候他应该用〈联系〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分散", "is_correct": false, "explanation": "语义：分散就是各自分开，与“联手对付对手”的合作意思矛盾"}, {"text": "联手", "is_correct": true, "explanation": "正确：他们合作对付对手，终于赢了比赛"}, {"text": "投降", "is_correct": false, "explanation": "语义：投降意味着认输，与“终于赢了比赛”矛盾"}, {"text": "退让", "is_correct": false, "explanation": "搭配：“退让”后接让步、妥协，不接“对付对手”"}], "explanations": {"分散": "语义：分散就是各自分开，与“联手对付对手”的合作意思矛盾", "联手": "正确：他们合作对付对手，终于赢了比赛", "投降": "语义：投降意味着认输，与“终于赢了比赛”矛盾", "退让": "搭配：“退让”后接让步、妥协，不接“对付对手”"}, "sentence_index": 6, "correct_answer": "联手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先在家联手，再去比赛。", "explanation": "这里应该用〈练手〉。练手指事先练习，不是联合行动对付他人，两者不能互换。"}, {"text": "他联手打败了坏人。", "explanation": "这里应该用〈单干〉。联手要求多方共同行动，一个人打败坏人不能说联手。"}, {"text": "他联手打击了坏人，没有人知道。", "explanation": "这里应该用〈偷偷〉。句中只有“他”一人，联手要求多方共同行动，独自暗中行动应说“偷偷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个国家跟邻国联手了应对这次大雨。", "corrected_sentence": "两个国家跟邻国联手应对这次大雨。", "error_description": "错误在“了”的位置。“联手”后面接动词“应对”时，“了”不能放在“联手”后面，去掉即可，正确形式是“跟邻国联手应对这次大雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国很联手打退了坏人，让街上安全了不少。", "corrected_sentence": "两国联手打退了坏人，让街上安全了不少。", "error_description": "错误在程度副词“很”。“联手”是动作动词，不能受“很”修饰；去掉“很”，正确形式是“两国联手打退了坏人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
