INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92505, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "选民是可以投票选人的人。", "primary_collocate": null, "pronunciation": "xuǎn mín", "ipa": "ɕɥɛn˨˩˦ min˧˥", "syllable_count": 2, "sentences": [{"text": "选民走进投票站，写下了候选人的名字。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每位选民都有一张选票。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天，很多选民早早来到学校投票。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位选民把票投给了年轻的候选人。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选民们排着长队等待投票。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一名老选民坐着轮椅来投票。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问了几位选民对新市长的看法。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选民需要带着身份证才能进去投票。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些选民还没有决定把票投给谁。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员告诉选民，投票站六点关门。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选民们", "label": "复数形式"}], "register": "中性", "sense_fingerprint": "名词，参加投票的人，强调投票这一行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a1638f-b64a-4caa-8649-66c87ab87a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选民", "is_correct": true, "explanation": "正确：选民是有投票权、去投票站投票的人，符合‘走进投票站，写下候选人的名字’的语境。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客不是去投票的人，与句中‘写下了候选人的名字’的语境矛盾。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客一般不会为投票而进入投票站，与‘写下了候选人的名字’不符。"}, {"text": "观众", "is_correct": false, "explanation": "搭配：‘观众’与‘投票站’‘写下候选人的名字’这类投票行为不搭配，观众不在投票站投票。"}], "explanations": {"选民": "正确：选民是有投票权、去投票站投票的人，符合‘走进投票站，写下候选人的名字’的语境。", "乘客": "语义：乘客不是去投票的人，与句中‘写下了候选人的名字’的语境矛盾。", "游客": "语义：游客一般不会为投票而进入投票站，与‘写下了候选人的名字’不符。", "观众": "搭配：‘观众’与‘投票站’‘写下候选人的名字’这类投票行为不搭配，观众不在投票站投票。"}, "sentence_index": 0, "correct_answer": "选民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位选民正在竞选市长。", "explanation": "这里应该用〈候选人〉。选民是去投票的人，竞选市长的应该说〈候选人〉。"}, {"text": "这位选民在比赛中获得了冠军。", "explanation": "这里应该用〈选手〉。选民指投票的人，比赛中获胜的人应该说〈选手〉。"}, {"text": "电影院里坐满了选民。", "explanation": "这里应该用〈观众〉。选民指有选举权、去投票的人，在电影院看电影的应该说〈观众〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选民", "is_correct": true, "explanation": "正确：选民是有投票权、对市长有看法的人，符合记者采访的语境。"}, {"text": "机器人", "is_correct": false, "explanation": "语义：机器人没有个人看法，与‘对新市长的看法’矛盾。"}, {"text": "外星人", "is_correct": false, "explanation": "语义：现实中外星人不会对本地市长有看法，与记者采访的语境冲突。"}, {"text": "幽灵", "is_correct": false, "explanation": "搭配：‘问……看法’要求能表达看法的人，‘幽灵’不与‘问看法’搭配。"}], "explanations": {"选民": "正确：选民是有投票权、对市长有看法的人，符合记者采访的语境。", "机器人": "语义：机器人没有个人看法，与‘对新市长的看法’矛盾。", "外星人": "语义：现实中外星人不会对本地市长有看法，与记者采访的语境冲突。", "幽灵": "搭配：‘问……看法’要求能表达看法的人，‘幽灵’不与‘问看法’搭配。"}, "sentence_index": 6, "correct_answer": "选民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公交车上坐满了选民。", "explanation": "这里应该用〈乘客〉。选民指有选举权、去投票的人，坐车的人应该说〈乘客〉。"}, {"text": "这辆出租车的选民熟悉这条路。", "explanation": "这里应该用〈司机〉。选民指投票的人，熟悉路线、开车的人应该说〈司机〉。"}, {"text": "舞台上的选民正在表演。", "explanation": "这里应该用〈演员〉。选民是投票的人，在舞台上表演的应该说〈演员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位选民们很关心教育问题。", "corrected_sentence": "这位选民很关心教育问题。", "error_description": "错误：‘选民们’加了复数后缀‘们’，与表示单个人的‘这位’不搭配。应为‘这位选民’，‘们’只用于没有数量词修饰的复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两选民在门口争论起来了。", "corrected_sentence": "两名选民在门口争论起来了。", "error_description": "错误：数词‘两’后面省略了量词。应为‘两名选民’，数词和名词之间要加量词‘名’。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
