INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有选举权、可以参加选举的公民。", "primary_collocate": null, "pronunciation": "xuǎn mín", "ipa": "ɕɥɛn˨˩˦ min˧˥", "syllable_count": 2, "sentences": [{"text": "年满十八岁的公民就是合法选民。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇一共有三千名选民。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选民名单已经贴在了社区门口。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬家以后，要重新登记为这里的选民。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有登记过的选民才能参加选举。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府希望更多年轻选民参加选举。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选民的人数比上次选举多了一万。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位候选人很受农村选民欢迎。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚满十八岁，成了新选民。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选民可以在网上查自己的投票地点。", "target_word": "选民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "选民们", "label": "复数形式"}], "register": "中性", "sense_fingerprint": "名词，具有选举权的公民，强调资格和身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a1638f-b64a-4caa-8649-66c87ab87a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选民", "is_correct": true, "explanation": "正确：选民指有选举权、可以参加选举的公民，符合‘合法’与‘年满十八岁’的语境。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：‘年满十八岁’说明已经成年，‘小孩’与之矛盾。"}, {"text": "外国人", "is_correct": false, "explanation": "语义：句中说的是公民，外国人不是本国公民，与‘公民’矛盾。"}, {"text": "老人", "is_correct": false, "explanation": "搭配：‘合法’一般不修饰‘老人’这类身份，此处不说‘合法老人’。"}], "explanations": {"选民": "正确：选民指有选举权、可以参加选举的公民，符合‘合法’与‘年满十八岁’的语境。", "小孩": "语义：‘年满十八岁’说明已经成年，‘小孩’与之矛盾。", "外国人": "语义：句中说的是公民，外国人不是本国公民，与‘公民’矛盾。", "老人": "搭配：‘合法’一般不修饰‘老人’这类身份，此处不说‘合法老人’。"}, "sentence_index": 0, "correct_answer": "选民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中是一名优秀选民。", "explanation": "这里应该用〈选手〉。选民指有选举权的公民，比赛中的优秀者应该说〈选手〉。"}, {"text": "超市里有很多选民在买东西。", "explanation": "这里应该用〈顾客〉。选民指有选举权的公民，在超市买东西的应该说〈顾客〉。"}, {"text": "这场演唱会有很多选民。", "explanation": "这里应该用〈观众〉。选民是有选举权的公民，参加演唱会的应该说〈观众〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选民", "is_correct": true, "explanation": "正确：选民是有选举权的公民，其人数可以与上次选举相比，符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生与选举无关，‘学生的人数比上次选举多了一万’不符合语境。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客不参加选举，与‘比上次选举多了一万’的比较矛盾。"}, {"text": "植物", "is_correct": false, "explanation": "搭配：‘人数’只用于计算人，不能说‘植物的人数’。"}], "explanations": {"选民": "正确：选民是有选举权的公民，其人数可以与上次选举相比，符合句意。", "学生": "语义：学生与选举无关，‘学生的人数比上次选举多了一万’不符合语境。", "游客": "语义：游客不参加选举，与‘比上次选举多了一万’的比较矛盾。", "植物": "搭配：‘人数’只用于计算人，不能说‘植物的人数’。"}, "sentence_index": 6, "correct_answer": "选民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里有三十名选民在上课。", "explanation": "这里应该用〈学生〉。选民指有选举权的公民，上课的人应该说〈学生〉。"}, {"text": "医院里有很多选民在给病人看病。", "explanation": "这里应该用〈医生〉。选民指有选举权的公民，给病人看病的应该说〈医生〉。"}, {"text": "厨房里的选民正在做饭。", "explanation": "这里应该用〈厨师〉。选民指有选举权的公民，在厨房做饭的应该说〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个社区有五千名选民们。", "corrected_sentence": "这个社区有五千名选民。", "error_description": "错误：数词加量词‘名’之后，‘选民’后面不能再加复数后缀‘们’。应为‘五千名选民’。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几选民来到了社区中心。", "corrected_sentence": "几位选民来到了社区中心。", "error_description": "错误：数词‘几’后面省略了量词。应为‘几位选民’，数词和名词之间要加量词‘位’，‘位’用于指人的名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de33d9ee-325c-469d-958a-5070d9ab7de1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
