INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92507, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "常常运动，让身体更有劲。", "primary_collocate": null, "pronunciation": "duàn liàn", "ipa": "tuan⁵¹ ljɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "爷爷每天早上都去公园锻炼。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想多锻炼，让身体更有劲。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每周锻炼三次，现在身体很好。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭以后，我们去河边锻炼一会儿。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他天天跑步锻炼，所以很少生病。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我应该多出去锻炼。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他锻炼了一个小时，出了很多汗。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在操场上锻炼身体。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以前不爱锻炼，现在每天都跑步。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想身体好，就要常常锻炼。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "锻炼了", "label": "体标（了）"}, {"form": "锻炼过", "label": "体标（过）"}, {"form": "锻炼着", "label": "体标（着）"}, {"form": "锻炼锻炼", "label": "重叠"}, {"form": "鍛煉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经常运动，使身体强壮有力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c571f81-6489-4741-8a61-f863fc462a95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92507, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "锻炼", "is_correct": true, "explanation": "正确：锻炼（duàn liàn），指经常运动，使身体更有劲。"}, {"text": "断电", "is_correct": false, "explanation": "diàn 与 liàn 声母不同，意思是停止供电。"}, {"text": "断线", "is_correct": false, "explanation": "xiàn 与 liàn 声母不同，意思是线路或联系中断。"}, {"text": "断裂", "is_correct": false, "explanation": "liè 与 liàn 韵母不同，意思是断开、破裂。"}, {"text": "断面", "is_correct": false, "explanation": "miàn 与 liàn 声母不同，意思是物体的横截面。"}], "explanations": {"锻炼": "正确：锻炼（duàn liàn），指经常运动，使身体更有劲。", "断电": "diàn 与 liàn 声母不同，意思是停止供电。", "断线": "xiàn 与 liàn 声母不同，意思是线路或联系中断。", "断裂": "liè 与 liàn 韵母不同，意思是断开、破裂。", "断面": "miàn 与 liàn 声母不同，意思是物体的横截面。"}, "sentence_index": null, "correct_answer": "锻炼"}, "level_3": {"options": [{"text": "锻炼", "is_correct": true, "explanation": "正确：“去公园锻炼”指去公园经常运动，符合“每天早上”的习惯。"}, {"text": "购物", "is_correct": false, "explanation": "语义：公园一般不是购物的场所，与“去公园”不相容。"}, {"text": "考试", "is_correct": false, "explanation": "语义：公园不是考试的场所，句子说的是日常活动。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡不在公园进行，与“去公园”不相容。"}], "explanations": {"锻炼": "正确：“去公园锻炼”指去公园经常运动，符合“每天早上”的习惯。", "购物": "语义：公园一般不是购物的场所，与“去公园”不相容。", "考试": "语义：公园不是考试的场所，句子说的是日常活动。", "洗澡": "语义：洗澡不在公园进行，与“去公园”不相容。"}, "sentence_index": 0, "correct_answer": "锻炼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天锻炼钢琴，手指越来越灵活。", "explanation": "这里应该用〈练习〉。学习乐器要用练习，锻炼只用于身体、意志或能力。"}, {"text": "工人锻炼了那台机器。", "explanation": "这里应该用〈修理〉。锻炼的对象是人的身体或能力，修理机器要用修理。"}, {"text": "他每天锻炼那只猫，猫学会了握手。", "explanation": "这里应该用〈训练〉。训练动物、教授技能要用训练，锻炼只用于人的身体、意志或能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锻炼", "is_correct": true, "explanation": "正确：“锻炼了一个小时”指身体活动了一段时间，所以会出很多汗。"}, {"text": "阅读", "is_correct": false, "explanation": "语义：阅读不需要身体用力，不会让人出很多汗。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：讨论主要用脑，与“出了很多汗”不相符。"}, {"text": "结束", "is_correct": false, "explanation": "配价：“结束”需要具体事件作宾语（如结束比赛），不能直接接“了一个小时”这类时段。"}], "explanations": {"锻炼": "正确：“锻炼了一个小时”指身体活动了一段时间，所以会出很多汗。", "阅读": "语义：阅读不需要身体用力，不会让人出很多汗。", "讨论": "语义：讨论主要用脑，与“出了很多汗”不相符。", "结束": "配价：“结束”需要具体事件作宾语（如结束比赛），不能直接接“了一个小时”这类时段。"}, "sentence_index": 6, "correct_answer": "锻炼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天锻炼厨房的地板，地板很快就干净了。", "explanation": "这里应该用〈擦〉。此句把“锻炼”用成了“擦洗、使…干净”的意思，但锻炼只用于人的身体、意志或能力，擦地板要用“擦”。"}, {"text": "老师每天锻炼教室里的黑板，黑板变得很亮。", "explanation": "这里应该用〈擦〉。此句把“锻炼”用成了“擦洗、使…干净”的意思，但锻炼只用于人的身体、意志或能力，擦黑板要用“擦”。"}, {"text": "他每天锻炼家里那张旧沙发，沙发越来越结实。", "explanation": "这里应该用〈加固〉。此句把“锻炼”用成了“使…变结实”的意思，但锻炼只用于人的身体、意志或能力，使家具变结实要用“加固”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天下午都在小区里很锻炼。", "corrected_sentence": "妈妈每天下午都在小区里锻炼。", "error_description": "错误：“很”修饰了动词“锻炼”。“很”一般修饰形容词，动词前应用“经常”“每天”等副词。正确说法：妈妈每天下午都在小区里锻炼。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我和朋友常去湖边的锻炼。", "corrected_sentence": "周末我和朋友常去湖边锻炼。", "error_description": "错误：“锻炼”前多加了“的”，使“去”后接的是名词短语“湖边的锻炼”。“去”后应接地点（湖边），再接动词“锻炼”。正确说法：周末我和朋友常去湖边锻炼。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
