INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92514, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "长度或时间达到（某个数量）。", "primary_collocate": null, "pronunciation": "cháng dá", "ipa": "ʈʂʰɑŋ˧˥ ta˧˥", "syllable_count": 2, "sentences": [{"text": "这条河长达三百公里。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议长达三个小时。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座桥长达两公里。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在国外学习长达五年。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛长达两个半小时。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这场雨长达一周。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那条路长达十公里。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的假期长达一个月。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部电影长达三小时。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "长城长达几千公里。", "target_word": "长达", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "長達", "label": "繁体"}], "register": "书面", "sense_fingerprint": "后接数量，说明长度或时间长到了这个数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad1d3580-2f81-4f34-89f3-d63ae05c6f1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长达", "is_correct": true, "explanation": "正确：长达说长度或时间达到某个数量，这里后接“三百公里”。"}, {"text": "重达", "is_correct": false, "explanation": "语义：“重达”说重量，河流描述的是长度，不能说重。"}, {"text": "持续", "is_correct": false, "explanation": "搭配：“持续”后接的是时间，不用来说河流的长度。"}, {"text": "宽达", "is_correct": false, "explanation": "语义：“宽达”说宽度，河流的长度不能说宽。"}], "explanations": {"长达": "正确：长达说长度或时间达到某个数量，这里后接“三百公里”。", "重达": "语义：“重达”说重量，河流描述的是长度，不能说重。", "持续": "搭配：“持续”后接的是时间，不用来说河流的长度。", "宽达": "语义：“宽达”说宽度，河流的长度不能说宽。"}, "sentence_index": 0, "correct_answer": "长达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试的成绩长达九十分。", "explanation": "这里应该用〈达到〉。长达说长度或时间的跨度，分数和成绩要用达到。"}, {"text": "他这一年长达了一米八。", "explanation": "这里应该用〈长到〉。长达用于长度或时间，人的身高要说长到。"}, {"text": "今年他的工资长达了三千块。", "explanation": "这里应该用〈增加〉。长达说长度或时间，钱数的变化要用增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长达", "is_correct": true, "explanation": "正确：长达说长度达到某个数量，这里后接“十公里”。"}, {"text": "高达", "is_correct": false, "explanation": "语义：“高达”说高度或数额，路的长度不能说高。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”要接能量、资源作宾语，不能跟“十公里”这样的长度搭配。"}, {"text": "抵达", "is_correct": false, "explanation": "搭配：“抵达”后接地点，不能跟“十公里”这样的长度搭配。"}], "explanations": {"长达": "正确：长达说长度达到某个数量，这里后接“十公里”。", "高达": "语义：“高达”说高度或数额，路的长度不能说高。", "消耗": "搭配：“消耗”要接能量、资源作宾语，不能跟“十公里”这样的长度搭配。", "抵达": "搭配：“抵达”后接地点，不能跟“十公里”这样的长度搭配。"}, "sentence_index": 6, "correct_answer": "长达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次涨价的幅度长达三成。", "explanation": "这里应该用〈高达〉。长达说长度或时间，涨幅的大小要用高达。"}, {"text": "这个班的学生长达三十人。", "explanation": "这里应该用〈有〉。长达只说长度和时间，人数要说有或共有。"}, {"text": "这头牛长达一吨。", "explanation": "这里应该用〈重达〉。长达说长度，牛的重量要说重达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段山路很长达八十多公里。", "corrected_sentence": "这段山路长达八十多公里。", "error_description": "错误在“很”。“长达”是动词，不能被程度副词“很”修饰。应去掉“很”，说“这段山路长达八十多公里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段河道被长达八公里。", "corrected_sentence": "这段河道长达八公里。", "error_description": "错误在“被”。“长达”是不及物动词，不能用被字句。应去掉“被”，说“这段河道长达八公里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c344b1a-6ec0-49b7-9dc7-d529462b5f32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
