INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92515, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "良心是心里分辨对错的感觉，做错事时会感到不安。", "primary_collocate": null, "pronunciation": "liáng xīn", "ipa": "liɑŋ³⁵ ɕin⁵⁵", "syllable_count": 2, "sentences": [{"text": "他说了谎，良心不安。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有良心，不会忘记你的帮助。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有良心的人，不会帮助别人。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的良心告诉她，不能拿别人的东西。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做错了事，良心一直过不去。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你摸着良心说，我对你好不好？", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老人很有良心，把钱还给了别人。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样对父母，不怕良心不安吗？", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子都有良心，知道什么是对错。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有良心，拿了钱就走了。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "良心企业", "label": "复合"}], "register": "中性", "sense_fingerprint": "良心：分辨对错的内心感觉，做错事会不安", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "语义：房间不会“不安”，“不安”要用于有心理活动的人。"}, {"text": "良心", "is_correct": true, "explanation": "正确：良心是心里知道对错的感觉，“良心不安”符合“说了谎”的语境。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车没有心理活动，不能“不安”。"}, {"text": "脑袋", "is_correct": false, "explanation": "语义：“脑袋”指头部，不指内心，不能说“脑袋不安”。"}], "explanations": {"房间": "语义：房间不会“不安”，“不安”要用于有心理活动的人。", "良心": "正确：良心是心里知道对错的感觉，“良心不安”符合“说了谎”的语境。", "汽车": "语义：汽车没有心理活动，不能“不安”。", "脑袋": "语义：“脑袋”指头部，不指内心，不能说“脑袋不安”。"}, "sentence_index": 0, "correct_answer": "良心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她有一张良心，不能拿别人的东西。", "explanation": "这里应该用〈颗〉。良心无形，“张”用于纸、桌子等平面的东西，不能用来计量良心。"}, {"text": "她有一台良心，不能拿别人的东西。", "explanation": "这里应该用〈颗〉。“台”用于机器、电器，良心不用“台”计量。"}, {"text": "今天我的良心很好，一直在笑。", "explanation": "这里应该用〈心情〉。良心指心里知道对错的感觉，表示高兴、难过等情绪要用“心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：“很有桌子”说不通，“有”后面要接抽象的品质。"}, {"text": "良心", "is_correct": true, "explanation": "正确：“很有良心”指这个人有良心，与后文“把钱还给了别人”的行为相符。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“很有脚印”不通，脚印不用“有”来形容人的品质。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人的品质，“很有汽车”不能说。"}], "explanations": {"桌子": "语义：“很有桌子”说不通，“有”后面要接抽象的品质。", "良心": "正确：“很有良心”指这个人有良心，与后文“把钱还给了别人”的行为相符。", "脚印": "搭配：“很有脚印”不通，脚印不用“有”来形容人的品质。", "汽车": "语义：汽车不是人的品质，“很有汽车”不能说。"}, "sentence_index": 6, "correct_answer": "良心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没有一根良心，拿了钱就走了。", "explanation": "这里应该用〈颗〉。“根”用于细长的东西，良心不能用“根”计量。"}, {"text": "他吃坏了东西，良心疼得厉害。", "explanation": "这里应该用〈肚子〉。良心指心里分辨对错的感觉，不是身体部位，不会“疼”。"}, {"text": "他的良心很聪明，数学考了满分。", "explanation": "这里应该用〈脑子〉。聪明、会算数说的是脑子，良心只管分辨对错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人有一只良心，从不乱收钱。", "corrected_sentence": "老人有一颗良心，从不乱收钱。", "error_description": "错误：量词“只”。良心是抽象的东西，应用“颗”。正确形式是“有一颗良心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小孩子都很良心，知道什么是对错。", "corrected_sentence": "小孩子都很有良心，知道什么是对错。", "error_description": "错误：“良心”是名词，不能直接受“很”修饰，应说“很有良心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
