INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92516, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92516, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "内心对是非善恶的正确认识和责任感。", "primary_collocate": null, "pronunciation": "liáng xīn", "ipa": "liɑŋ³⁵ ɕin⁵⁵", "syllable_count": 2, "sentences": [{"text": "做人要有良心。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了钱，昧着良心说了假话。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板没有良心，不给工人发工资。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的良心让他不能骗朋友。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做，对得起自己的良心吗？", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个医生很有良心，从不乱收费。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他夜里睡不着，良心一直不安。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要凭良心，不能骗人。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她捡到钱包，良心让她送回去了。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王良心很好，常帮助老人。", "target_word": "良心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "良心企业", "label": "复合"}], "register": "中性", "sense_fingerprint": "良心：内心对是非善恶的认识和责任感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人应具备的品质，“做人要有”后面不能接“汽车”。"}, {"text": "良心", "is_correct": true, "explanation": "正确：良心指内心对是非善恶的认识和责任感，“做人要有良心”是常见说法。"}, {"text": "黑心肠", "is_correct": false, "explanation": "语义：“黑心肠”是负面品质，与“做人要有”提出的正面要求相矛盾。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“有”后接“脚印”不通，脚印要说“留下”或“踩出”。"}], "explanations": {"汽车": "语义：汽车不是人应具备的品质，“做人要有”后面不能接“汽车”。", "良心": "正确：良心指内心对是非善恶的认识和责任感，“做人要有良心”是常见说法。", "黑心肠": "语义：“黑心肠”是负面品质，与“做人要有”提出的正面要求相矛盾。", "脚印": "搭配：“有”后接“脚印”不通，脚印要说“留下”或“踩出”。"}, "sentence_index": 0, "correct_answer": "良心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她有一张良心，所以不会骗朋友。", "explanation": "这里应该用〈颗〉。良心无形，量词用“颗”；“张”用于纸、桌子等平面的东西。"}, {"text": "他剧烈运动以后，良心跳得特别快。", "explanation": "这里应该用〈心脏〉。良心指内心对是非的判断，不指身体器官；说心跳要用“心脏”，应为“心脏跳得特别快”。"}, {"text": "他有一台良心，所以不会骗朋友。", "explanation": "这里应该用〈颗〉。“台”用于机器、电器，良心不能用“台”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会“不安”，“不安”只用于有心理活动的人。"}, {"text": "脑袋", "is_correct": false, "explanation": "搭配：“不安”说的是心理状态，“脑袋一直不安”不通。"}, {"text": "良心", "is_correct": true, "explanation": "正确：良心指内心对是非的认识，“良心不安”是固定说法，与“睡不着”的原因相符。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不会“不安”，与“睡不着”所说的内心状态无关。"}], "explanations": {"桌子": "语义：桌子不会“不安”，“不安”只用于有心理活动的人。", "脑袋": "搭配：“不安”说的是心理状态，“脑袋一直不安”不通。", "良心": "正确：良心指内心对是非的认识，“良心不安”是固定说法，与“睡不着”的原因相符。", "饭菜": "语义：饭菜不会“不安”，与“睡不着”所说的内心状态无关。"}, "sentence_index": 6, "correct_answer": "良心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小王有一根良心，常帮助老人。", "explanation": "这里应该用〈颗〉。“根”用于细长的东西，良心无形，不能用“根”计量。"}, {"text": "小王的良心很聪明，数学考了满分。", "explanation": "这里应该用〈脑子〉。聪明说的是脑子，良心指对是非善恶的认识。"}, {"text": "小王的良心很高，有一米九。", "explanation": "这里应该用〈个子〉。说身高要用“个子”，良心没有高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一只良心，从不骗人。", "corrected_sentence": "她有一颗良心，从不骗人。", "error_description": "错误：量词“只”。“只”用于动物或成对的东西，良心无形，应用“颗”。正确形式是“有一颗良心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个司机很良心，从不多收钱。", "corrected_sentence": "这个司机很有良心，从不多收钱。", "error_description": "错误：“良心”是名词，不能直接受“很”修饰，应说“很有良心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
