INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92517, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "镇压是用很大的力量，不让别人反抗。", "primary_collocate": null, "pronunciation": "zhèn yā", "ipa": "ʈʂən˥˩ ja˥", "syllable_count": 2, "sentences": [{"text": "国家不应该镇压和平的游行。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用警棍镇压了抗议的学生。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝派大臣去镇压各地的反抗。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政府一直在镇压反对的声音。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队把村里的反抗镇压了。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越镇压，人们的反抗就越强烈。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想镇压示威的人群，可是人太多了。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地警察镇压了这次小规模的骚乱。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "独裁者常常镇压不同意见的人。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民不怕军队来镇压他们。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "镇压了", "label": "体标"}, {"form": "镇压过", "label": "体标"}], "register": "书面", "sense_fingerprint": "用强大力量不让人反抗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "镇压", "is_correct": true, "explanation": "“镇压”表示用强力不让人反抗，与“不应该”构成对国家行为的否定。"}, {"text": "抵达", "is_correct": false, "explanation": "配价：“抵达”要求地点作宾语，不能接“游行”这样的活动。"}, {"text": "丈量", "is_correct": false, "explanation": "搭配：“丈量”的对象是长度或土地，不能用于游行。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”的对象是有形的物体，不能说“扛游行”。"}], "explanations": {"镇压": "“镇压”表示用强力不让人反抗，与“不应该”构成对国家行为的否定。", "抵达": "配价：“抵达”要求地点作宾语，不能接“游行”这样的活动。", "丈量": "搭配：“丈量”的对象是长度或土地，不能用于游行。", "扛": "搭配：“扛”的对象是有形的物体，不能说“扛游行”。"}, "sentence_index": 0, "correct_answer": "镇压"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位店主热情镇压了远道而来的客人。", "explanation": "这里应该用〈接待〉。镇压是用力量压制反抗，不用于对客人的热情招待。"}, {"text": "父母一直镇压生病的孩子。", "explanation": "这里应该用〈照顾〉。镇压是对反抗者的强力压制，不用于照料病人。"}, {"text": "志愿者镇压受伤的动物。", "explanation": "这里应该用〈救助〉。镇压的对象是反抗的人或群体，不用于受伤的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镇压", "is_correct": true, "explanation": "“镇压”表示用强力压制示威，与“人太多了”的困难语境相符。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是建筑或设施，不能用于人群。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能用来指示威的人群。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”表示亲近，与示威人群对立的情境不合。"}], "explanations": {"镇压": "“镇压”表示用强力压制示威，与“人太多了”的困难语境相符。", "修建": "搭配：“修建”的对象是建筑或设施，不能用于人群。", "参观": "搭配：“参观”的对象是场所或展览，不能用来指示威的人群。", "拥抱": "语义：“拥抱”表示亲近，与示威人群对立的情境不合。"}, "sentence_index": 6, "correct_answer": "镇压"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那场大雨镇压了整个城市。", "explanation": "这里应该用〈淹没〉。镇压是用力量压制反抗，不用于大雨覆盖城市这类自然现象。"}, {"text": "教练镇压了比赛的节奏。", "explanation": "这里应该用〈掌控〉。镇压是用力量压制反抗的人，不用于控制比赛的节奏。"}, {"text": "他一直想镇压这道数学题。", "explanation": "这里应该用〈攻克〉。镇压是对反抗者的强力压制，不用于解决难题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当局很快镇压了住那场罢工。", "corrected_sentence": "当局很快镇压住了那场罢工。", "error_description": "“住”是结果补语，应紧跟在动词后面，写成“镇压住了”，不能写成“镇压了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府想镇压了这场大规模的示威。", "corrected_sentence": "政府想镇压这场大规模的示威。", "error_description": "“想”表示打算，后面的动词不能带“了”。应去掉“镇压”后的“了”，正确形式为“政府想镇压这场大规模的示威”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
