INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92518, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用武力压制、制止反抗或叛乱。", "primary_collocate": null, "pronunciation": "zhèn yā", "ipa": "ʈʂən˥˩ ja˥", "syllable_count": 2, "sentences": [{"text": "政府派军队镇压了这次叛乱。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队很快就镇压了农民起义。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王下令镇压反抗的人民。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵用武力镇压了城里的暴动。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场叛乱很快就镇压下去了。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年朝廷出兵镇压起义军。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用枪炮镇压老百姓的反抗。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，这个王朝多次镇压农民起义。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军带兵去镇压边境的叛乱。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朝廷派大军镇压造反的地方官。", "target_word": "镇压", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "镇压了", "label": "体标"}, {"form": "镇压过", "label": "体标"}], "register": "书面", "sense_fingerprint": "用武力压制叛乱或起义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "镇压", "is_correct": true, "explanation": "“镇压”指用武力压制叛乱，与“派军队”搭配，句意通顺。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象是食物或饮料，不能说“品尝叛乱”。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的宾语是地方或展览，不能说“参观叛乱”。"}, {"text": "宣传", "is_correct": false, "explanation": "搭配：“宣传”的宾语是观点或主张，不能用于派军队这样的行动。"}], "explanations": {"镇压": "“镇压”指用武力压制叛乱，与“派军队”搭配，句意通顺。", "品尝": "搭配：“品尝”的对象是食物或饮料，不能说“品尝叛乱”。", "参观": "搭配：“参观”的宾语是地方或展览，不能说“参观叛乱”。", "宣传": "搭配：“宣传”的宾语是观点或主张，不能用于派军队这样的行动。"}, "sentence_index": 0, "correct_answer": "镇压"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，他很快镇压了内心的慌张。", "explanation": "这里应该用〈平复〉。镇压指用武力压制反抗或叛乱，不用于人内心的情绪。"}, {"text": "护士每天都耐心镇压病人。", "explanation": "这里应该用〈护理〉。镇压是用武力压制反抗或叛乱，不用于照料病人。"}, {"text": "政府正在努力镇压环境污染。", "explanation": "这里应该用〈治理〉。镇压的对象是反抗或叛乱的人，不能用来说污染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镇压", "is_correct": true, "explanation": "“镇压”指用武力制止反抗，与“用枪炮”搭配，句意通顺。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与用枪炮压制反抗的意思相反。"}, {"text": "理解", "is_correct": false, "explanation": "搭配：“理解”的对象是想法或处境，不能用枪炮去理解。"}, {"text": "询问", "is_correct": false, "explanation": "搭配：“询问”的对象是问题或情况，不能用枪炮去询问反抗。"}], "explanations": {"镇压": "“镇压”指用武力制止反抗，与“用枪炮”搭配，句意通顺。", "赞美": "语义：“赞美”表示称赞，与用枪炮压制反抗的意思相反。", "理解": "搭配：“理解”的对象是想法或处境，不能用枪炮去理解。", "询问": "搭配：“询问”的对象是问题或情况，不能用枪炮去询问反抗。"}, "sentence_index": 6, "correct_answer": "镇压"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府派军队镇压了这场大雪。", "explanation": "这里应该用〈清除〉。镇压是用武力压制人为的反抗，不能用于大雪这类自然现象。"}, {"text": "裁判很快镇压了这场足球比赛的胜负。", "explanation": "这里应该用〈决定〉。镇压是用武力压制反抗，不能用于比赛的胜负。"}, {"text": "这台机器很快就镇压了全部的数据。", "explanation": "这里应该用〈删除〉。镇压是用武力压制人为的反抗，不能用于机器处理数据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当时军队镇压了了这次起义。", "corrected_sentence": "当时军队镇压了这次起义。", "error_description": "“了”重复。“镇压”后只需一个“了”，正确形式为“当时军队镇压了这次起义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们想用强力镇压了工人的罢工。", "corrected_sentence": "他们想用强力镇压工人的罢工。", "error_description": "“想”表示打算，后面的动词不能带“了”。正确形式为“想用强力镇压工人的罢工”，应去掉“镇压”后的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
