INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92519, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人看得到。", "primary_collocate": null, "pronunciation": "lù", "ipa": "lu˥˩", "syllable_count": 1, "sentences": [{"text": "他一笑，就露出一口白牙。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗对着陌生人露出了牙齿。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有露出一点儿不高兴。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不露出害怕的神情。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师笑着露出了高兴的样子。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在门后露出半个头。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他卷起袖子，露出手臂上的伤。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对我露出了笑脸。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别在老板面前露出累的样子。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫生气了，对我露出了尖尖的牙。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "露了", "label": "体标"}, {"form": "露着", "label": "体标"}, {"form": "露出", "label": "复合"}], "register": "中性", "sense_fingerprint": "有意或无意地把身体部分、表情、想法让人看见（施动者露出）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a97372-e185-4f36-8342-f0d88b211b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92519, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "露", "is_correct": true, "explanation": "正确：露（lù），指让别人看得到。"}, {"text": "炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是炉子。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 lù 声母不同（n 对 l），意思是愤怒。"}, {"text": "卤", "is_correct": false, "explanation": "lǔ（第三声）与 lù（第四声）声调不同，意思是卤汁。"}], "explanations": {"露": "正确：露（lù），指让别人看得到。", "炉": "lú（第二声）与 lù（第四声）声调不同，意思是炉子。", "怒": "nù 与 lù 声母不同（n 对 l），意思是愤怒。", "卤": "lǔ（第三声）与 lù（第四声）声调不同，意思是卤汁。"}, "sentence_index": null, "correct_answer": "露"}, "level_3": {"options": [{"text": "露", "is_correct": true, "explanation": "正确：“露出”的“露”表示牙齿显现出来，与“一笑”相符。"}, {"text": "吐", "is_correct": false, "explanation": "语义：“吐”是把东西吐出来，与“一笑”不合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿夹住，与“一笑”的显露不合，不能说“咬出一口白牙”。"}, {"text": "拔", "is_correct": false, "explanation": "语义：“拔”是拉出，不是笑时显现出来。"}], "explanations": {"露": "正确：“露出”的“露”表示牙齿显现出来，与“一笑”相符。", "吐": "语义：“吐”是把东西吐出来，与“一笑”不合。", "咬": "语义：“咬”是用牙齿夹住，与“一笑”的显露不合，不能说“咬出一口白牙”。", "拔": "语义：“拔”是拉出，不是笑时显现出来。"}, "sentence_index": 0, "correct_answer": "露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电子表能露出现在的时间。", "explanation": "这里应该用〈显示〉。电子表显示时间要用显示，“露”指人的身体、神情或原本遮住的东西显现出来。"}, {"text": "这家公司在会议上露了一句感谢。", "explanation": "这里应该用〈致谢〉。“露”指显现身体、神情或原本遮住的东西，向人表达感谢应说致谢，不能用露。"}, {"text": "他在纸上露了一笔。", "explanation": "这里应该用〈画〉。“露”指显现出来，在纸上画一笔要用画，不能用露。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92519, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "露", "is_correct": true, "explanation": "正确：露（lù），指让别人看得到。"}, {"text": "芦", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇。"}, {"text": "颅", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是头颅。"}, {"text": "鲁", "is_correct": false, "explanation": "lǔ（第三声）与 lù（第四声）声调不同，意思是鲁（地名、姓氏）。"}, {"text": "卢", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是卢（姓氏）。"}], "explanations": {"露": "正确：露（lù），指让别人看得到。", "芦": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇。", "颅": "lú（第二声）与 lù（第四声）声调不同，意思是头颅。", "鲁": "lǔ（第三声）与 lù（第四声）声调不同，意思是鲁（地名、姓氏）。", "卢": "lú（第二声）与 lù（第四声）声调不同，意思是卢（姓氏）。"}, "sentence_index": null, "correct_answer": "露"}, "level_3": {"options": [{"text": "露", "is_correct": true, "explanation": "正确：“露出”的“露”表示手臂上的伤显现出来，与“卷起袖子”相符。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”用于悬挂物品，不说伤口挂出。"}, {"text": "戳", "is_correct": false, "explanation": "语义：“戳”是用尖物刺，与卷起袖子的动作不符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”是搬运东西，不能用于伤疤显现。"}], "explanations": {"露": "正确：“露出”的“露”表示手臂上的伤显现出来，与“卷起袖子”相符。", "挂": "搭配：“挂”用于悬挂物品，不说伤口挂出。", "戳": "语义：“戳”是用尖物刺，与卷起袖子的动作不符。", "搬": "语义：“搬”是搬运东西，不能用于伤疤显现。"}, "sentence_index": 6, "correct_answer": "露"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校露了考试成绩。", "explanation": "这里应该用〈公布〉。“露”指显现出来，公布考试成绩要用公布，不能用露。"}, {"text": "商店在门口露打折活动。", "explanation": "这里应该用〈宣传〉。“露”指显现出来，宣传打折活动要用宣传，不能用露。"}, {"text": "这家画廊露了很多油画。", "explanation": "这里应该用〈展览〉。“露”指显现身体、神情或原本遮住的东西，陈列作品应说展览。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小孩躲在门后，只露到半个脑袋。", "corrected_sentence": "小孩躲在门后，只露出半个脑袋。", "error_description": "补语用错：“露”与“出”组成趋向补语，表示显现出来，不能把“出”换成“到”，应说“露出半个脑袋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一笑，嘴角就露了出一丝得意。", "corrected_sentence": "她一笑，嘴角就露出了一丝得意。", "error_description": "“了”位置错误：“露出”是整体的动补结构，“了”应放在“露出”之后，说“露出了一丝得意”；“露了出”后直接接宾语不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
