INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92520, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "显现出来，不遮盖。", "primary_collocate": null, "pronunciation": "lù", "ipa": "lu˥˩", "syllable_count": 1, "sentences": [{"text": "他的脚趾露在鞋外面。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很浅，石头都露出来了。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳从云里露出来了。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的裤子破了，膝盖露着。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮了，东边露出一点白色。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪化了，地上露出了绿草。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被子太小，他的脚露在外面。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树林后面露出一座小房子。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包没拉好，里面的书露了出来。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水退了以后，河底露出了很多石头。", "target_word": "露", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "露了", "label": "体标"}, {"form": "露着", "label": "体标"}, {"form": "露出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物原本被遮住，现在显现出来（受事物露出来）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a97372-e185-4f36-8342-f0d88b211b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92520, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "露", "is_correct": true, "explanation": "正确：露（lù），指原本被遮住的东西显现出来。"}, {"text": "芦", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇。"}, {"text": "卤", "is_correct": false, "explanation": "lǔ（第三声）与 lù（第四声）声调不同，意思是卤汁。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 lù 声母不同（n 对 l），意思是愤怒。"}], "explanations": {"露": "正确：露（lù），指原本被遮住的东西显现出来。", "芦": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇。", "卤": "lǔ（第三声）与 lù（第四声）声调不同，意思是卤汁。", "怒": "nù 与 lù 声母不同（n 对 l），意思是愤怒。"}, "sentence_index": null, "correct_answer": "露"}, "level_3": {"options": [{"text": "露", "is_correct": true, "explanation": "正确：“露在鞋外面”的“露”表示脚趾显现在鞋外，与句意相符。"}, {"text": "藏", "is_correct": false, "explanation": "语义：“藏”是隐藏，与“在鞋外面”的显现意思相反。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，不能说脚趾扔在鞋外面。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”是穿戴，不能说脚趾穿在鞋外面。"}], "explanations": {"露": "正确：“露在鞋外面”的“露”表示脚趾显现在鞋外，与句意相符。", "藏": "语义：“藏”是隐藏，与“在鞋外面”的显现意思相反。", "扔": "语义：“扔”是丢弃，不能说脚趾扔在鞋外面。", "穿": "语义：“穿”是穿戴，不能说脚趾穿在鞋外面。"}, "sentence_index": 0, "correct_answer": "露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会议上露出了一句话。", "explanation": "这里应该用〈说出〉。“露出”指原本被遮住的东西显现出来，说话要用说出，不能用露出。"}, {"text": "老师在黑板上露了一道题。", "explanation": "这里应该用〈写〉。“露”指显现出来，在黑板上写题要用写，不能用露。"}, {"text": "他在课堂上露了一篇课文。", "explanation": "这里应该用〈朗读〉。“露”指显现出来，在课堂上读课文要用朗读，不能用露。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92520, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "露", "is_correct": true, "explanation": "正确：露（lù），指原本被遮住的东西显现出来。"}, {"text": "炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是炉子。"}, {"text": "颅", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是头颅。"}, {"text": "鲁", "is_correct": false, "explanation": "lǔ（第三声）与 lù（第四声）声调不同，意思是鲁（地名、姓氏）。"}, {"text": "卢", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是卢（姓氏）。"}], "explanations": {"露": "正确：露（lù），指原本被遮住的东西显现出来。", "炉": "lú（第二声）与 lù（第四声）声调不同，意思是炉子。", "颅": "lú（第二声）与 lù（第四声）声调不同，意思是头颅。", "鲁": "lǔ（第三声）与 lù（第四声）声调不同，意思是鲁（地名、姓氏）。", "卢": "lú（第二声）与 lù（第四声）声调不同，意思是卢（姓氏）。"}, "sentence_index": null, "correct_answer": "露"}, "level_3": {"options": [{"text": "露", "is_correct": true, "explanation": "正确：“露在外面”的“露”表示脚显现在被子外，与句意相符。"}, {"text": "缩", "is_correct": false, "explanation": "语义：“缩”是往回收，与“露在外面”的情形矛盾。"}, {"text": "涂", "is_correct": false, "explanation": "语义：“涂”是把东西抹在表面，不能说脚涂在外面。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，不能说脚扔在外面。"}], "explanations": {"露": "正确：“露在外面”的“露”表示脚显现在被子外，与句意相符。", "缩": "语义：“缩”是往回收，与“露在外面”的情形矛盾。", "涂": "语义：“涂”是把东西抹在表面，不能说脚涂在外面。", "扔": "语义：“扔”是丢弃，不能说脚扔在外面。"}, "sentence_index": 6, "correct_answer": "露"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家博物馆露了很多古老的瓷器。", "explanation": "这里应该用〈展览〉。“露”指显现出来，陈列展品应说展览。"}, {"text": "这家餐厅露了新菜单。", "explanation": "这里应该用〈推出〉。“露”指显现出来，推出新菜单要用推出，不能用露。"}, {"text": "春天到了，花园里露了很多花。", "explanation": "这里应该用〈开〉。“露”指显现出来，花开要用开，不能用露。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停以后，云缝里露了出一角蓝天。", "corrected_sentence": "雨停以后，云缝里露出了一角蓝天。", "error_description": "“了”位置错误：“露出”是整体的动补结构，“了”应放在“露出”之后，说“露出了一角蓝天”；“露了出”后直接接宾语不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他冷得发抖，手臂露袖子外面。", "corrected_sentence": "他冷得发抖，手臂露在袖子外面。", "error_description": "介词缺失：表示处所时，“露”后面要加“在”，应说“露在袖子外面”，不说“露袖子外面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
