INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92522, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "英制长度单位，一英里约合一千六百零九米。", "primary_collocate": null, "pronunciation": "yīng lǐ", "ipa": "iŋ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这条高速公路全长五十英里。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一英里大约等于一千六百米。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上跑三英里。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国的路牌常用英里表示距离。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里到机场还有十英里。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车每小时能开六十英里。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们走了两英里才找到水。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一英里比一公里长一些。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马拉松比赛大约有二十六英里。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖的长度只有半英里。", "target_word": "英里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方英里", "label": "复合"}], "register": "中性", "sense_fingerprint": "英制长度单位，约一千六百零九米", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62eac6f8-55d8-4516-a7c5-4d8181c28db1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92522, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "英里", "is_correct": true, "explanation": "正确答案：英里（yīng lǐ），英制长度单位。"}, {"text": "盈利", "is_correct": false, "explanation": "盈利（yíng lì）两个音节的声调都与英里不同（yíng、lì 对 yīng、lǐ），意思是赚钱。"}, {"text": "经理", "is_correct": false, "explanation": "经理（jīng lǐ）声母是 j，不是 y，意思是负责管理的人。"}, {"text": "清理", "is_correct": false, "explanation": "清理（qīng lǐ）声母是 q，不是 y，意思是清除、整理。"}], "explanations": {"英里": "正确答案：英里（yīng lǐ），英制长度单位。", "盈利": "盈利（yíng lì）两个音节的声调都与英里不同（yíng、lì 对 yīng、lǐ），意思是赚钱。", "经理": "经理（jīng lǐ）声母是 j，不是 y，意思是负责管理的人。", "清理": "清理（qīng lǐ）声母是 q，不是 y，意思是清除、整理。"}, "sentence_index": null, "correct_answer": "英里"}, "level_3": {"options": [{"text": "英里", "is_correct": true, "explanation": "正确：“全长”说的是长度，英里是长度单位，符合句意。"}, {"text": "吨", "is_correct": false, "explanation": "搭配：“吨”是重量单位，“全长”要用长度单位。"}, {"text": "亩", "is_correct": false, "explanation": "搭配：“亩”是面积单位，“全长”要用长度单位。"}, {"text": "斤", "is_correct": false, "explanation": "搭配：“斤”是重量单位，不能用来计量道路的长度。"}], "explanations": {"英里": "正确：“全长”说的是长度，英里是长度单位，符合句意。", "吨": "搭配：“吨”是重量单位，“全长”要用长度单位。", "亩": "搭配：“亩”是面积单位，“全长”要用长度单位。", "斤": "搭配：“斤”是重量单位，不能用来计量道路的长度。"}, "sentence_index": 0, "correct_answer": "英里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的客厅长二十英里。", "explanation": "这里应该用〈米〉。英里远远超过房间的长度，房间的长度一般用米来计量。"}, {"text": "这个操场跑一圈是四百英里。", "explanation": "这里应该用〈米〉。英里太长，操场跑一圈通常用米来计量。"}, {"text": "这张纸宽八英里。", "explanation": "这里应该用〈英寸〉。英里远远超过纸张的宽度，纸张的宽度要用英寸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92522, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "英里", "is_correct": true, "explanation": "正确答案：英里（yīng lǐ），英制长度单位。"}, {"text": "行礼", "is_correct": false, "explanation": "行礼（xíng lǐ）声母是 x，声调是第二声，与英里不同，意思是敬礼。"}, {"text": "赢利", "is_correct": false, "explanation": "赢利（yíng lì）两个音节的声调都与英里不同，意思是获得利润。"}, {"text": "应力", "is_correct": false, "explanation": "应力（yìng lì）声调与英里不同（yìng、lì 对 yīng、lǐ），是物理学用语。"}, {"text": "精力", "is_correct": false, "explanation": "精力（jīng lì）两个音节的声母和声调都与英里不同，意思是体力和精神。"}], "explanations": {"英里": "正确答案：英里（yīng lǐ），英制长度单位。", "行礼": "行礼（xíng lǐ）声母是 x，声调是第二声，与英里不同，意思是敬礼。", "赢利": "赢利（yíng lì）两个音节的声调都与英里不同，意思是获得利润。", "应力": "应力（yìng lì）声调与英里不同（yìng、lì 对 yīng、lǐ），是物理学用语。", "精力": "精力（jīng lì）两个音节的声母和声调都与英里不同，意思是体力和精神。"}, "sentence_index": null, "correct_answer": "英里"}, "level_3": {"options": [{"text": "英里", "is_correct": true, "explanation": "正确：“走了两英里”表示步行的路程，英里是长度单位，符合句意。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：公斤是重量单位，“走了”说的是路程，不能用重量来计量。"}, {"text": "升", "is_correct": false, "explanation": "搭配：“升”是容积单位，不能用来计量步行的距离。"}, {"text": "斗", "is_correct": false, "explanation": "搭配：“斗”是容量单位，走路的距离不能用斗来计量。"}], "explanations": {"英里": "正确：“走了两英里”表示步行的路程，英里是长度单位，符合句意。", "公斤": "语义：公斤是重量单位，“走了”说的是路程，不能用重量来计量。", "升": "搭配：“升”是容积单位，不能用来计量步行的距离。", "斗": "搭配：“斗”是容量单位，走路的距离不能用斗来计量。"}, "sentence_index": 6, "correct_answer": "英里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的铅笔长十八英里。", "explanation": "这里应该用〈厘米〉。铅笔很短，英里是很长的距离单位，物体的长度要用厘米。"}, {"text": "这袋大米重五英里。", "explanation": "这里应该用〈公斤〉。英里是长度单位，重量要用公斤。"}, {"text": "这块菜地有十英里。", "explanation": "这里应该用〈亩〉。英里量的是长度，土地的面积要用亩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天跑三张英里。", "corrected_sentence": "我们每天跑三英里。", "error_description": "错误：量词用了“张”。“张”用于平面物体，不能用来计量距离。正确：“三英里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "从车站到海边大约有两只英里。", "corrected_sentence": "从车站到海边大约有两英里。", "error_description": "错误：量词用了“只”。“只”用于个体动物或物件，不能用来计量距离。正确：“两英里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
