INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92523, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "点将是从很多人里，叫出某一个人来做事。", "primary_collocate": null, "pronunciation": "diǎn jiàng", "ipa": "tiɛn˨˩ tɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师在班里点将，叫小明来擦黑板。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈点将，让弟弟去买酱油。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，经理点将，让小刘说说想法。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长点将，让小王去守门。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动，主任点将请小陈来主持。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷点将，让我给客人倒茶。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长点将，让王同学代表学校发言。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板点将，请老周负责新店。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛要开始了，队长开始点将。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师只好点将，叫小红来回答。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点将台", "label": "复合词"}], "register": "中性", "sense_fingerprint": "从很多人里叫出某一个人来做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36673f00-f0bc-43d7-a615-18caeb0a4ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点将", "is_correct": true, "explanation": "正确：“点将”指从很多人里叫出一个人来做事，与“叫小明来擦黑板”相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能发生在班里，句子不通。"}, {"text": "赞扬", "is_correct": false, "explanation": "配价：“赞扬”后要带对象，这里缺宾语，“老师在班里赞扬”不完整。"}, {"text": "登陆", "is_correct": false, "explanation": "语义：“登陆”指船或飞机靠岸，老师不能在班里“登陆”。"}], "explanations": {"点将": "正确：“点将”指从很多人里叫出一个人来做事，与“叫小明来擦黑板”相符。", "下雨": "语义：“下雨”是天气现象，不能发生在班里，句子不通。", "赞扬": "配价：“赞扬”后要带对象，这里缺宾语，“老师在班里赞扬”不完整。", "登陆": "语义：“登陆”指船或飞机靠岸，老师不能在班里“登陆”。"}, "sentence_index": 0, "correct_answer": "点将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师上课点将，看看谁还没到。", "explanation": "这里应该用〈点名〉。点将指挑出一人做事，课堂上查人到没到要说点名。"}, {"text": "妈妈点将弟弟回家吃饭。", "explanation": "这里应该用〈叫〉。点将是从很多人里挑出一人做事，让人回家吃饭直接说叫。"}, {"text": "店员点将一瓶酱油给顾客。", "explanation": "这里应该用〈拿〉。点将只用于从很多人里叫出一人做事，拿酱油给顾客要说拿，不能用点将。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点将", "is_correct": true, "explanation": "正确：“点将”指从很多人里选出一个人做事，这里是校长选王同学代表学校发言，符合句意。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪等物体变成液体，校长不能“融化”，句子不通。"}, {"text": "赞美", "is_correct": false, "explanation": "配价：“赞美”后要有赞美的对象，这里缺宾语，句子不完整。"}, {"text": "发光", "is_correct": false, "explanation": "语义：“发光”用于物体或光源，不能指校长做事。"}], "explanations": {"点将": "正确：“点将”指从很多人里选出一个人做事，这里是校长选王同学代表学校发言，符合句意。", "融化": "语义：“融化”指冰雪等物体变成液体，校长不能“融化”，句子不通。", "赞美": "配价：“赞美”后要有赞美的对象，这里缺宾语，句子不完整。", "发光": "语义：“发光”用于物体或光源，不能指校长做事。"}, "sentence_index": 6, "correct_answer": "点将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长点将全班同学去操场。", "explanation": "这里应该用〈集合〉。点将是挑出个别人去做事，让全班同学聚到一起要说集合。"}, {"text": "我在超市点将一包饼干。", "explanation": "这里应该用〈买〉。点将只用于挑出一人做事，买饼干要说买，不能说点将。"}, {"text": "老师点将这节课的内容。", "explanation": "这里应该用〈讲〉。点将只用于挑人担任任务，讲授课程内容要说讲，不能用点将。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师点将的让小华来擦黑板。", "corrected_sentence": "老师点将让小华来擦黑板。", "error_description": "助词错误：“点将”后面不能直接加“的”，句子结构断开，无法成立。应说“老师点将让小华来擦黑板”，不能说“老师点将的让小华来擦黑板”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校长点将着让李同学代表学校发言。", "corrected_sentence": "校长点将让李同学代表学校发言。", "error_description": "体标错误：“着”不能加在“点将”后面，这里表示的是挑选这个动作，不应带“着”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
