INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92524, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "点名挑选人员担任某项任务；古时指点名派将领出战。", "primary_collocate": null, "pronunciation": "diǎn jiàng", "ipa": "tiɛn˨˩ tɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "经理点将，让小张去北京开会。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师点将，让小红当班长。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练点将，让三名新队员上场。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要做新项目，老板亲自点将。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长点将，让我第一个上场。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，大将军在城下点将出战。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很难，经理点将让老李来办。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长点将，请王老师带这个班。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演点将，请她演主角。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，教练点将，我们都很紧张。", "target_word": "点将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点将台", "label": "复合词"}], "register": "中性", "sense_fingerprint": "点名挑选人员担任任务；古时点名派将出战", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36673f00-f0bc-43d7-a615-18caeb0a4ccd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点将", "is_correct": true, "explanation": "正确：“点将”指点名挑选人员担任任务，与“让小张去北京开会”的语境相符。"}, {"text": "发光", "is_correct": false, "explanation": "语义：经理是人，“发光”只用于物体或光源，不能指经理做事。"}, {"text": "赞扬", "is_correct": false, "explanation": "配价：“赞扬”后面要带被赞扬的对象，这里缺宾语，句子不完整。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，经理不会“下雨”，与句中的人物不匹配。"}], "explanations": {"点将": "正确：“点将”指点名挑选人员担任任务，与“让小张去北京开会”的语境相符。", "发光": "语义：经理是人，“发光”只用于物体或光源，不能指经理做事。", "赞扬": "配价：“赞扬”后面要带被赞扬的对象，这里缺宾语，句子不完整。", "下雨": "语义：“下雨”是天气现象，经理不会“下雨”，与句中的人物不匹配。"}, "sentence_index": 0, "correct_answer": "点将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师上课点将，看看谁没来。", "explanation": "这里应该用〈点名〉。点将指挑选人员担任任务，课堂上查人到没到要说点名。"}, {"text": "我们在饭馆点将两个菜。", "explanation": "这里应该用〈点菜〉。点将指挑选人员去做任务，在饭馆点餐要说点菜。"}, {"text": "老板点将一台电脑去开会。", "explanation": "这里应该用〈挑选〉。点将只用于挑人担任任务，挑选电脑这类物品要说挑选，不能说点将。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点将", "is_correct": true, "explanation": "正确：“点将”指挑选人员担任任务，这里是经理挑老李来办这件事，符合句意。"}, {"text": "登陆", "is_correct": false, "explanation": "语义：“登陆”指船或飞机靠岸、人员上岸，经理不能“登陆”，句子不通。"}, {"text": "赞美", "is_correct": false, "explanation": "配价：“赞美”后面要有赞美的对象，这里缺宾语，“经理赞美”之后句子不完整。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”说的是冰雪等物体变成液体，不能用于经理。"}], "explanations": {"点将": "正确：“点将”指挑选人员担任任务，这里是经理挑老李来办这件事，符合句意。", "登陆": "语义：“登陆”指船或飞机靠岸、人员上岸，经理不能“登陆”，句子不通。", "赞美": "配价：“赞美”后面要有赞美的对象，这里缺宾语，“经理赞美”之后句子不完整。", "融化": "语义：“融化”说的是冰雪等物体变成液体，不能用于经理。"}, "sentence_index": 6, "correct_answer": "点将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经理点将大家去开会。", "explanation": "这里应该用〈召集〉。点将是从中挑出个别人担任任务，叫全体人员来开会要说召集。"}, {"text": "爸爸点将哥哥回家吃饭。", "explanation": "这里应该用〈叫〉。点将是挑人去做某件事，让人回家吃饭直接说叫。"}, {"text": "妈妈在市场点将新鲜的水果。", "explanation": "这里应该用〈挑选〉。挑水果要说挑选；点将挑的是人，它的对象不能是水果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理点将的让小李去上海出差。", "corrected_sentence": "经理点将让小李去上海出差。", "error_description": "助词错误：“点将”后面不能直接加“的”，句子结构断开，无法成立。应说“经理点将让小李去上海出差”，不能说“经理点将的让小李去上海出差”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事很难，经理点将着让小赵来办。", "corrected_sentence": "这件事很难，经理点将让小赵来办。", "error_description": "体标错误：“点将”后面不能加“着”，“着”不能附在这个动词上。应说“经理点将让小赵来办”，不能说“经理点将着让小赵来办”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b343d69-1e3d-4705-bbef-dfd8c9d5f3de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
