INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头的上面。", "primary_collocate": null, "pronunciation": "tóu shang", "ipa": "tʰou˧˥ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "头上有一盏明亮的灯。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我头上有一只蝴蝶。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书顶在头上走路。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手举到头上。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上的云在我们头上飘过。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把包放在头上。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫趴在爸爸头上睡觉。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "头上的树叶沙沙响。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把眼镜推到了头上。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们头上顶着书本跑。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "头上面", "label": "复合词"}], "register": "口语", "sense_fingerprint": "头的上面，指放在头顶或头顶之上的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "头上", "is_correct": true, "explanation": "正确：“头上”指头顶上方，灯可以在其上方，句子通顺。"}, {"text": "锅里", "is_correct": false, "explanation": "语义：灯不会在锅里，“锅里有一盏明亮的灯”说不通。"}, {"text": "鞋底", "is_correct": false, "explanation": "语义：灯放在鞋底不合常理，句子说不通。"}, {"text": "杯子里", "is_correct": false, "explanation": "语义：灯放在杯子里不合常理，“杯子里有一盏明亮的灯”说不通。"}], "explanations": {"头上": "正确：“头上”指头顶上方，灯可以在其上方，句子通顺。", "锅里": "语义：灯不会在锅里，“锅里有一盏明亮的灯”说不通。", "鞋底": "语义：灯放在鞋底不合常理，句子说不通。", "杯子里": "语义：灯放在杯子里不合常理，“杯子里有一盏明亮的灯”说不通。"}, "sentence_index": 0, "correct_answer": "头上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他头上拿着一本书。", "explanation": "这里应该用〈手上〉。拿的东西在手上，不在头上。"}, {"text": "小鱼在头上游来游去。", "explanation": "这里应该用〈水里〉。鱼在水里游，不在头上游。"}, {"text": "他头上喝了一杯水。", "explanation": "这里应该用〈嘴里〉。水是喝进嘴里的，不说头上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "头上", "is_correct": true, "explanation": "正确：“趴”可以接“头上”，小猫趴在头顶上睡觉合情合理。"}, {"text": "肚子里", "is_correct": false, "explanation": "语义：小猫不会趴在肚子里睡觉，句子说不通。"}, {"text": "嘴里", "is_correct": false, "explanation": "搭配：“趴”一般用于上面或身上，不说“趴在嘴里”。"}, {"text": "书里", "is_correct": false, "explanation": "语义：小猫不会在书里“趴着睡觉”，语境不合。"}], "explanations": {"头上": "正确：“趴”可以接“头上”，小猫趴在头顶上睡觉合情合理。", "肚子里": "语义：小猫不会趴在肚子里睡觉，句子说不通。", "嘴里": "搭配：“趴”一般用于上面或身上，不说“趴在嘴里”。", "书里": "语义：小猫不会在书里“趴着睡觉”，语境不合。"}, "sentence_index": 6, "correct_answer": "头上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在头上睡觉。", "explanation": "这里应该用〈床上〉。睡觉的地方是床上，不说头上。"}, {"text": "我头上闪过一个念头。", "explanation": "这里应该用〈脑子里〉。念头在脑子里闪过，不说“头上”。"}, {"text": "他头上标着一条路线。", "explanation": "这里应该用〈地图上〉。路线标在地图上，不标在头上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把帽子戴从头上。", "corrected_sentence": "他把帽子戴在头上。", "error_description": "错误：“戴从头上”，正确：“戴在头上”。帽子戴好后的位置在头的上面，要用“在头上”表示位置，不用“从”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹把篮子顶往头上。", "corrected_sentence": "妹妹把篮子顶在头上。", "error_description": "错误：“顶往头上”，正确：“顶在头上”。篮子停留的位置在头的上面，要用“在头上”，不用表示方向的“往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
