INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头的上方或头部表面。", "primary_collocate": null, "pronunciation": "tóu shang", "ipa": "tʰou˧˥ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "他头上戴着一顶红帽子。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一架飞机从我头上飞过去了。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她头上别着一朵白花。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈头上有几根白头发。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头上撞了一个大包。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点落在我头上。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳就在我们头上。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他头上裹着白布。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跳到了哥哥头上。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师头上落了一些雪。", "target_word": "头上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "头上面", "label": "复合词"}], "register": "口语", "sense_fingerprint": "头部的表面或头顶上方的空间，如头上戴着、头上飞过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "头上", "is_correct": true, "explanation": "正确：“戴帽子”的位置在头部，“头上”与“戴”搭配。"}, {"text": "手上", "is_correct": false, "explanation": "语义：帽子戴在头上，不会戴在手上。"}, {"text": "脸上", "is_correct": false, "explanation": "搭配：“戴帽子”的部位是头，脸上不能戴帽子。"}, {"text": "桌上", "is_correct": false, "explanation": "语义：桌子上不能戴帽子，“他桌上戴着帽子”说不通。"}], "explanations": {"头上": "正确：“戴帽子”的位置在头部，“头上”与“戴”搭配。", "手上": "语义：帽子戴在头上，不会戴在手上。", "脸上": "搭配：“戴帽子”的部位是头，脸上不能戴帽子。", "桌上": "语义：桌子上不能戴帽子，“他桌上戴着帽子”说不通。"}, "sentence_index": 0, "correct_answer": "头上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他头上穿着一件黑色外套。", "explanation": "这里应该用〈身上〉。穿衣服要说“身上”，不说“头上”。"}, {"text": "他头上带着笑容。", "explanation": "这里应该用〈脸上〉。笑容在脸上，不在头上。"}, {"text": "他头上很难过。", "explanation": "这里应该用〈心里〉。难过的心情在心里，不在头上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "头上", "is_correct": true, "explanation": "正确：太阳在头顶的上方，“就在我们头上”符合空间关系。"}, {"text": "河底", "is_correct": false, "explanation": "语义：太阳不会在河底，句子不符合常识。"}, {"text": "桌上", "is_correct": false, "explanation": "语义：太阳不会在桌子上，与“就在我们”的语境不合。"}, {"text": "嘴里", "is_correct": false, "explanation": "语义：太阳不会在嘴里，“太阳就在我们嘴里”说不通。"}], "explanations": {"头上": "正确：太阳在头顶的上方，“就在我们头上”符合空间关系。", "河底": "语义：太阳不会在河底，句子不符合常识。", "桌上": "语义：太阳不会在桌子上，与“就在我们”的语境不合。", "嘴里": "语义：太阳不会在嘴里，“太阳就在我们嘴里”说不通。"}, "sentence_index": 6, "correct_answer": "头上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她头上闪着泪光。", "explanation": "这里应该用〈眼里〉。泪光闪在眼睛里，不在头上。"}, {"text": "他头上答应了，但没做。", "explanation": "这里应该用〈嘴上〉。“嘴上答应”指口头应允，不能说“头上答应”。"}, {"text": "头上显示了结果。", "explanation": "这里应该用〈屏幕上〉。结果显示在屏幕上，不能说“头上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只鸟落了在我头上。", "corrected_sentence": "一只鸟落在了我头上。", "error_description": "错误：“落了在我头上”，正确：“落在了我头上”。“了”表示动作完成，要紧跟在“落在”之后，不能放在“在”的前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "阳光照我们头上。", "corrected_sentence": "阳光照在我们头上。", "error_description": "错误：“照我们头上”，正确：“照在我们头上”。表示处所的“在”不能省略，要放在动词“照”之后，引出处所“我们头上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
