INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92527, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "万物是世界上所有的东西。", "primary_collocate": null, "pronunciation": "wàn wù", "ipa": "wan˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "世界上的万物，我都想看一看。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子好奇地问：“万物是从哪里来的？”", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山、水、花、草，都是自然中的万物。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书用图画介绍世界上的万物。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪盖住了万物，外面一片白。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月光照在万物上，一切都很安静。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的清晨，万物都带着水珠。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们认识大自然中的万物。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱看天上的星星和地上的万物。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春风吹过，万物都换上了新的颜色。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "萬物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "世界上所有的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b076924c-de4b-472c-a356-ba993cc371b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万物", "is_correct": true, "explanation": "万物指世界上所有的东西，可以“想看一看”，与“世界上的”一致。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“看一看”针对可见的事物，不说“看一看歌曲”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是用耳朵听的，不能用“看”来形容。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是用舌头尝或用鼻子闻的，不能用“看”。"}], "explanations": {"万物": "万物指世界上所有的东西，可以“想看一看”，与“世界上的”一致。", "歌曲": "搭配：“看一看”针对可见的事物，不说“看一看歌曲”。", "声音": "语义：声音是用耳朵听的，不能用“看”来形容。", "味道": "语义：味道是用舌头尝或用鼻子闻的，不能用“看”。"}, "sentence_index": 0, "correct_answer": "万物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位科学家是我们最尊敬的万物。", "explanation": "这里应该用〈人物〉。“万物”指世界上的东西，不能用来指人。"}, {"text": "这座万物很高，远远就能看见。", "explanation": "这里应该用〈山〉。“座”修饰的是山，“万物”是总称，不能作一座山来数。"}, {"text": "这所万物有一千多名学生。", "explanation": "这里应该用〈学校〉。“万物”不指学校这类机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万物", "is_correct": true, "explanation": "万物指世界上所有的东西，与“雨后的清晨”描写的景象相符，可以“都带着水珠”。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想是抽象的，不会带着水珠。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法是抽象的规则，不能带着水珠。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的思维内容，不会“带着水珠”。"}], "explanations": {"万物": "万物指世界上所有的东西，与“雨后的清晨”描写的景象相符，可以“都带着水珠”。", "思想": "语义：思想是抽象的，不会带着水珠。", "语法": "语义：语法是抽象的规则，不能带着水珠。", "道理": "语义：道理是抽象的思维内容，不会“带着水珠”。"}, "sentence_index": 6, "correct_answer": "万物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把厨房里的万物都收拾好了。", "explanation": "这里应该用〈东西〉。“东西”指厨房里的具体物品，“万物”是宇宙间一切事物的总称，不指家里的物件。"}, {"text": "小猫在院子里追着万物跑。", "explanation": "这里应该用〈小动物〉。“万物”泛指宇宙间的一切事物，不指某一个具体的动物。"}, {"text": "公园里有一个很安静的万物。", "explanation": "这里应该用〈地方〉。“万物”不指地点，不能说“一个很安静的万物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要好好保护这个万物。", "corrected_sentence": "我们要好好保护万物。", "error_description": "错误形式“这个万物”，正确形式“万物”。“万物”是总称，前面不能加“这个”之类的指示词和量词，应删去“这个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "树叶落下来，都万物安静地等待冬天。", "corrected_sentence": "树叶落下来，万物安静地等待冬天。", "error_description": "副词“都”不能直接放在名词“万物”前面，此处多出的“都”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
