INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92528, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92528, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宇宙间一切事物。", "primary_collocate": null, "pronunciation": "wàn wù", "ipa": "wan˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "春天来了，万物都开始生长。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳给万物带来了光和热。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人认为，天地之间的万物都有生命。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人是万物中最会思考的一种。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水落下来，万物都变得干净了。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天一到，万物好像都睡着了。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢大自然，爱护世间的万物。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万物都在变化，没有什么不会变。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人觉得，万物都有自己的位置。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天过去了，万物慢慢安静下来。", "target_word": "万物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "萬物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "宇宙间的一切事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b076924c-de4b-472c-a356-ba993cc371b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万物", "is_correct": true, "explanation": "万物指宇宙间的一切事物，作“开始生长”的主语最自然，与“春天来了”的语境一致。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不会“开始生长”，与语境冲突。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”不是能生长的事物，“都开始生长”说不通。"}, {"text": "万事", "is_correct": false, "explanation": "搭配：“生长”多用于草木、生物，不说“万事都开始生长”。"}], "explanations": {"万物": "万物指宇宙间的一切事物，作“开始生长”的主语最自然，与“春天来了”的语境一致。", "石头": "语义：石头是无生命的物体，不会“开始生长”，与语境冲突。", "考试": "语义：“考试”不是能生长的事物，“都开始生长”说不通。", "万事": "搭配：“生长”多用于草木、生物，不说“万事都开始生长”。"}, "sentence_index": 0, "correct_answer": "万物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一件万物送给妈妈。", "explanation": "这里应该用〈礼物〉。“礼物”是可以买来送人的具体物品，“万物”是宇宙间一切事物的总称，不能当作可以买来送人的东西，也不能用〈件〉计数。"}, {"text": "他是我们学校最有名的万物。", "explanation": "这里应该用〈人物〉。“万物”指宇宙间的一切事物，不能用来指人。"}, {"text": "这家万物有一千多名员工。", "explanation": "这里应该用〈公司〉。“万物”不指组织或机构，不能表示“公司”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万物", "is_correct": true, "explanation": "万物泛指世间的一切事物，与“爱护”搭配，也与“大自然”的语境一致。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”不值得爱护，与“喜欢大自然”的语境冲突。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“噪音”是人们想要消除的对象，不说“爱护噪音”。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：“爱护”的对象不能是谎言，与“喜欢大自然”的语境冲突。"}], "explanations": {"万物": "万物泛指世间的一切事物，与“爱护”搭配，也与“大自然”的语境一致。", "垃圾": "语义：“垃圾”不值得爱护，与“喜欢大自然”的语境冲突。", "噪音": "语义：“噪音”是人们想要消除的对象，不说“爱护噪音”。", "谎言": "语义：“爱护”的对象不能是谎言，与“喜欢大自然”的语境冲突。"}, "sentence_index": 6, "correct_answer": "万物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种万物生活在深海里。", "explanation": "这里应该用〈生物〉。“万物”泛指宇宙间的一切事物，不指某一种有生命的个体。"}, {"text": "他把家里的万物都搬到了新房子里。", "explanation": "这里应该用〈东西〉。“东西”指家里的具体物品，“万物”是宇宙间一切事物的总称，不指家里的各种物件。"}, {"text": "我们去了一个很美丽的万物。", "explanation": "这里应该用〈地方〉。“地方”指可以去的场所，“万物”指宇宙间一切事物，不指地点，不能说“一个很美丽的万物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在万物的中，人类是最聪明的。", "corrected_sentence": "在万物中，人类是最聪明的。", "error_description": "错误：“万物的中”。正确：“万物中”，方位词“中”直接接在“万物”后面，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋天的田野里，一个万物都在忙着过冬。", "corrected_sentence": "秋天的田野里，万物都在忙着过冬。", "error_description": "“万物”是泛指一切事物的总称，不能用个体量词“个”来计数，应说“万物都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983d98b8-fa00-4d88-b880-58a3319faa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
