INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92530, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "轮流行事时排在自己前面的一方，如牌局中先出牌者；也指上一环节的供货方。", "primary_collocate": null, "pronunciation": "shàng jiā", "ipa": "ʂɑŋ˥˩ t͡ɕja˥", "syllable_count": 2, "sentences": [{"text": "玩牌时，上家出完牌，就轮到我了。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货有问题，我们要去找上家。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上家不发货，我们就没有东西卖。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的上家是一家大工厂。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上家晚送了三天货。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经和上家谈好了价钱。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要和上家、下家都搞好关系。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上家把货发过来了。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个价格是上家定的，我们不能改。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上家先发了货，我们才能接着发。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "轮流时排前面的一方；买卖中的供货方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '334d3bb3-d40f-4673-8ec2-5f77f12859af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92530, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上家", "is_correct": true, "explanation": "上家（shàng jiā）指轮流时排在自己前面的一方，或上一环节的供货方，是正确答案。"}, {"text": "商家", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是做买卖的人或店铺。"}, {"text": "上架", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是把商品放到货架上。"}, {"text": "上交", "is_correct": false, "explanation": "jiāo 与 jiā 韵母不同（多一个 o），意思是把东西交给上级或组织。"}], "explanations": {"上家": "上家（shàng jiā）指轮流时排在自己前面的一方，或上一环节的供货方，是正确答案。", "商家": "shāng（第一声）与 shàng（第四声）声调不同，意思是做买卖的人或店铺。", "上架": "jià（第四声）与 jiā（第一声）声调不同，意思是把商品放到货架上。", "上交": "jiāo 与 jiā 韵母不同（多一个 o），意思是把东西交给上级或组织。"}, "sentence_index": null, "correct_answer": "上家"}, "level_3": {"options": [{"text": "上家", "is_correct": true, "explanation": "上家指轮流时排在我前面的一方，此句指牌局中先出牌的人，与“玩牌时”和“出完牌”搭配，是正确答案。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不会出牌，“玩牌时，雨出完牌”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是玩牌的人，不能出牌。"}, {"text": "牌", "is_correct": false, "explanation": "配价：“出完牌”的施事必须是人，“牌”不能主动出牌。"}], "explanations": {"上家": "上家指轮流时排在我前面的一方，此句指牌局中先出牌的人，与“玩牌时”和“出完牌”搭配，是正确答案。", "雨": "语义：雨不会出牌，“玩牌时，雨出完牌”说不通。", "窗户": "语义：窗户不是玩牌的人，不能出牌。", "牌": "配价：“出完牌”的施事必须是人，“牌”不能主动出牌。"}, "sentence_index": 0, "correct_answer": "上家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的上家是一家大超市，经常来我们这里进货。", "explanation": "这里应该用〈下家〉。上家是给我们供货的一方，来这里进货的是下家；超市是买方。"}, {"text": "我们的新上家每天都来上班，工作很认真。", "explanation": "这里应该用〈同事〉。上家指上一环节的供货方，不是同一单位的同事；它不用来指同事或员工。"}, {"text": "我们的上家收到了货，然后付了钱。", "explanation": "这里应该用〈买家〉。收货、付款的是买方；上家是供货方，不会收货付款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上家", "is_correct": true, "explanation": "上家指排在我前面的一方，或上一环节的供货方，与“做生意”搭配，是正确答案。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“搞好关系”的对象须是人或单位，“天气”不能被“搞好关系”。"}, {"text": "锅", "is_correct": false, "explanation": "语义：锅不是买卖的参与方，“和锅搞好关系”说不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不参与生意，“和树、下家搞好关系”说不通。"}], "explanations": {"上家": "上家指排在我前面的一方，或上一环节的供货方，与“做生意”搭配，是正确答案。", "天气": "配价：“搞好关系”的对象须是人或单位，“天气”不能被“搞好关系”。", "锅": "语义：锅不是买卖的参与方，“和锅搞好关系”说不通。", "树": "语义：树不参与生意，“和树、下家搞好关系”说不通。"}, "sentence_index": 6, "correct_answer": "上家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位上家是我们的老客户，常来店里买东西。", "explanation": "这里应该用〈顾客〉。上家是供货方，给我们供货；来店里买东西的是顾客，不是上家。"}, {"text": "我们找到了一位新上家，他每天在办公室里发号施令。", "explanation": "这里应该用〈老板〉。上家指上一环节的供货方，不指管理者或上级领导。"}, {"text": "这家公司的上家每年都给我们分红，我们很满意。", "explanation": "这里应该用〈股东〉。分红是股东的权利；上家是供货方，不持有我们的股份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们换了一张新上家。", "corrected_sentence": "我们换了一个新上家。", "error_description": "量词错误：上家指人或单位，应该用“个”，不能用“张”（“张”用于纸、桌子等平面的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于找到了一只新上家，合作很顺利。", "corrected_sentence": "我们终于找到了一个新上家，合作很顺利。", "error_description": "量词错误：上家指人或单位，应该用“个”，不能用“只”（“只”多用于动物或成对物品中的一个）。正确说法是“我们终于找到了一个新上家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
