INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92531, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "老是来打扰别人，让人不舒服。", "primary_collocate": null, "pronunciation": "sāo rǎo", "ipa": "sau˥ ʐau˨˩˦", "syllable_count": 2, "sentences": [{"text": "他每天给她打电话，这是骚扰。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我老接到骚扰电话，很烦。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人总发短信骚扰她。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事一直骚扰她，她只好告诉经理。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人天天在门口骚扰我。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人骚扰你，要马上告诉老师。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骚扰电话太多了，我不接陌生号码。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他老是骚扰女同学，大家都不喜欢他。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她请警察帮忙，不让那个人再骚扰她。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司常发广告骚扰客户。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骚扰了", "label": "体标"}, {"form": "骚扰着", "label": "体标"}, {"form": "骚扰电话", "label": "复合"}], "register": "中性", "sense_fingerprint": "反复纠缠、打扰他人，令对方反感（如骚扰电话）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a97372-e185-4f36-8342-f0d88b211b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骚扰", "is_correct": true, "explanation": "骚扰：反复纠缠、打扰他人，令对方反感。每天打电话、不让对方安宁，正是骚扰。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是对某种行为的判断，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不能用来判断打电话这一行为的性质。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“这是”后要接对打电话这一行为的判断，“电话”只是工具，“他每天给她打电话，这是电话”句意不通。"}], "explanations": {"骚扰": "骚扰：反复纠缠、打扰他人，令对方反感。每天打电话、不让对方安宁，正是骚扰。", "天气": "语义：“天气”不是对某种行为的判断，句意不通。", "桌子": "语义：“桌子”不能用来判断打电话这一行为的性质。", "电话": "语义：“这是”后要接对打电话这一行为的判断，“电话”只是工具，“他每天给她打电话，这是电话”句意不通。"}, "sentence_index": 0, "correct_answer": "骚扰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该骚扰身边的老人。", "explanation": "这里应该用〈关心〉。骚扰是令人反感的纠缠，不能用于对人的关怀。"}, {"text": "请你骚扰大家明天开会。", "explanation": "这里应该用〈通知〉。骚扰不能表示告知，通知大家要说通知。"}, {"text": "警察要骚扰市民的安全。", "explanation": "这里应该用〈保护〉。骚扰表示纠缠、打扰，不能用于保障安全。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骚扰", "is_correct": true, "explanation": "骚扰：反复纠缠、打扰他人，令对方反感。“骚扰电话”指这类让人反感的来电。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“花朵电话”不是一种电话，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头电话”不指任何电话，且与“不接陌生号码”的语境无关。"}, {"text": "箱子", "is_correct": false, "explanation": "搭配：电话的修饰语应表示其性质或用途，“箱子”不能修饰“电话”。"}], "explanations": {"骚扰": "骚扰：反复纠缠、打扰他人，令对方反感。“骚扰电话”指这类让人反感的来电。", "花朵": "语义：“花朵电话”不是一种电话，句意不通。", "石头": "语义：“石头电话”不指任何电话，且与“不接陌生号码”的语境无关。", "箱子": "搭配：电话的修饰语应表示其性质或用途，“箱子”不能修饰“电话”。"}, "sentence_index": 6, "correct_answer": "骚扰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你骚扰我带钥匙。", "explanation": "这里应该用〈提醒〉。骚扰表示纠缠、打扰，不能表示提示对方做某事。"}, {"text": "我们都骚扰他考上了大学。", "explanation": "这里应该用〈恭喜〉。骚扰含有令人反感的意思，祝贺他人应说恭喜。"}, {"text": "节日里，大家用彩灯骚扰房间。", "explanation": "这里应该用〈装饰〉。骚扰指打扰他人、使人不安，用彩灯布置房间应说装饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个人天天骚扰得我，我很烦。", "corrected_sentence": "这个人天天骚扰我，我很烦。", "error_description": "补语结构错误：“得”引出的补语应说明程度，“骚扰得我”后缺少补语，应说“天天骚扰我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个男人经常把骚扰我，我很害怕。", "corrected_sentence": "那个男人经常骚扰我，我很害怕。", "error_description": "“把”用错：“骚扰”后直接接宾语，不需要“把”字结构，应为“经常骚扰我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
