INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打扰，使不安宁。", "primary_collocate": null, "pronunciation": "sāo rǎo", "ipa": "sau˥ ʐau˨˩˦", "syllable_count": 2, "sentences": [{"text": "半夜的汽车喇叭声骚扰着全楼的人。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "bàn yè de qì chē lǎ ba shēng sāo rǎo zhe quán lóu de rén", "sentence_source": "generated"}, {"text": "工地的机器声一早就骚扰了整条街。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "gōng dì de jī qì shēng yì zǎo jiù sāo rǎo le zhěng tiáo jiē", "sentence_source": "generated"}, {"text": "为了不骚扰别人，他把音乐关小了。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "wèi le bù sāo rǎo bié rén, tā bǎ yīn yuè guān xiǎo le", "sentence_source": "generated"}, {"text": "施工的声音骚扰着附近的居民。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深夜的敲门声骚扰着楼里的老人。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚊子在房间里骚扰我，我睡不好。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上别用音乐骚扰邻居。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的鞭炮声常常骚扰整个村子。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上的脚步声整夜骚扰着我。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "lóu shàng de jiǎo bù shēng zhěng yè sāo rǎo zhe wǒ", "sentence_source": "generated"}, {"text": "窗外的噪音骚扰着他。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骚扰了", "label": "体标"}, {"form": "骚扰着", "label": "体标"}, {"form": "骚扰过", "label": "体标"}], "register": "中性", "sense_fingerprint": "一般的打扰、干扰，使人或地方不得安宁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a97372-e185-4f36-8342-f0d88b211b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骚扰", "is_correct": true, "explanation": "骚扰：打扰，使人不安宁。喇叭声在半夜打扰了全楼的人。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：「照顾」的施事应是有意识的人，喇叭声不能照顾全楼的人。"}, {"text": "提高", "is_correct": false, "explanation": "配价：「提高」的宾语多为水平、质量等抽象事物，不能说提高全楼的人。"}, {"text": "监督", "is_correct": false, "explanation": "语义：喇叭声不能监督人，句中“半夜”的语境也与监督无关。"}], "explanations": {"骚扰": "骚扰：打扰，使人不安宁。喇叭声在半夜打扰了全楼的人。", "照顾": "语义：「照顾」的施事应是有意识的人，喇叭声不能照顾全楼的人。", "提高": "配价：「提高」的宾语多为水平、质量等抽象事物，不能说提高全楼的人。", "监督": "语义：喇叭声不能监督人，句中“半夜”的语境也与监督无关。"}, "sentence_index": 0, "correct_answer": "骚扰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "谢谢您的款待，我该走了，不再骚扰您了。", "explanation": "这里应该用〈打扰〉。告辞时的客气说法是打扰，骚扰含有反复纠缠、令人反感的意思，不能用于客气的告辞。"}, {"text": "雷雨天气骚扰了电视信号。", "explanation": "这里应该用〈干扰〉。骚扰的对象通常是人或生活环境，信号受影响应说干扰。"}, {"text": "他总是骚扰别人的时间。", "explanation": "这里应该用〈占用〉。骚扰强调打扰他人、使人不安，占用别人的时间应说占用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骚扰", "is_correct": true, "explanation": "骚扰：打扰，使人不安宁。句意是请别人不要用音乐打扰邻居。"}, {"text": "批评", "is_correct": false, "explanation": "语义：音乐不能“批评”人，且句子是请人停止打扰，批评不合语境。"}, {"text": "推广", "is_correct": false, "explanation": "配价：「推广」的宾语多为产品、方法等，不能说推广邻居。"}, {"text": "检查", "is_correct": false, "explanation": "语义：音乐不能检查人，句意与检查无关。"}], "explanations": {"骚扰": "骚扰：打扰，使人不安宁。句意是请别人不要用音乐打扰邻居。", "批评": "语义：音乐不能“批评”人，且句子是请人停止打扰，批评不合语境。", "推广": "配价：「推广」的宾语多为产品、方法等，不能说推广邻居。", "检查": "语义：音乐不能检查人，句意与检查无关。"}, "sentence_index": 6, "correct_answer": "骚扰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次意外骚扰了我们的计划。", "explanation": "这里应该用〈扰乱〉。骚扰多指打扰人、使人不安，计划被打乱应说扰乱。"}, {"text": "警察要负责骚扰社会秩序。", "explanation": "这里应该用〈维护〉。骚扰的对象是人或生活环境，维护秩序不能用骚扰。"}, {"text": "他的粗心骚扰了我们的合作。", "explanation": "这里应该用〈破坏〉。骚扰表示打扰、使人不安，不能用于合作关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "半夜的喇叭声一直骚扰了着邻居。", "corrected_sentence": "半夜的喇叭声一直骚扰着邻居。", "error_description": "“骚扰”后的动态助词用错：不能同时用“了”和“着”。应为“骚扰着”，表示持续的状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骚扰了过邻居很多次。", "corrected_sentence": "他骚扰过邻居很多次。", "error_description": "动态助词重复：“过”已表示经验，前面不能再加“了”，应为“骚扰过邻居很多次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2d230d5-9d27-4f49-a094-6a4240d20be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
