INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "名义上宣称；对外宣称有某种名声。", "primary_collocate": null, "pronunciation": "hào chēng", "ipa": "xau˥˩ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这支队伍号称有一百万人。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学号称是世界一流的。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市号称“千湖之城”。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌军号称有二十万人马。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家网站号称有上亿用户。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她号称“最美老师”，很受学生喜欢。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位厨师号称“面条大王”。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家号称“千岛之国”。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行号称是全国最安全的。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广州号称“花城”。", "target_word": "号称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对外宣称有某种数量或名声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62eac6f8-55d8-4516-a7c5-4d8181c28db1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "号称", "is_correct": true, "explanation": "正确：“号称”表示对外宣称人数，句中是这支队伍的说法，符合句意。"}, {"text": "解散", "is_correct": false, "explanation": "语义：“解散”指队伍散开，不能与“有一百万人”搭配，句中说不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地面等，后面不能接“有一百万人”。"}, {"text": "招募", "is_correct": false, "explanation": "搭配：“招募”是征集人员的动作，后面不接“有一百万人”这样的人数宣称。"}], "explanations": {"号称": "正确：“号称”表示对外宣称人数，句中是这支队伍的说法，符合句意。", "解散": "语义：“解散”指队伍散开，不能与“有一百万人”搭配，句中说不通。", "打扫": "搭配：“打扫”的对象是房间、地面等，后面不能接“有一百万人”。", "招募": "搭配：“招募”是征集人员的动作，后面不接“有一百万人”这样的人数宣称。"}, "sentence_index": 0, "correct_answer": "号称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我号称有五个兄弟姐妹。", "explanation": "这里应该直接陈述事实，不用〈号称〉。“号称”是对外宣称、带有未经证实意味的说法，用来介绍自己家里的确定情况，与语境不符。"}, {"text": "我号称今年二十岁。", "explanation": "这里应该直接陈述年龄，不用〈号称〉。“号称”带有对外宣称、未经证实的意味，用来介绍自己确定的年龄不妥。"}, {"text": "经过核对，这所学校号称确有两千名学生。", "explanation": "这里应该用〈确认〉。已经核实的数量不能用“号称”，它表示未经证实的宣称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "号称", "is_correct": true, "explanation": "正确：“号称”表示对外宣称的名号，句中是厨师自封或外界说的称呼，符合句意。"}, {"text": "授予", "is_correct": false, "explanation": "语义：“授予”的主体应是有权的机构，厨师不能给自己授予称号。"}, {"text": "取笑", "is_correct": false, "explanation": "语义：“取笑”是拿人开玩笑，句中说的是对外宣称的称号，不表示取笑。"}, {"text": "颁发", "is_correct": false, "explanation": "语义：“颁发”指由机构正式发放证书或奖状，与厨师自称的情况不符。"}], "explanations": {"号称": "正确：“号称”表示对外宣称的名号，句中是厨师自封或外界说的称呼，符合句意。", "授予": "语义：“授予”的主体应是有权的机构，厨师不能给自己授予称号。", "取笑": "语义：“取笑”是拿人开玩笑，句中说的是对外宣称的称号，不表示取笑。", "颁发": "语义：“颁发”指由机构正式发放证书或奖状，与厨师自称的情况不符。"}, "sentence_index": 6, "correct_answer": "号称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他号称我这件事是真的。", "explanation": "这里应该用〈告诉〉。“号称”是对外宣扬的说法，不用于向别人转述或说明事情。"}, {"text": "老师号称他的作文写得好。", "explanation": "这里应该用〈夸奖〉。“号称”侧重宣扬某种名声，不表示当面赞扬。"}, {"text": "他号称很爱你，这让我很感动。", "explanation": "这里应该用〈表示〉。号称是对外宣称、带有存疑意味的说法，表达真诚的感情应说“表示”或直接说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司很号称有三千名员工。", "corrected_sentence": "这家公司号称有三千名员工。", "error_description": "错误：“很”放在“号称”前面。“很”不修饰动词“号称”，应去掉“很”，说“号称有三千名员工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座古城号称了有千年历史。", "corrected_sentence": "这座古城号称有千年历史。", "error_description": "错误：“号称”后多加了“了”。“号称”表示对外宣称，不带完成意味，不能加“了”，应说“号称有千年历史”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '294aec55-9074-4681-9a20-a8228b21f69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。"}, {"text": "昨天", "is_correct": false, "explanation": "「昨天」指过去的一天，只是同类时间词，不是「今后」的反义词。"}, {"text": "时候", "is_correct": false, "explanation": "「时候」泛指一段时间，与「今后」并不构成反义。"}, {"text": "清晨", "is_correct": false, "explanation": "「清晨」指一天中的一个时段，与「今后」不是反义关系。"}], "correct_answer": "以前", "explanations": {"以前": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。", "昨天": "「昨天」指过去的一天，只是同类时间词，不是「今后」的反义词。", "时候": "「时候」泛指一段时间，与「今后」并不构成反义。", "清晨": "「清晨」指一天中的一个时段，与「今后」不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。"}, {"text": "星期", "is_correct": false, "explanation": "「星期」是一周的时间单位，与「今后」不构成反义。"}, {"text": "时代", "is_correct": false, "explanation": "「时代」指历史阶段，与「今后」不是反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "「周末」指一周的休息日，与「今后」不是反义关系。"}], "correct_answer": "以前", "explanations": {"以前": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。", "星期": "「星期」是一周的时间单位，与「今后」不构成反义。", "时代": "「时代」指历史阶段，与「今后」不是反义关系。", "周末": "「周末」指一周的休息日，与「今后」不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今后是从今天开始，以后的日子。", "primary_collocate": null, "pronunciation": "jīn hòu", "ipa": "tɕin˥˥ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "今后的日子，我们一起努力。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后的生活会越来越好。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说今后每天都要早起。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后你有什么打算？", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今后的路要靠你自己走。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师告诉我们，今后要多读书。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬到这里，今后我们就是邻居了。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后的几年，这个城市会变得更大。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想好了今后的计划。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道今后会怎么样。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "今後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "今后：指从今天开始的以后的日子，常说今后的日子、生活、路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2534af2a-1516-45ed-a22b-20f025827a87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今后", "is_correct": true, "explanation": "正确：「今后」指从现在往后的时间，与「一起努力」的将来含义相合。"}, {"text": "以前", "is_correct": false, "explanation": "语义：「以前」指过去，与「一起努力」面向将来的意思相反。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：「昨天」只指一天，不能修饰「日子」这样的长时段。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：「年代」指某个十年的历史时期，不能泛指「的日子」。"}], "explanations": {"今后": "正确：「今后」指从现在往后的时间，与「一起努力」的将来含义相合。", "以前": "语义：「以前」指过去，与「一起努力」面向将来的意思相反。", "昨天": "搭配：「昨天」只指一天，不能修饰「日子」这样的长时段。", "年代": "搭配：「年代」指某个十年的历史时期，不能泛指「的日子」。"}, "sentence_index": 0, "correct_answer": "今后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃完饭今后去散步。", "explanation": "这里应该用〈以后〉。今后从现在往后算，不能表示紧接在某个动作之后的先后，此处要用〈以后〉。"}, {"text": "今后，他去了北京工作。", "explanation": "这里应该用〈后来〉。「去了」说的是已经发生的事，而今后只指从现在往后，不能用于过去。"}, {"text": "他把碗洗好，今后马上出门。", "explanation": "这里应该用〈然后〉。今后指从现在往后，不能连接刚做完的动作；「马上」的即时义也与「今后」的长远义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今后", "is_correct": true, "explanation": "正确：「今后」表示从搬来之后开始的时间，与「就是邻居了」的先后关系相合。"}, {"text": "时代", "is_correct": false, "explanation": "搭配：「时代」是泛指的历史阶段，不能直接作「就是邻居」的时间状语。"}, {"text": "从前", "is_correct": false, "explanation": "语义：「从前」指往昔，与「搬到这里」之后才成为邻居的先后关系矛盾。"}, {"text": "假期", "is_correct": false, "explanation": "语义：「假期」是休假的时段，与搬家后成为邻居的情况无关。"}], "explanations": {"今后": "正确：「今后」表示从搬来之后开始的时间，与「就是邻居了」的先后关系相合。", "时代": "搭配：「时代」是泛指的历史阶段，不能直接作「就是邻居」的时间状语。", "从前": "语义：「从前」指往昔，与「搬到这里」之后才成为邻居的先后关系矛盾。", "假期": "语义：「假期」是休假的时段，与搬家后成为邻居的情况无关。"}, "sentence_index": 6, "correct_answer": "今后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今后，警察赶到了现场。", "explanation": "这里应该用〈随后〉。今后只指从现在往后，而「赶到了」说的是已经发生的事。"}, {"text": "我们先检查行李，今后马上出发。", "explanation": "这里应该用〈接着〉。今后指从现在往后，不能表示检查行李之后紧接着出发；「马上」的即时义也与「今后」矛盾。"}, {"text": "今后，他向大家道了歉。", "explanation": "这里应该用〈事后〉。「道了歉」是已经完成的事，今后指将来，不能表示事后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今后地生活，我们一起努力。", "corrected_sentence": "今后的生活，我们一起努力。", "error_description": "错误形式：「今后地生活，我们一起努力」；正确形式：「今后的生活，我们一起努力」。「今后」作定语修饰名词「生活」时须用「的」，误用「地」（「地」用于修饰动词、形容词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今后了我每天早起。", "corrected_sentence": "今后我每天早起。", "error_description": "错误形式：「今后了我每天早起」；正确形式：「今后我每天早起」。「今后」是时间词，后面不能加「了」，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。"}, {"text": "昨天", "is_correct": false, "explanation": "「昨天」指过去的一天，只是同类时间词，不是「今后」的反义词。"}, {"text": "时候", "is_correct": false, "explanation": "「时候」泛指一段时间，与「今后」并不构成反义。"}, {"text": "清晨", "is_correct": false, "explanation": "「清晨」指一天中的一个时段，与「今后」不是反义关系。"}], "correct_answer": "以前", "explanations": {"以前": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。", "昨天": "「昨天」指过去的一天，只是同类时间词，不是「今后」的反义词。", "时候": "「时候」泛指一段时间，与「今后」并不构成反义。", "清晨": "「清晨」指一天中的一个时段，与「今后」不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。"}, {"text": "星期", "is_correct": false, "explanation": "「星期」是一周的时间单位，与「今后」不构成反义。"}, {"text": "时代", "is_correct": false, "explanation": "「时代」指历史阶段，与「今后」不是反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "「周末」指一周的休息日，与「今后」不是反义关系。"}], "correct_answer": "以前", "explanations": {"以前": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。", "星期": "「星期」是一周的时间单位，与「今后」不构成反义。", "时代": "「时代」指历史阶段，与「今后」不是反义关系。", "周末": "「周末」指一周的休息日，与「今后」不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从现在起往后的时间。", "primary_collocate": null, "pronunciation": "jīn hòu", "ipa": "tɕin˥˥ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "今后请大家准时上课。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今后我一定注意身体。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司说，今后不再发纸质通知。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后一个月，我每天跑步。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后他再也不迟到了。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后有问题，请直接给我打电话。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我保证，今后不会再犯同样的错误。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后天气会越来越冷。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校规定今后不能带手机进教室。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你今后想做什么工作？", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "今後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "今后：作时间词放在句首或主语后，表示从现在起往后的时间，常引出打算、保证、规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2534af2a-1516-45ed-a22b-20f025827a87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今后", "is_correct": true, "explanation": "正确：「今后」指从现在起往后，与「请大家准时上课」的规定相合。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：「昨天」指已过去的一天，与「请大家准时上课」的规定不相符。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：「星期」是时间单位，不能直接作这样的时间状语。"}, {"text": "时代", "is_correct": false, "explanation": "搭配：「时代」泛指历史阶段，不能作「请大家准时上课」的时间状语。"}], "explanations": {"今后": "正确：「今后」指从现在起往后，与「请大家准时上课」的规定相合。", "昨天": "语义：「昨天」指已过去的一天，与「请大家准时上课」的规定不相符。", "星期": "搭配：「星期」是时间单位，不能直接作这样的时间状语。", "时代": "搭配：「时代」泛指历史阶段，不能作「请大家准时上课」的时间状语。"}, "sentence_index": 0, "correct_answer": "今后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我考完试今后去旅行。", "explanation": "这里应该用〈以后〉。今后从现在往后算，不能表示紧接在考试之后的先后，此处要用〈以后〉。"}, {"text": "今后，妈妈回了老家。", "explanation": "这里应该用〈后来〉。「回了老家」说的是已经发生的事，今后只指从现在往后。"}, {"text": "他洗完澡，今后马上睡觉。", "explanation": "这里应该用〈然后〉。今后指从现在往后，不能表示洗完澡之后紧接着的动作；「马上」的即时义也与「今后」的长远义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今后", "is_correct": true, "explanation": "正确：「今后」指从现在往后，与「保证」面向将来的语气相合。"}, {"text": "过去", "is_correct": false, "explanation": "语义：「过去」指已经发生的时间，与「保证不会再犯」的将来承诺相矛盾。"}, {"text": "时候", "is_correct": false, "explanation": "搭配：「时候」是泛指的时段，不能单独作「不会再犯」的时间状语。"}, {"text": "从前", "is_correct": false, "explanation": "语义：「从前」指往昔，与「保证」面向将来的语气不合。"}], "explanations": {"今后": "正确：「今后」指从现在往后，与「保证」面向将来的语气相合。", "过去": "语义：「过去」指已经发生的时间，与「保证不会再犯」的将来承诺相矛盾。", "时候": "搭配：「时候」是泛指的时段，不能单独作「不会再犯」的时间状语。", "从前": "语义：「从前」指往昔，与「保证」面向将来的语气不合。"}, "sentence_index": 6, "correct_answer": "今后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今后，他签了合同。", "explanation": "这里应该用〈随后〉。今后只指从现在往后，而「签了合同」是已经发生的事。"}, {"text": "他签完字，今后离开办公室。", "explanation": "这里应该用〈接着〉。今后指从现在往后，不能表示签字之后紧接着离开，此处要用〈接着〉。"}, {"text": "今后，我们总结了经验。", "explanation": "这里应该用〈事后〉。「总结了经验」是已经完成的事，今后指将来，不能表示事后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今后地工作，我会好好努力。", "corrected_sentence": "今后的工作，我会好好努力。", "error_description": "错误形式：「今后地工作，我会好好努力」；正确形式：「今后的工作，我会好好努力」。「今后」作定语修饰名词「工作」时须用「的」，误用「地」（「地」用于修饰动词、形容词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今后了我们要多锻炼身体。", "corrected_sentence": "今后我们要多锻炼身体。", "error_description": "错误形式：「今后了我们要多锻炼身体」；正确形式：「今后我们要多锻炼身体」。「今后」是时间词，后面不能加「了」，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
