INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92537, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把人或动物赶走。", "primary_collocate": null, "pronunciation": "qū zhú", "ipa": "tɕʰy˥ ʈʂu˧˥", "syllable_count": 2, "sentences": [{"text": "农民驱逐了田里的麻雀。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着棍子驱逐野狗。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧民用火驱逐靠近的狼。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安驱逐了门口的小贩。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民驱逐了围着船的海鸟。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想办法驱逐老鼠。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把野猪驱逐出了村子。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "响声可以驱逐山里的野兽。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主人驱逐了闯进院子的人。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧羊人驱逐了偷羊的狐狸。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "驱逐了", "label": "体标"}, {"form": "驱逐过", "label": "体标"}, {"form": "驱逐出境", "label": "复合词"}, {"form": "驅逐", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把人或动物赶走，使其离开某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "驱逐", "is_correct": true, "explanation": "驱逐：把田里的麻雀赶走，符合句意。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”指割取庄稼，麻雀不是庄稼，不能说收割麻雀。"}, {"text": "栽培", "is_correct": false, "explanation": "搭配：“栽培”用于植物或人才，不能用于麻雀。"}, {"text": "雇佣", "is_correct": false, "explanation": "搭配：“雇佣”的对象是人，不能说雇佣麻雀。"}], "explanations": {"驱逐": "驱逐：把田里的麻雀赶走，符合句意。", "收割": "语义：“收割”指割取庄稼，麻雀不是庄稼，不能说收割麻雀。", "栽培": "搭配：“栽培”用于植物或人才，不能用于麻雀。", "雇佣": "搭配：“雇佣”的对象是人，不能说雇佣麻雀。"}, "sentence_index": 0, "correct_answer": "驱逐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用吸尘器驱逐了房间里的灰尘。", "explanation": "这里应该用〈驱除〉。驱逐的对象通常是人或动物，灰尘等无生命之物要用驱除。"}, {"text": "他驱逐了原来的公司，自己创业去了。", "explanation": "这里应该用〈离开〉。驱逐是强迫别人离开，自己主动走开要说离开，不能用驱逐。"}, {"text": "我们驱逐了远行的朋友。", "explanation": "这里应该用〈送别〉。驱逐是强迫赶走，朋友远行是自己离开，应说送别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驱逐", "is_correct": true, "explanation": "驱逐：把野猪赶出村子，符合句意。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”指用火加热食物，不能表示把野猪赶出村子。"}, {"text": "观察", "is_correct": false, "explanation": "配价：“观察”的宾语是对象或现象，不能带“出村子”这样的处所补语。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”多用于景物或作品，不能说把野猪欣赏出村子。"}], "explanations": {"驱逐": "驱逐：把野猪赶出村子，符合句意。", "烤": "语义：“烤”指用火加热食物，不能表示把野猪赶出村子。", "观察": "配价：“观察”的宾语是对象或现象，不能带“出村子”这样的处所补语。", "欣赏": "搭配：“欣赏”多用于景物或作品，不能说把野猪欣赏出村子。"}, "sentence_index": 6, "correct_answer": "驱逐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农夫驱逐耕牛去耕地。", "explanation": "这里应该用〈驱使〉。驱逐是赶走，驱使是赶着去做事，耕牛是被使唤干活，不是被赶走。"}, {"text": "他们驱逐了重重困难。", "explanation": "这里应该用〈克服〉。驱逐的对象是人、动物或外来势力，困难要说克服。"}, {"text": "他驱逐了心中的希望。", "explanation": "这里应该用〈保持〉。驱逐的对象是人或动物，“希望”是心里的想法，而且应当留住，不能说驱逐希望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民用棍子把野狗驱逐了院子。", "corrected_sentence": "农民用棍子把野狗驱逐出了院子。", "error_description": "“驱逐”后漏了趋向补语“出”。表示把野狗赶出某处，应说“驱逐出了院子”；只说“驱逐了院子”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用石头把狼驱逐了出田地。", "corrected_sentence": "他们用石头把狼驱逐出了田地。", "error_description": "“了”放错位置。“驱逐出”是动补结构，“了”应放在整个动补之后，说“驱逐出了田地”，不能说“驱逐了出田地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
