INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92538, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "强迫离开；赶走。", "primary_collocate": null, "pronunciation": "qū zhú", "ipa": "tɕʰy˥ ʈʂu˧˥", "syllable_count": 2, "sentences": [{"text": "政府驱逐了那位外国记者。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东驱逐了不交钱的房客。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察驱逐了广场上的小贩。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家决定驱逐非法入境的人。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们驱逐了村里的外来人。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把偷东西的学生驱逐出了校园。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家驱逐了三位外交官。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队把当地居民驱逐出家园。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们驱逐了捣乱的陌生人。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院下令驱逐那户拖欠房租的租客。", "target_word": "驱逐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "驱逐了", "label": "体标"}, {"form": "驱逐过", "label": "体标"}, {"form": "驱逐出境", "label": "复合词"}, {"form": "驅逐", "label": "繁体"}], "register": "书面", "sense_fingerprint": "以权力或强制手段迫使人离开某地或某个范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8986b3-b2f6-4123-8222-d26c9cd9393b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "驱逐", "is_correct": true, "explanation": "驱逐：强制赶出国境或某地，符合句意。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：“砍伐”指砍倒树木，不能用于人。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能说种植记者。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，不能说饲养人。"}], "explanations": {"驱逐": "驱逐：强制赶出国境或某地，符合句意。", "砍伐": "语义：“砍伐”指砍倒树木，不能用于人。", "种植": "搭配：“种植”的对象是植物，不能说种植记者。", "饲养": "搭配：“饲养”的对象是动物，不能说饲养人。"}, "sentence_index": 0, "correct_answer": "驱逐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人驱逐了路面上的积雪。", "explanation": "这里应该用〈清除〉。驱逐的对象是人或动物，积雪这类无生命之物要用清除。"}, {"text": "他驱逐了远行的老同学。", "explanation": "这里应该用〈送别〉。驱逐是强迫赶走，老同学远行是自己离开，应说送别。"}, {"text": "公司驱逐了那份过期的合同。", "explanation": "这里应该用〈作废〉。驱逐的对象是人或动物，过期合同是文件，应说作废。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驱逐", "is_correct": true, "explanation": "驱逐：强制赶走外交官，符合句意。"}, {"text": "放牧", "is_correct": false, "explanation": "语义：“放牧”指放养牲畜，不能用于外交官。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、头发等，不能说修剪外交官。"}, {"text": "灌溉", "is_correct": false, "explanation": "搭配：“灌溉”的对象是田地或作物，不能说灌溉外交官。"}], "explanations": {"驱逐": "驱逐：强制赶走外交官，符合句意。", "放牧": "语义：“放牧”指放养牲畜，不能用于外交官。", "修剪": "搭配：“修剪”用于枝叶、头发等，不能说修剪外交官。", "灌溉": "搭配：“灌溉”的对象是田地或作物，不能说灌溉外交官。"}, "sentence_index": 6, "correct_answer": "驱逐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他驱逐了心中的希望。", "explanation": "这里应该用〈保持〉。驱逐是赶走不需要的东西，希望应当留住，用驱逐与句意相反。"}, {"text": "警察驱逐了那起抢劫案。", "explanation": "这里应该用〈侦破〉。驱逐的对象是人或动物，案件要说侦破，不能说驱逐。"}, {"text": "农夫驱逐马匹运货。", "explanation": "这里应该用〈驱使〉。驱逐是赶走，驱使是赶着干活，马匹被使唤运货，不是被赶走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府把那名外国记者驱逐出境着。", "corrected_sentence": "政府把那名外国记者驱逐出境了。", "error_description": "体标“着”用错。“驱逐出境”是已完成的动作，应用“了”，说“驱逐出境了”；“着”表示持续状态，不能说“驱逐出境着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个醉汉驱逐出了酒吧。", "corrected_sentence": "那个醉汉被保安驱逐出了酒吧。", "error_description": "漏了被动标记“被”。“驱逐”的对象是醉汉，应用“被”字句，说“被保安驱逐出了酒吧”；“醉汉驱逐出了酒吧”是主动式，意思不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d75e0-6e6b-44b8-a337-cd25b194b54f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
