INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92545, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "制版是做出印刷用的版。", "primary_collocate": null, "pronunciation": "zhì bǎn", "ipa": "tʂɻ̩⁵¹ pan²¹⁴", "syllable_count": 2, "sentences": [{"text": "工人正在给新书制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志下周开始制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制版以后才能印刷。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷厂的老师傅制版又快又好。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在印刷厂学过制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张海报的图片要先制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅用电脑给报纸制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制版完成后，机器开始印书。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得先制版，再印一千本。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在印刷厂里制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制版师", "label": "复合"}, {"form": "制版工艺", "label": "复合"}, {"form": "製版", "label": "繁体"}], "register": "中性", "sense_fingerprint": "印刷前做出印刷用的版", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92545, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "制版", "is_correct": true, "explanation": "正确。制版指做印刷用的版，是印刷前的一道工序。"}, {"text": "纸板", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，纸板指用纸做的硬板，意思不同。"}, {"text": "直板", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，直板指形状平直的板子，意思不同。"}, {"text": "置办", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，置办指购置、准备物品，意思不同。"}, {"text": "治本", "is_correct": false, "explanation": "běn 与 bǎn 韵母不同（en 与 an），治本指从根本上解决问题，意思不同。"}, {"text": "试版", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），试版指试印的版本，意思不同。"}], "explanations": {"制版": "正确。制版指做印刷用的版，是印刷前的一道工序。", "纸板": "zhǐ（第三声）与 zhì（第四声）声调不同，纸板指用纸做的硬板，意思不同。", "直板": "zhí（第二声）与 zhì（第四声）声调不同，直板指形状平直的板子，意思不同。", "置办": "bàn（第四声）与 bǎn（第三声）声调不同，置办指购置、准备物品，意思不同。", "治本": "běn 与 bǎn 韵母不同（en 与 an），治本指从根本上解决问题，意思不同。", "试版": "shì 与 zhì 声母不同（sh 与 zh），试版指试印的版本，意思不同。"}, "sentence_index": null, "correct_answer": "制版"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是衣物、身体等，不能用来洗新书。"}, {"text": "制版", "is_correct": true, "explanation": "正确。给新书做印刷用的版，符合句中语境。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”要把内容讲给人听，不能说“给新书讲”。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”用于衣物等织物，不能用于书。"}], "explanations": {"洗": "语义：“洗”的对象是衣物、身体等，不能用来洗新书。", "制版": "正确。给新书做印刷用的版，符合句中语境。", "讲": "搭配：“讲”要把内容讲给人听，不能说“给新书讲”。", "烫": "语义：“烫”用于衣物等织物，不能用于书。"}, "sentence_index": 0, "correct_answer": "制版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用纸箱制版了一个小房子。", "explanation": "这里应该用〈制作〉。制版专指做印刷用的版，用纸箱做房子要用制作。"}, {"text": "学校制版了新的规章。", "explanation": "这里应该用〈制定〉。制版只用于印刷版面，制订规章要用制定。"}, {"text": "这家窑厂制版了一百个碗。", "explanation": "这里应该用〈烧制〉。制版指做印刷用的版，烧制瓷碗要用烧制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92545, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：“煮”用于食物，不能用来煮报纸。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”一般用于食物，不说烤报纸。"}, {"text": "制版", "is_correct": true, "explanation": "正确。用电脑给报纸做印刷用的版，符合句中语境。"}, {"text": "炒", "is_correct": false, "explanation": "语义：“炒”用于菜肴等食物，报纸不能炒。"}], "explanations": {"煮": "语义：“煮”用于食物，不能用来煮报纸。", "烤": "搭配：“烤”一般用于食物，不说烤报纸。", "制版": "正确。用电脑给报纸做印刷用的版，符合句中语境。", "炒": "语义：“炒”用于菜肴等食物，报纸不能炒。"}, "sentence_index": 6, "correct_answer": "制版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用毛线制版了一件新衣服。", "explanation": "这里应该用〈缝制〉。制版指做印刷版面，做衣服要用缝制。"}, {"text": "这家工厂制版了一千辆汽车。", "explanation": "这里应该用〈制造〉。制版只用于印刷版面，生产汽车要用制造。"}, {"text": "这位工程师制版了一座新桥。", "explanation": "这里应该用〈设计〉。制版只用于印刷版面，设计桥梁要用设计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经制版过了。", "corrected_sentence": "我们已经制过版了。", "error_description": "“过”应紧接动词“制”，说“制过版”；说“制版过”把“过”放到宾语之后，是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经制版完了。", "corrected_sentence": "他们已经制完版了。", "error_description": "“完”是结果补语，应紧接动词“制”，说“制完版”；说“制版完”把补语放在宾语之后，是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
