INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "制作印刷用的版面。", "primary_collocate": null, "pronunciation": "zhì bǎn", "ipa": "tʂɻ̩⁵¹ pan²¹⁴", "syllable_count": 2, "sentences": [{"text": "设计师正在为这本画册制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑今天要给新报纸制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会用软件给杂志制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制版时，文字和图片要放整齐。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "封面做好了，现在可以制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学习怎么给海报制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请他给菜单制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份传单还没制版呢。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她制版时很细心。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你明天上午前给报纸制版。", "target_word": "制版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制版师", "label": "复合"}, {"form": "制版工艺", "label": "复合"}, {"form": "製版", "label": "繁体"}], "register": "中性", "sense_fingerprint": "排好文字图片，做出印刷用的版面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
